//! DJI `.DAT` Blackbox IMU Attitude & Kinematics Telemetry Decoder (Payload ID 0x01).
//!
//! Provides zero-allocation decoding of quaternions, angular gyro rates,
//! body accelerations, and NED velocity vectors from on-board blackbox recordings.
//!
//! Strictly adheres to `#![deny(unsafe_code)]` with zero `unsafe` blocks.

use byteorder::{ByteOrder, LittleEndian};

use crate::error::{FlightReaderError, Result};

/// Minimum payload length in bytes required to decode basic IMU attitude quaternions.
pub const MIN_IMU_PAYLOAD_LEN: usize = 16;

/// Standard payload length in bytes for full IMU attitude, gyro, accel, and NED velocity.
pub const FULL_IMU_PAYLOAD_LEN: usize = 52;

/// Decoded IMU Attitude, Angular Rates, Body Accelerations, and Velocities.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct DatImuRecord {
    /// Quaternion w-component ($q_0$).
    pub q0: f32,
    /// Quaternion x-component ($q_1$).
    pub q1: f32,
    /// Quaternion y-component ($q_2$).
    pub q2: f32,
    /// Quaternion z-component ($q_3$).
    pub q3: f32,
    /// Roll angular gyro rate in radians per second (body x-axis).
    pub gyro_x: f32,
    /// Pitch angular gyro rate in radians per second (body y-axis).
    pub gyro_y: f32,
    /// Yaw angular gyro rate in radians per second (body z-axis).
    pub gyro_z: f32,
    /// Body acceleration along x-axis in $m/s^2$.
    pub accel_x: f32,
    /// Body acceleration along y-axis in $m/s^2$.
    pub accel_y: f32,
    /// Body acceleration along z-axis in $m/s^2$.
    pub accel_z: f32,
    /// North velocity in meters per second ($v_n$).
    pub vel_n: f32,
    /// East velocity in meters per second ($v_e$).
    pub vel_e: f32,
    /// Down velocity in meters per second ($v_d$).
    pub vel_d: f32,
}

impl DatImuRecord {
    /// Parses a `.DAT` Payload ID 0x01 byte slice into a [`DatImuRecord`].
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() < MIN_IMU_PAYLOAD_LEN {
            return Err(FlightReaderError::PayloadTooShort {
                minimum: MIN_IMU_PAYLOAD_LEN,
                available: payload.len(),
            });
        }

        let q0 = LittleEndian::read_f32(&payload[0..4]);
        let q1 = LittleEndian::read_f32(&payload[4..8]);
        let q2 = LittleEndian::read_f32(&payload[8..12]);
        let q3 = LittleEndian::read_f32(&payload[12..16]);

        let (gyro_x, gyro_y, gyro_z) = if payload.len() >= 28 {
            (
                LittleEndian::read_f32(&payload[16..20]),
                LittleEndian::read_f32(&payload[20..24]),
                LittleEndian::read_f32(&payload[24..28]),
            )
        } else {
            (0.0, 0.0, 0.0)
        };

        let (accel_x, accel_y, accel_z) = if payload.len() >= 40 {
            (
                LittleEndian::read_f32(&payload[28..32]),
                LittleEndian::read_f32(&payload[32..36]),
                LittleEndian::read_f32(&payload[36..40]),
            )
        } else {
            (0.0, 0.0, 0.0)
        };

        let (vel_n, vel_e, vel_d) = if payload.len() >= 52 {
            (
                LittleEndian::read_f32(&payload[40..44]),
                LittleEndian::read_f32(&payload[44..48]),
                LittleEndian::read_f32(&payload[48..52]),
            )
        } else {
            (0.0, 0.0, 0.0)
        };

        Ok(Self {
            q0,
            q1,
            q2,
            q3,
            gyro_x,
            gyro_y,
            gyro_z,
            accel_x,
            accel_y,
            accel_z,
            vel_n,
            vel_e,
            vel_d,
        })
    }

    /// Computes pitch attitude angle in degrees from quaternions.
    #[must_use]
    pub fn pitch_deg(&self) -> f32 {
        let sinp = 2.0 * (self.q0 * self.q2 - self.q3 * self.q1);
        if sinp.abs() >= 1.0 {
            std::f32::consts::FRAC_PI_2.copysign(sinp).to_degrees()
        } else {
            sinp.asin().to_degrees()
        }
    }

    /// Computes roll attitude angle in degrees from quaternions.
    #[must_use]
    pub fn roll_deg(&self) -> f32 {
        let sinr_cosp = 2.0 * (self.q0 * self.q1 + self.q2 * self.q3);
        let cosr_cosp = 1.0 - 2.0 * (self.q1 * self.q1 + self.q2 * self.q2);
        sinr_cosp.atan2(cosr_cosp).to_degrees()
    }

    /// Computes yaw heading angle in degrees ($-180^\circ \dots +180^\circ$) from quaternions.
    #[must_use]
    pub fn yaw_deg(&self) -> f32 {
        let siny_cosp = 2.0 * (self.q0 * self.q3 + self.q1 * self.q2);
        let cosy_cosp = 1.0 - 2.0 * (self.q2 * self.q2 + self.q3 * self.q3);
        siny_cosp.atan2(cosy_cosp).to_degrees()
    }

    /// Computes horizontal ground speed in meters per second ($V_h = \sqrt{v_n^2 + v_e^2}$).
    #[inline]
    #[must_use]
    pub fn horizontal_speed(&self) -> f32 {
        self.vel_n.hypot(self.vel_e)
    }

    /// Computes 3D flight speed in meters per second ($V_{3D} = \sqrt{v_n^2 + v_e^2 + v_d^2}$).
    #[inline]
    #[must_use]
    pub fn speed_3d(&self) -> f32 {
        self.vel_n.hypot(self.vel_e).hypot(self.vel_d)
    }

    /// Computes vertical climb rate in meters per second ($-v_d$, positive = climbing).
    #[inline]
    #[must_use]
    pub fn climb_rate(&self) -> f32 {
        -self.vel_d
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_imu_parse_full_payload() {
        let mut buf = [0u8; 52];
        // Quaternions: unit quaternion identity (q0 = 1.0, q1=0, q2=0, q3=0)
        LittleEndian::write_f32(&mut buf[0..4], 1.0);
        LittleEndian::write_f32(&mut buf[4..8], 0.0);
        LittleEndian::write_f32(&mut buf[8..12], 0.0);
        LittleEndian::write_f32(&mut buf[12..16], 0.0);

        // Gyros: 0.1, 0.2, 0.3 rad/s
        LittleEndian::write_f32(&mut buf[16..20], 0.1);
        LittleEndian::write_f32(&mut buf[20..24], 0.2);
        LittleEndian::write_f32(&mut buf[24..28], 0.3);

        // Accels: 0.0, 0.0, 9.81 m/s^2
        LittleEndian::write_f32(&mut buf[28..32], 0.0);
        LittleEndian::write_f32(&mut buf[32..36], 0.0);
        LittleEndian::write_f32(&mut buf[36..40], 9.81);

        // Velocities: vn=12.0, ve=16.0, vd=-5.0 m/s
        LittleEndian::write_f32(&mut buf[40..44], 12.0);
        LittleEndian::write_f32(&mut buf[44..48], 16.0);
        LittleEndian::write_f32(&mut buf[48..52], -5.0);

        let rec = DatImuRecord::parse(&buf).unwrap();
        assert_eq!(rec.q0, 1.0);
        assert_eq!(rec.q1, 0.0);
        assert_eq!(rec.q2, 0.0);
        assert_eq!(rec.q3, 0.0);

        assert_eq!(rec.gyro_x, 0.1);
        assert_eq!(rec.accel_z, 9.81);

        assert_eq!(rec.vel_n, 12.0);
        assert_eq!(rec.vel_e, 16.0);
        assert_eq!(rec.vel_d, -5.0);

        assert!((rec.pitch_deg() - 0.0).abs() < 1e-4);
        assert!((rec.roll_deg() - 0.0).abs() < 1e-4);
        assert!((rec.yaw_deg() - 0.0).abs() < 1e-4);

        assert!((rec.horizontal_speed() - 20.0).abs() < 1e-4);
        assert_eq!(rec.climb_rate(), 5.0);
    }

    #[test]
    fn test_imu_parse_truncated_error() {
        let buf = [0u8; 15];
        assert_eq!(
            DatImuRecord::parse(&buf).unwrap_err(),
            FlightReaderError::PayloadTooShort {
                minimum: 16,
                available: 15,
            }
        );
    }
}

//! DJI `.DAT` Blackbox Motor & ESC Diagnostics Telemetry Decoder (Payload ID 0x12 / 18).
//!
//! Provides zero-allocation decoding of real-time rotor RPMs, ESC bus input voltages,
//! phase currents, power stage temperatures, and PWM duty cycles for up to 8 rotors.
//!
//! Strictly adheres to `#![deny(unsafe_code)]` with zero `unsafe` blocks.

use byteorder::{ByteOrder, LittleEndian};

use crate::error::{FlightReaderError, Result};

/// Minimum payload length in bytes required to decode rotor RPM telemetry (at least 4 motors).
pub const MIN_MOTOR_PAYLOAD_LEN: usize = 8;

/// Decoded Motor & ESC real-time diagnostics.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct DatMotorRecord {
    /// Real-time rotor rotational speed in revolutions per minute (RPM) for motors 1 through 8.
    pub rotor_rpm: [u16; 8],
    /// ESC input bus voltage in volts for motors 1 through 8.
    pub esc_voltage_v: [f32; 8],
    /// ESC phase current draw in amperes for motors 1 through 8.
    pub esc_current_a: [f32; 8],
    /// ESC MOSFET power stage temperature in degrees Celsius for motors 1 through 8.
    pub esc_temp_c: [i8; 8],
    /// ESC PWM command duty cycle percentage (0.0% to 100.0%) for motors 1 through 8.
    pub pwm_duty_percent: [f32; 8],
}

impl DatMotorRecord {
    /// Parses a `.DAT` Payload ID 0x12 byte slice into a [`DatMotorRecord`].
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() < MIN_MOTOR_PAYLOAD_LEN {
            return Err(FlightReaderError::PayloadTooShort {
                minimum: MIN_MOTOR_PAYLOAD_LEN,
                available: payload.len(),
            });
        }

        let mut rotor_rpm = [0u16; 8];
        let mut esc_voltage_v = [0.0f32; 8];
        let mut esc_current_a = [0.0f32; 8];
        let mut esc_temp_c = [0i8; 8];
        let mut pwm_duty_percent = [0.0f32; 8];

        // Decode RPMs (up to 8 motors, 2 bytes each)
        let rpm_motors = (payload.len() / 2).min(8);
        for i in 0..rpm_motors {
            rotor_rpm[i] = LittleEndian::read_u16(&payload[i * 2..(i + 1) * 2]);
        }

        // Decode ESC voltages (offset 16..32, 2 bytes each in 0.1V or mV)
        if payload.len() >= 32 {
            for i in 0..8 {
                let raw_v = LittleEndian::read_u16(&payload[16 + i * 2..16 + (i + 1) * 2]);
                esc_voltage_v[i] = f32::from(raw_v) / 10.0;
            }
        }

        // Decode ESC currents (offset 32..48, 2 bytes each in 0.1A)
        if payload.len() >= 48 {
            for i in 0..8 {
                let raw_i = LittleEndian::read_i16(&payload[32 + i * 2..32 + (i + 1) * 2]);
                esc_current_a[i] = f32::from(raw_i) / 10.0;
            }
        }

        // Decode ESC temperatures (offset 48..56, 1 byte signed per motor)
        if payload.len() >= 56 {
            for i in 0..8 {
                esc_temp_c[i] = payload[48 + i] as i8;
            }
        }

        // Decode PWM duty cycles (offset 56..72, 2 bytes each in 0.1%)
        if payload.len() >= 72 {
            for i in 0..8 {
                let raw_pwm = LittleEndian::read_u16(&payload[56 + i * 2..56 + (i + 1) * 2]);
                pwm_duty_percent[i] = f32::from(raw_pwm) / 10.0;
            }
        }

        Ok(Self {
            rotor_rpm,
            esc_voltage_v,
            esc_current_a,
            esc_temp_c,
            pwm_duty_percent,
        })
    }

    /// Returns the average rotor RPM across all active non-zero motors.
    #[must_use]
    pub fn average_active_rpm(&self) -> f32 {
        let mut sum = 0u32;
        let mut count = 0u32;
        for &rpm in &self.rotor_rpm {
            if rpm > 0 {
                sum += u32::from(rpm);
                count += 1;
            }
        }
        if count == 0 {
            0.0
        } else {
            sum as f32 / count as f32
        }
    }

    /// Checks if any rotor RPM is spinning above idle speed (> 1,200 RPM),
    /// used to synchronize with mobile log motor-start events per Section 6.5 of `SPECS.md`.
    #[inline]
    #[must_use]
    pub fn is_motor_spinning(&self) -> bool {
        self.rotor_rpm.iter().any(|&rpm| rpm > 1200)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_motor_parse_quadcopter_rpm() {
        let mut buf = [0u8; 16];
        LittleEndian::write_u16(&mut buf[0..2], 5200);
        LittleEndian::write_u16(&mut buf[2..4], 5250);
        LittleEndian::write_u16(&mut buf[4..6], 5180);
        LittleEndian::write_u16(&mut buf[6..8], 5220);

        let rec = DatMotorRecord::parse(&buf).unwrap();
