                available: 7,
            }
        );
    }
}

//! DJI `.DAT` Blackbox Smart Battery Diagnostics Telemetry Decoder (Payload ID 0x0A / 10).
//!
//! Provides zero-allocation decoding of total pack voltage, instantaneous current draw,
//! battery pack temperature, state of charge, individual cell voltages, and internal resistances.
//!
//! Strictly adheres to `#![deny(unsafe_code)]` with zero `unsafe` blocks.

use byteorder::{ByteOrder, LittleEndian};

use crate::error::{FlightReaderError, Result};

/// Minimum payload length in bytes required to decode basic battery pack diagnostics.
pub const MIN_DAT_BATTERY_PAYLOAD_LEN: usize = 11;

/// Decoded Smart Battery Diagnostics from on-board `.DAT` blackbox recordings.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct DatBatteryRecord {
    /// Total pack voltage in millivolts.
    pub total_voltage_mv: u32,
    /// Instantaneous battery current draw in milliamperes (negative indicates discharge).
    pub current_ma: i32,
    /// Battery pack temperature in degrees Celsius.
    pub temperature_c: f32,
    /// State of charge percentage (0% to 100%).
    pub soc_percent: u8,
    /// Individual cell voltages in millivolts for cells 1 through 12.
    pub cell_voltages_mv: [u16; 12],
    /// Individual cell internal resistances in milliohms ($m\Omega$) for cells 1 through 12.
    pub cell_resistances_mohm: [u16; 12],
}

impl DatBatteryRecord {
    /// Parses a `.DAT` Payload ID 0x0A byte slice into a [`DatBatteryRecord`].
    pub fn parse(payload: &[u8]) -> Result<Self> {
        if payload.len() < MIN_DAT_BATTERY_PAYLOAD_LEN {
            return Err(FlightReaderError::PayloadTooShort {
                minimum: MIN_DAT_BATTERY_PAYLOAD_LEN,
                available: payload.len(),
            });
        }

        let total_voltage_mv = LittleEndian::read_u32(&payload[0..4]);
        let current_ma = LittleEndian::read_i32(&payload[4..8]);
        let temp_raw = LittleEndian::read_i16(&payload[8..10]);
        let temperature_c = f32::from(temp_raw) / 10.0;
        let soc_percent = payload[10];

        let mut cell_voltages_mv = [0u16; 12];
        let mut cell_resistances_mohm = [0u16; 12];

        // Decode cell voltages (offset 11..35, 2 bytes per cell, up to 12 cells)
        let available_cells = if payload.len() >= 11 {
            ((payload.len() - 11) / 2).min(12)
        } else {
            0
        };

        for i in 0..available_cells {
            let offset = 11 + i * 2;
            cell_voltages_mv[i] = LittleEndian::read_u16(&payload[offset..offset + 2]);
        }

        // Decode cell internal resistances (offset 35..59, 2 bytes per cell, up to 12 cells)
        if payload.len() >= 35 {
            let available_res = ((payload.len() - 35) / 2).min(12);
            for i in 0..available_res {
                let offset = 35 + i * 2;
                cell_resistances_mohm[i] = LittleEndian::read_u16(&payload[offset..offset + 2]);
            }
        }

        Ok(Self {
            total_voltage_mv,
            current_ma,
            temperature_c,
            soc_percent,
            cell_voltages_mv,
            cell_resistances_mohm,
        })
    }

    /// Total battery pack voltage in volts.
    #[inline]
    #[must_use]
    pub fn total_voltage_v(&self) -> f32 {
        self.total_voltage_mv as f32 / 1000.0
    }

    /// Instantaneous current draw in amperes.
    #[inline]
    #[must_use]
    pub fn current_a(&self) -> f32 {
        self.current_ma as f32 / 1000.0
    }

    /// Returns the cell voltage in volts for cell index `0..12`.
    #[must_use]
    pub fn cell_voltage_v(&self, cell_idx: usize) -> Option<f32> {
        if cell_idx < 12 && self.cell_voltages_mv[cell_idx] > 0 {
            Some(f32::from(self.cell_voltages_mv[cell_idx]) / 1000.0)
        } else {
            None
        }
    }

    /// Returns the number of active cells with non-zero voltage.
    #[must_use]
    pub fn active_cell_count(&self) -> usize {
        self.cell_voltages_mv
            .iter()
            .filter(|&&mv| mv > 0)
            .count()
    }

    /// Returns the average cell voltage in volts across all active cells.
    #[must_use]
    pub fn average_cell_voltage_v(&self) -> f32 {
        let count = self.active_cell_count();
        if count == 0 {
            0.0
        } else {
            let sum_mv: u32 = self
                .cell_voltages_mv
                .iter()
                .filter(|&&mv| mv > 0)
                .map(|&mv| u32::from(mv))
                .sum();
            (sum_mv as f32 / count as f32) / 1000.0
        }
    }

    /// Returns the maximum voltage delta between cells in millivolts.
    #[must_use]
    pub fn cell_voltage_delta_mv(&self) -> u16 {
        let active_cells: Vec<u16> = self
            .cell_voltages_mv
            .iter()
            .copied()
            .filter(|&mv| mv > 0)
            .collect();

        if active_cells.len() < 2 {
            0
        } else {
            let min_v = active_cells.iter().min().copied().unwrap_or(0);
            let max_v = active_cells.iter().max().copied().unwrap_or(0);
            max_v.saturating_sub(min_v)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_dat_battery_parse_4s_pack() {
        let mut buf = [0u8; 19];
        // Total voltage: 15,200 mV (15.2V)
        LittleEndian::write_u32(&mut buf[0..4], 15200);
        // Current: -3,500 mA (-3.5A discharge)
        LittleEndian::write_i32(&mut buf[4..8], -3500);
        // Temperature: 25.0 °C (250)
        LittleEndian::write_i16(&mut buf[8..10], 250);
        // SOC: 88%
        buf[10] = 88;
        // 4 cells at 3,800 mV (3.8V)
        LittleEndian::write_u16(&mut buf[11..13], 3800);
        LittleEndian::write_u16(&mut buf[13..15], 3805);
        LittleEndian::write_u16(&mut buf[15..17], 3795);
        LittleEndian::write_u16(&mut buf[17..19], 3800);

        let rec = DatBatteryRecord::parse(&buf).unwrap();
        assert_eq!(rec.total_voltage_mv, 15200);
        assert!((rec.total_voltage_v() - 15.2).abs() < 1e-4);
        assert_eq!(rec.current_ma, -3500);
        assert!((rec.current_a() - (-3.5)).abs() < 1e-4);
        assert!((rec.temperature_c - 25.0).abs() < 1e-4);
        assert_eq!(rec.soc_percent, 88);

        assert_eq!(rec.active_cell_count(), 4);
        assert!((rec.cell_voltage_v(0).unwrap() - 3.8).abs() < 1e-4);
        assert_eq!(rec.cell_voltage_delta_mv(), 10); // 3805 - 3795 = 10 mV
    }

    #[test]
    fn test_dat_battery_parse_too_short() {
        let buf = [0u8; 10];
        assert_eq!(
            DatBatteryRecord::parse(&buf).unwrap_err(),
            FlightReaderError::PayloadTooShort {
                minimum: 11,
                available: 10,
            }
        );
    }
}

//! DJI `.DAT` blackbox sensor telemetry payload decoders.
//!
//! Provides zero-allocation decoders for on-board IMU attitude/accelerometer/velocity (Payload 0x01),
//! Smart Battery diagnostics (Payload 0x0A), and Motor & ESC diagnostics (Payload 0x12).
//!
//! Strictly adheres to `#![deny(unsafe_code)]` with zero `unsafe` blocks.

pub mod battery;
pub mod imu;
pub mod motor;

pub use battery::{DatBatteryRecord, MIN_DAT_BATTERY_PAYLOAD_LEN};
pub use imu::{DatImuRecord, FULL_IMU_PAYLOAD_LEN, MIN_IMU_PAYLOAD_LEN};
pub use motor::{DatMotorRecord, MIN_MOTOR_PAYLOAD_LEN};

use crate::error::Result;

/// Known DJI `.DAT` blackbox sensor payload IDs per Section 6.4 of `SPECS.md`.
pub mod payload_ids {
    /// OSD / IMU Attitude, Angular Rates, Body Accelerations, and NED Velocities (`0x01` / `1`).
    pub const IMU_ATTITUDE: u16 = 0x01;
    /// GPS Raw binary sentences (`0x02` / `2`).
    pub const GPS_RAW: u16 = 0x02;
    /// Smart Battery diagnostics (`0x0A` / `10`).
    pub const SMART_BATTERY: u16 = 0x0A;
    /// Motor & ESC real-time rotor RPM and power stage diagnostics (`0x12` / `18`).
    pub const MOTOR_ESC: u16 = 0x12;
    /// Barometer & Compass atmospheric pressure and magnetometer field (`0x2A` / `42`).
    pub const BARO_COMPASS: u16 = 0x2A;
}

/// Polymorphic representation of a parsed DJI `.DAT` blackbox payload.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum DatRecordPayload<'a> {
    /// Decoded IMU Attitude, Gyro rates, Accelerations, and Velocities (Payload 0x01).
    Imu(DatImuRecord),
    /// Decoded Motor & ESC diagnostics for up to 8 rotors (Payload 0x12).
    Motor(DatMotorRecord),
    /// Decoded Smart Battery diagnostics (Payload 0x0A).
    Battery(DatBatteryRecord),
    /// Raw unparsed payload bytes for extended or unknown sensor payload IDs.
    Unknown {
        /// Sensor payload identifier.
        payload_id: u16,
        /// Raw borrowed payload bytes.
        raw: &'a [u8],
    },
}

/// Parses a raw `.DAT` payload slice based on its `payload_id`.
pub fn parse_dat_payload(payload_id: u16, payload: &[u8]) -> Result<DatRecordPayload<'_>> {
    match payload_id {
        payload_ids::IMU_ATTITUDE => DatImuRecord::parse(payload).map(DatRecordPayload::Imu),
        payload_ids::MOTOR_ESC => DatMotorRecord::parse(payload).map(DatRecordPayload::Motor),
        payload_ids::SMART_BATTERY => DatBatteryRecord::parse(payload).map(DatRecordPayload::Battery),
        _ => Ok(DatRecordPayload::Unknown {
            payload_id,
            raw: payload,
        }),
    }
}

