//! Comprehensive Integration & Differential Test Suite: Geodetic Mathematics & EGM2008 Model
//!
//! Validates:
//! 1. Fundamental orthometric height relationship: $H = h - N$
//! 2. Takeoff relative AGL elevation: $H_{current} - H_{takeoff}$
//! 3. Local geoid undulation cancellation for AGL
//! 4. EGM2008 PGM raster discretization range ($[-108.0, 88.605]\text{ m}$)
//! 5. Global benchmark coordinates (Indian Ocean, New Guinea, Greenwich, North/South Poles)
//! 6. Bilinear grid interpolation accuracy and coordinate normalization
//! 7. WGS84 ellipsoid parameters ($a, b, f, 1/f$)
//! 8. Forward azimuth bearing calculation $[0.0, 360.0)$ across cardinal and diagonal axes
//! 9. 3D flight kinematics ($V_h, V_{3D}$, vertical climb rate, unit conversions)
//! 10. Proptest property sweeps verifying panic-free operations across all coordinate ranges.

use flightreader_core::error::FlightReaderError;
use flightreader_core::geo::{
    climb_rate, feet_to_meters, forward_azimuth, geodesic_distance, haversine_distance,
    horizontal_speed, meters_to_feet, ms_to_kmh, ms_to_mph, speed_3d, Egm2008Model, GeoidGrid,
    EGM2008_OFFSET_M, EGM2008_SCALE_M, WGS84_A, WGS84_B, WGS84_F, WGS84_INV_F,
};
use proptest::prelude::*;

// ============================================================================
// 1. Orthometric Height & EGM2008 Math (Matching test_geodetic_telemetry_dat.py)
// ============================================================================

#[test]
fn test_orthometric_height_fundamental_formula() {
    let h_sample = 525.450; // meters WGS84 ellipsoid
    let n_sample = 32.125; // meters EGM2008 geoid separation
    let expected_h = 493.325; // H = h - N

    let calc_h = h_sample - n_sample;
    assert!((calc_h - expected_h).abs() < 1e-6);

    let h_takeoff = 105.200;
    let h_current = 245.800;
    let expected_agl = 140.600;
    let calc_agl = Egm2008Model::agl_altitude(h_current, h_takeoff);
    assert!((calc_agl - expected_agl).abs() < 1e-6);

    // Local cancellation test:
    // Alt_AGL = (h_curr - N) - (h_takeoff - N) = h_curr - h_takeoff
    let h_takeoff_ellips = 137.325;
    let h_current_ellips = 277.925;
    let agl_from_ellipsoid = (h_current_ellips - n_sample) - (h_takeoff_ellips - n_sample);
    assert!((agl_from_ellipsoid - (h_current_ellips - h_takeoff_ellips)).abs() < 1e-6);
}

#[test]
fn test_egm2008_pgm_discretization_range() {
    let n_min = EGM2008_OFFSET_M + EGM2008_SCALE_M * 0.0;
    let n_max = EGM2008_OFFSET_M + EGM2008_SCALE_M * 65535.0;

    assert!((n_min - (-108.0)).abs() < 1e-6);
    assert!((n_max - 88.605).abs() < 1e-6);
}

#[test]
fn test_egm2008_discretization_feasibility_benchmarks() {
    struct Benchmark {
        name: &'static str,
        undulation: f64,
    }

    let benchmarks = [
        Benchmark {
            name: "Indian Ocean Geoid Low",
            undulation: -106.0,
        },
        Benchmark {
            name: "New Guinea Geoid High",
            undulation: 85.0,
        },
        Benchmark {
            name: "Greenwich (London)",
            undulation: 45.3,
        },
        Benchmark {
            name: "North Pole",
            undulation: 14.9,
        },
        Benchmark {
            name: "South Pole",
            undulation: -29.5,
        },
    ];

    for b in &benchmarks {
        assert!(b.undulation >= -108.0 && b.undulation <= 88.605);
        let u16_val = ((b.undulation - EGM2008_OFFSET_M) / EGM2008_SCALE_M).round() as u16;
        let reconstructed = EGM2008_OFFSET_M + EGM2008_SCALE_M * f64::from(u16_val);
        assert!(
            (b.undulation - reconstructed).abs() <= 0.002,
            "Failed benchmark precision for {}",
            b.name
        );
    }
}

#[test]
fn test_bilinear_interpolation_grid_evaluation() {
    let n00 = 40.0;
    let n10 = 42.0;
    let n01 = 44.0;
    let n11 = 48.0;

    let u = 0.5;
    let v = 0.5;
    let expected = 0.25 * (n00 + n10 + n01 + n11); // 43.5
    let calc = (1.0 - u) * (1.0 - v) * n00
        + u * (1.0 - v) * n10
        + (1.0 - u) * v * n01
        + u * v * n11;

    assert!((calc - expected).abs() < 1e-6);
}

