#[test]
fn test_wgs84_ellipsoidal_parameters() {
    assert_eq!(WGS84_A, 6378137.0);
    assert!((WGS84_INV_F - 298.257223563).abs() < 1e-9);
    assert!((WGS84_B - 6356752.314245179).abs() < 1e-4);
}

#[test]
fn test_forward_azimuth_bearing_compass() {
    // True cardinal bearings from Equator
    let north = forward_azimuth(0.0, 0.0, 1.0, 0.0);
    let east = forward_azimuth(0.0, 0.0, 0.0, 1.0);
    let south = forward_azimuth(0.0, 0.0, -1.0, 0.0);
    let west = forward_azimuth(0.0, 0.0, 0.0, -1.0);

    assert!((north - 0.0).abs() < 1e-6);
    assert!((east - 90.0).abs() < 1e-6);
    assert!((south - 180.0).abs() < 1e-6);
    assert!((west - 270.0).abs() < 1e-6);

    // Northeast 45 degrees
    let ne = forward_azimuth(0.0, 0.0, 1.0, 1.0);
    assert!((ne - 45.0).abs() < 1.0);
}

#[test]
fn test_geodesic_distance_and_haversine() {
    let lat1 = 37.7749;
    let lon1 = -122.4194;
    let lat2 = 37.7750;
    let lon2 = -122.4194;

    let dist_geo = geodesic_distance(lat1, lon1, lat2, lon2);
