    assert!((dist_geo - 11.12).abs() < 0.1);
    assert!((dist_hav - 11.12).abs() < 0.1);
}

#[test]
fn test_velocity_kinematics_and_conversions() {
    let vx = 12.0f32;
    let vy = 16.0f32;
    let vz = -15.0f32;

    let vh = horizontal_speed(vx, vy);
    assert!((vh - 20.0).abs() < 1e-6);

