    assert!((v3d - 25.0).abs() < 1e-6);

    let climb = climb_rate(vz);
    assert_eq!(climb, 15.0);

    assert!((ms_to_kmh(vh) - 72.0).abs() < 1e-5);
    assert!((ms_to_mph(vh) - 44.738726).abs() < 1e-3);

    let m = 100.0;
    let ft = meters_to_feet(m);
    assert!((ft - 328.0839895).abs() < 1e-4);
    assert!((feet_to_meters(ft) - 100.0).abs() < 1e-4);
}

#[test]
fn test_geoid_model_elevation_conversions() {
    let model = Egm2008Model::new();

    let lat = 51.5;
    let lon = 0.0;
    let h_ellips = 100.0;

    let h_ortho = model.ellipsoidal_to_orthometric(h_ellips, lat, lon).unwrap();
