//! Comprehensive Integration & Property Test Suite: DJI `.DAT` Blackbox Sensor Decoders
//!
//! Validates:
//! 1. IMU Attitude & Kinematics decoder (Payload 0x01) with attitude quaternions, gyro rates, and velocities.
//! 2. Motor & ESC diagnostics decoder (Payload 0x12) with 8-rotor RPMs, voltages, currents, and duty cycles.
//! 3. Smart Battery diagnostics decoder (Payload 0x0A) with total voltage, currents, temperatures, and cell voltages.
//! 4. End-to-end `.DAT` binary stream framing and polymorphic payload parsing with [`DatFrameIterator`].
//! 5. Robustness against truncated payloads and graceful error propagation with typed [`FlightReaderError`].
//! 6. Property-based fuzzing with `proptest`.

use byteorder::{ByteOrder, LittleEndian};
use flightreader_core::dat::checksum::calc_crc16_ccitt;
use flightreader_core::dat::{
    parse_dat_payload, payload_ids, DatBatteryRecord, DatChecksumType, DatFrame, DatFrameIterator,
    DatImuRecord, DatMotorRecord, DatRecordPayload, DAT_MAGIC,
};
use flightreader_core::error::FlightReaderError;
use proptest::prelude::*;

/// Helper to synthesize a valid CRC16-protected `.DAT` frame with header and checksum.
fn make_dat_frame(seq: u8, payload_id: u16, ticks: u32, payload: &[u8]) -> Vec<u8> {
    let header_len = 9;
    let checksum_len = 2;
    let total_len = header_len + payload.len() + checksum_len;
    assert!(total_len <= 255);

    let mut frame = Vec::with_capacity(total_len);
    frame.push(DAT_MAGIC);
    frame.push(total_len as u8);
    frame.push(seq);
    let mut id_bytes = [0u8; 2];
    LittleEndian::write_u16(&mut id_bytes, payload_id);
    frame.extend_from_slice(&id_bytes);

    let mut tick_bytes = [0u8; 4];
    LittleEndian::write_u32(&mut tick_bytes, ticks);
    frame.extend_from_slice(&tick_bytes);

    frame.extend_from_slice(payload);

    let crc = calc_crc16_ccitt(&frame);
    let mut crc_bytes = [0u8; 2];
    LittleEndian::write_u16(&mut crc_bytes, crc);
    frame.extend_from_slice(&crc_bytes);

    frame
}

// ============================================================================
// 1. IMU Attitude & Velocity Decoder Tests
// ============================================================================

#[test]
fn test_dat_imu_attitude_and_kinematics_decoding() {
    let mut payload = vec![0u8; 52];
    // Identity quaternion
    LittleEndian::write_f32(&mut payload[0..4], 1.0);
    LittleEndian::write_f32(&mut payload[4..8], 0.0);
    LittleEndian::write_f32(&mut payload[8..12], 0.0);
    LittleEndian::write_f32(&mut payload[12..16], 0.0);

    // Gyro rates: 0.05, -0.02, 0.10 rad/s
    LittleEndian::write_f32(&mut payload[16..20], 0.05);
    LittleEndian::write_f32(&mut payload[20..24], -0.02);
    LittleEndian::write_f32(&mut payload[24..28], 0.10);

    // Body accelerations: 0.1, 0.2, 9.80 m/s^2
    LittleEndian::write_f32(&mut payload[28..32], 0.1);
    LittleEndian::write_f32(&mut payload[32..36], 0.2);
    LittleEndian::write_f32(&mut payload[36..40], 9.80);

    // Velocities: North 15.0 m/s, East 20.0 m/s, Down -8.0 m/s (climbing)
    LittleEndian::write_f32(&mut payload[40..44], 15.0);
    LittleEndian::write_f32(&mut payload[44..48], 20.0);
    LittleEndian::write_f32(&mut payload[48..52], -8.0);

    let imu = DatImuRecord::parse(&payload).expect("valid IMU parse");
    assert_eq!(imu.q0, 1.0);
    assert_eq!(imu.gyro_x, 0.05);
    assert_eq!(imu.accel_z, 9.80);

    assert_eq!(imu.vel_n, 15.0);
    assert_eq!(imu.vel_e, 20.0);
    assert_eq!(imu.vel_d, -8.0);

    // Speed derivations:
    // V_h = sqrt(15^2 + 20^2) = 25.0 m/s
    assert!((imu.horizontal_speed() - 25.0).abs() < 1e-4);
    // V_3D = sqrt(25^2 + 8^2) = sqrt(625 + 64) = sqrt(689) ~= 26.2488
    assert!((imu.speed_3d() - 26.2488).abs() < 1e-3);
    // Climb rate = -(-8.0) = +8.0 m/s
    assert_eq!(imu.climb_rate(), 8.0);

    // Euler attitude angles: level flight
    assert!((imu.pitch_deg() - 0.0).abs() < 1e-4);
    assert!((imu.roll_deg() - 0.0).abs() < 1e-4);
    assert!((imu.yaw_deg() - 0.0).abs() < 1e-4);
}

// ============================================================================
// 2. Motor & ESC Diagnostics Decoder Tests
// ============================================================================

#[test]
fn test_dat_motor_and_esc_diagnostics() {
    let mut payload = vec![0u8; 72];
    // Rotor RPMs (8 motors)
    let rpms = [5100, 5150, 5080, 5120, 5110, 5130, 5090, 5140];
    for (i, &rpm) in rpms.iter().enumerate() {
        LittleEndian::write_u16(&mut payload[i * 2..(i + 1) * 2], rpm);
    }

    // ESC Voltages (22.2V nominal -> 222 in 0.1V)
    for i in 0..8 {
        LittleEndian::write_u16(&mut payload[16 + i * 2..16 + (i + 1) * 2], 222);
    }

    // ESC Currents (14.5A -> 145 in 0.1A)
    for i in 0..8 {
        LittleEndian::write_i16(&mut payload[32 + i * 2..32 + (i + 1) * 2], 145);
    }

    // ESC Temperatures (45 °C)
    for i in 0..8 {
        payload[48 + i] = 45;
    }

    // PWM Duty Cycle (65.0% -> 650 in 0.1%)
    for i in 0..8 {
        LittleEndian::write_u16(&mut payload[56 + i * 2..56 + (i + 1) * 2], 650);
    }

    let motor = DatMotorRecord::parse(&payload).expect("valid motor parse");
    assert_eq!(motor.rotor_rpm, rpms);
    assert!(motor.is_motor_spinning());
    assert!((motor.average_active_rpm() - 5115.0).abs() < 1.0);

    for i in 0..8 {
        assert!((motor.esc_voltage_v[i] - 22.2).abs() < 0.1);
        assert!((motor.esc_current_a[i] - 14.5).abs() < 0.1);
        assert_eq!(motor.esc_temp_c[i], 45);
        assert!((motor.pwm_duty_percent[i] - 65.0).abs() < 0.1);
    }
}

// ============================================================================
// 3. Smart Battery Diagnostics Decoder Tests
// ============================================================================

#[test]
fn test_dat_smart_battery_diagnostics() {
    let mut payload = vec![0u8; 59];
    // Total voltage: 22,800 mV (22.8V - 6S pack)
    LittleEndian::write_u32(&mut payload[0..4], 22800);
    // Current draw: -18,200 mA (-18.2A)
    LittleEndian::write_i32(&mut payload[4..8], -18200);
    // Temperature: 32.5 °C (325 in 0.1°C)
    LittleEndian::write_i16(&mut payload[8..10], 325);
    // SOC: 72%
    payload[10] = 72;

    // 6 cells at 3,800 mV
    let cell_v = [3800, 3805, 3798, 3802, 3800, 3795, 0, 0, 0, 0, 0, 0];
    for (i, &v) in cell_v.iter().enumerate() {
        LittleEndian::write_u16(&mut payload[11 + i * 2..11 + (i + 1) * 2], v);
    }

    // 6 cell resistances at 4 mOhm
    let cell_res = [4, 4, 5, 4, 4, 4, 0, 0, 0, 0, 0, 0];
    for (i, &r) in cell_res.iter().enumerate() {
        LittleEndian::write_u16(&mut payload[35 + i * 2..35 + (i + 1) * 2], r);
    }

    let bat = DatBatteryRecord::parse(&payload).expect("valid battery parse");
    assert_eq!(bat.total_voltage_mv, 22800);
    assert!((bat.total_voltage_v() - 22.8).abs() < 1e-3);
    assert_eq!(bat.current_ma, -18200);
    assert!((bat.current_a() - (-18.2)).abs() < 1e-3);
    assert!((bat.temperature_c - 32.5).abs() < 1e-3);
    assert_eq!(bat.soc_percent, 72);

    assert_eq!(bat.active_cell_count(), 6);
    assert!((bat.cell_voltage_v(0).unwrap() - 3.800).abs() < 1e-3);
    assert_eq!(bat.cell_voltage_v(6), None); // Inactive cell 7
    assert_eq!(bat.cell_voltage_delta_mv(), 10); // 3805 - 3795 = 10 mV
}

// ============================================================================
// 4. End-to-End Stream Demuxing with DatFrameIterator
// ============================================================================

#[test]
fn test_e2e_dat_stream_demuxing_and_payload_parsing() {
    let mut stream = Vec::new();

    // Frame 1: IMU Attitude (seq 1, ticks 100,000)
    let mut imu_payload = vec![0u8; 16];
    LittleEndian::write_f32(&mut imu_payload[0..4], 1.0);
    stream.extend_from_slice(&make_dat_frame(1, payload_ids::IMU_ATTITUDE, 100_000, &imu_payload));

    // Frame 2: Motor Diagnostics (seq 2, ticks 105,000)
    let mut motor_payload = vec![0u8; 16];
    for i in 0..4 {
        LittleEndian::write_u16(&mut motor_payload[i * 2..(i + 1) * 2], 5200);
    }
    stream.extend_from_slice(&make_dat_frame(2, payload_ids::MOTOR_ESC, 105_000, &motor_payload));

    // Frame 3: Smart Battery (seq 3, ticks 110,000)
    let mut bat_payload = vec![0u8; 19];
    LittleEndian::write_u32(&mut bat_payload[0..4], 15200);
    stream.extend_from_slice(&make_dat_frame(3, payload_ids::SMART_BATTERY, 110_000, &bat_payload));

    // Iterate frames
    let mut iter = DatFrameIterator::new(&stream);

    // Frame 1: IMU
    let f1 = iter.next().expect("Frame 1").expect("valid frame");
    assert_eq!(f1.payload_id, payload_ids::IMU_ATTITUDE);
    match parse_dat_payload(f1.payload_id, f1.payload).unwrap() {
        DatRecordPayload::Imu(imu) => assert_eq!(imu.q0, 1.0),
        other => panic!("Expected IMU payload, got {other:?}"),
    }

    // Frame 2: Motor
    let f2 = iter.next().expect("Frame 2").expect("valid frame");
    assert_eq!(f2.payload_id, payload_ids::MOTOR_ESC);
    match parse_dat_payload(f2.payload_id, f2.payload).unwrap() {
        DatRecordPayload::Motor(m) => assert_eq!(m.rotor_rpm[0], 5200),
        other => panic!("Expected Motor payload, got {other:?}"),
    }

    // Frame 3: Battery
    let f3 = iter.next().expect("Frame 3").expect("valid frame");
    assert_eq!(f3.payload_id, payload_ids::SMART_BATTERY);
    match parse_dat_payload(f3.payload_id, f3.payload).unwrap() {
        DatRecordPayload::Battery(b) => assert_eq!(b.total_voltage_mv, 15200),
        other => panic!("Expected Battery payload, got {other:?}"),
    }

    assert!(iter.next().is_none());
}

