//! Command-line argument definitions and parser for `flightreader`.

use std::path::PathBuf;
use clap::{Args, Parser, Subcommand, ValueEnum};
use flightreader_export::exporters::ExportFormat;

/// OpenFlightReader — High-performance offline DJI drone flight log analyzer,
/// GIS exporter, and interactive local visualization engine.
#[derive(Debug, Parser)]
#[command(
    name = "flightreader",
    author,
    version,
    about = "100% offline DJI flight log analysis, GIS export, and interactive local visualization",
    long_about = "OpenFlightReader provides high-performance, air-gapped decoding and analysis\n\
                  of DJI .txt and .DAT drone flight logs with zero cloud dependencies."
)]
pub struct Cli {
    #[command(subcommand)]
    pub command: Commands,

    /// Verbosity level (-v, -vv, -vvv)
    #[arg(short, long, action = clap::ArgAction::Count, global = true)]
    pub verbose: u8,
}

/// Subcommands supported by `flightreader`.
#[derive(Debug, Subcommand)]
pub enum Commands {
    /// Print header summary, version, aircraft type, and detected telemetry streams
    Info(InfoArgs),

    /// Export decoded flight telemetry to GIS and analytical data formats (CSV, KML, GPX, GeoJSON, JSON)
    Export(ExportArgs),

    /// Launch the local offline web viewer and dashboard
    Serve(ServeArgs),
}

/// Arguments for `flightreader info`.
#[derive(Debug, Args)]
pub struct InfoArgs {
    /// Path to DJI .txt or .DAT flight log file
    #[arg(value_name = "FILE")]
    pub file: PathBuf,

    /// Output header and flight metadata as structured JSON
    #[arg(long)]
    pub json: bool,
}

/// Supported export formats for CLI.
#[derive(Debug, Clone, Copy, PartialEq, Eq, ValueEnum)]
pub enum CliExportFormat {
    /// RFC 4180 Comma-Separated Values time-series table
    Csv,
    /// OGC KML 2.2 3D extruded flight trajectory path
    Kml,
    /// TopoGrafix GPX 1.1 standard GPS trackpoints with UAV telemetry
    Gpx,
    /// RFC 7946 GeoJSON LineString feature collection
    Geojson,
    /// Structured hierarchical flight summary JSON
    Json,
}

impl From<CliExportFormat> for ExportFormat {
    fn from(f: CliExportFormat) -> Self {
        match f {
            CliExportFormat::Csv => ExportFormat::Csv,
            CliExportFormat::Kml => ExportFormat::Kml,
            CliExportFormat::Gpx => ExportFormat::Gpx,
            CliExportFormat::Geojson => ExportFormat::GeoJson,
            CliExportFormat::Json => ExportFormat::JsonSummary,
        }
    }
}

/// Arguments for `flightreader export`.
#[derive(Debug, Args)]
pub struct ExportArgs {
    /// Path to input DJI .txt or .DAT flight log file
    #[arg(value_name = "FILE")]
    pub file: PathBuf,

    /// Target export format
    #[arg(short, long, value_enum)]
    pub format: CliExportFormat,

    /// Output destination file path (or '-' for stdout)
    #[arg(short, long, value_name = "OUT")]
    pub output: Option<PathBuf>,

    /// Filter start boundary (elapsed seconds, MM:SS, HH:MM:SS, or ISO 8601 UTC)
    #[arg(long, value_name = "START")]
    pub start: Option<String>,

    /// Filter end boundary (elapsed seconds, MM:SS, HH:MM:SS, or ISO 8601 UTC)
    #[arg(long, value_name = "END")]
    pub end: Option<String>,

    /// Rate decimation sampling frequency in Hz (e.g. 1.0, 5.0, 10.0; preserves critical landmark events)
    #[arg(short, long, value_name = "HZ")]
    pub rate: Option<f64>,

    /// Format JSON or GeoJSON output with indentation
    #[arg(long)]
    pub pretty: bool,
}

/// Arguments for `flightreader serve`.
#[derive(Debug, Args)]
pub struct ServeArgs {
    /// Optional path to a DJI flight log file to load immediately on startup
    #[arg(value_name = "FILE")]
    pub file: Option<PathBuf>,

    /// TCP port to bind server listener to
    #[arg(short, long, default_value_t = 8080)]
    pub port: u16,

    /// Host IP address to bind server listener to
    #[arg(short = 'H', long, default_value = "127.0.0.1")]
    pub host: String,

    /// Automatically open default web browser upon server launch
    #[arg(long)]
    pub open: bool,

    /// Optional path to an MBTiles vector/raster basemap SQLite archive
    #[arg(long, value_name = "MBTILES")]
    pub mbtiles: Option<PathBuf>,

    /// Optional path to offline map tiles directory ({z}/{x}/{y}.png)
    #[arg(long, value_name = "DIR")]
    pub tile_dir: Option<PathBuf>,
}

//! Implementation of the `flightreader info` command.

use std::fs;
use std::path::Path;
use chrono::{DateTime, Utc};
use serde::Serialize;

use flightreader_core::dat::DAT_MAGIC;
use flightreader_core::txt::TxtHeader;
use flightreader_export::model::FlightDataset;

use crate::args::InfoArgs;

/// Structured JSON output model for flight information.
#[derive(Debug, Serialize)]
pub struct FlightInfoOutput {
    /// File name.
    pub file_name: String,
    /// Total file size in bytes.
    pub file_size_bytes: u64,
    /// Human-readable file size string.
    pub file_size_formatted: String,
    /// Format identifier (e.g. "DJI .txt (v12)" or "DJI .DAT Blackbox").
    pub format: String,
    /// Protocol major version (for .txt logs).
    pub version: Option<u8>,
    /// Byte offset where details metadata or record tables reside.
    pub details_offset: Option<i64>,
    /// Whether payloads are scrambled with cyclic XOR / AES encryption.
    pub scrambled: Option<bool>,
    /// Aircraft model / name.
    pub aircraft_name: String,
    /// Total count of synchronized telemetry points.
    pub total_points: usize,
    /// Total recording duration in seconds.
    pub duration_seconds: f64,
    /// Formatted duration string (HH:MM:SS or MM:SS).
    pub duration_formatted: String,
    /// Total horizontal flight distance in meters.
    pub total_distance_meters: f64,
    /// Maximum altitude MSL in meters.
    pub max_altitude_msl: f64,
    /// Maximum altitude AGL in meters.
    pub max_altitude_agl: f64,
    /// Maximum ground speed in meters per second.
    pub max_ground_speed_mps: f64,
    /// Maximum ground speed in km/h.
    pub max_ground_speed_kmh: f64,
    /// Start timestamp in ISO 8601 UTC.
    pub start_time_utc: Option<String>,
    /// End timestamp in ISO 8601 UTC.
    pub end_time_utc: Option<String>,
    /// Home point location.
    pub home_point: Option<HomePointInfo>,
    /// Geographic bounding box.
    pub bounding_box: Option<BoundingBoxInfo>,
    /// Battery health and consumption summary.
    pub battery_summary: Option<BatterySummaryInfo>,
    /// Total recorded flight landmark events (takeoff, landing, mode change, RTH).
    pub events_count: usize,
}

/// Home point coordinate information.
#[derive(Debug, Serialize)]
pub struct HomePointInfo {
    /// WGS84 Latitude.
    pub latitude: f64,
    /// WGS84 Longitude.
    pub longitude: f64,
    /// Altitude MSL in meters.
    pub altitude_msl: f64,
}

/// Geographic bounding box enclosing the trajectory.
#[derive(Debug, Serialize)]
pub struct BoundingBoxInfo {
    /// Minimum latitude.
    pub min_lat: f64,
    /// Maximum latitude.
    pub max_lat: f64,
    /// Minimum longitude.
    pub min_lon: f64,
    /// Maximum longitude.
    pub max_lon: f64,
}

/// Battery summary metrics.
#[derive(Debug, Serialize)]
pub struct BatterySummaryInfo {
    /// Initial State of Charge percentage.
    pub start_soc_pct: Option<u8>,
    /// Lowest recorded State of Charge percentage.
    pub min_soc_pct: Option<u8>,
    /// Lowest pack terminal voltage in millivolts.
    pub min_voltage_mv: Option<u32>,
}

/// Executes the `flightreader info` command.
pub fn execute_info(args: InfoArgs) -> Result<(), Box<dyn std::error::Error>> {
    let path = &args.file;
    if !path.exists() {
        return Err(format!("File not found: {}", path.display()).into());
    }

    let file_metadata = fs::metadata(path)?;
    let file_size_bytes = file_metadata.len();
    let bytes = fs::read(path)?;

    if bytes.is_empty() {
        return Err("Flight log file is empty (0 bytes)".into());
    }

    // Inspect header format
    let is_dat = bytes[0] == DAT_MAGIC;
    let (format_str, version_opt, details_offset_opt, scrambled_opt) = if is_dat {
        ("DJI .DAT Blackbox Recording".to_string(), None, None, None)
    } else if bytes.len() >= 100 {
        match TxtHeader::parse(&bytes[..101.min(bytes.len())]) {
            Ok(hdr) => (
                format!("DJI .txt (v{})", hdr.version),
                Some(hdr.version),
                Some(hdr.details_offset),
                Some(hdr.scrambled_flag != 0),
            ),
            Err(_) => ("DJI .txt (Unknown Version)".to_string(), None, None, None),
        }
    } else {
        ("Unknown Binary Telemetry Format".to_string(), None, None, None)
    };

    // Ingest telemetry dataset
    let dataset = flightreader_export::aggregate_buffer(&bytes, None)
        .map_err(|e| format!("Failed to parse flight log: {e}"))?;

    let file_name = path
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| "unknown".to_string());

    let file_size_formatted = format_file_size(file_size_bytes);
    let duration_formatted = format_duration(dataset.metadata.duration_seconds);

    let start_time_utc = dataset
        .metadata
        .start_time_utc_ms
        .and_then(|ms| DateTime::from_timestamp_millis(ms).map(|dt: DateTime<Utc>| dt.to_rfc3339()));

    let end_time_utc = dataset
        .metadata
        .end_time_utc_ms
        .and_then(|ms| DateTime::from_timestamp_millis(ms).map(|dt: DateTime<Utc>| dt.to_rfc3339()));

    let home_point = dataset.metadata.home_point.as_ref().map(|hp| HomePointInfo {
        latitude: hp.latitude,
        longitude: hp.longitude,
        altitude_msl: hp.altitude_msl,
    });

    let bounding_box = dataset.metadata.bounding_box.as_ref().map(|bb| BoundingBoxInfo {
        min_lat: bb.min_lat,
        max_lat: bb.max_lat,
        min_lon: bb.min_lon,
        max_lon: bb.max_lon,
    });

    // Derive battery metrics if available
    let (start_soc, min_soc, min_voltage) = derive_battery_metrics(&dataset);
    let battery_summary = if start_soc.is_some() || min_soc.is_some() || min_voltage.is_some() {
        Some(BatterySummaryInfo {
            start_soc_pct: start_soc,
            min_soc_pct: min_soc,
            min_voltage_mv: min_voltage,
        })
    } else {
        None
    };

    let max_speed_kmh = dataset.metadata.max_ground_speed_mps * 3.6;

    let output = FlightInfoOutput {
        file_name,
        file_size_bytes,
        file_size_formatted,
        format: format_str,
        version: version_opt,
        details_offset: details_offset_opt,
        scrambled: scrambled_opt,
        aircraft_name: dataset.metadata.aircraft_name.clone(),
        total_points: dataset.points.len(),
        duration_seconds: dataset.metadata.duration_seconds,
        duration_formatted,
        total_distance_meters: dataset.metadata.total_distance_m,
        max_altitude_msl: dataset.metadata.max_altitude_msl,
        max_altitude_agl: dataset.metadata.max_altitude_agl,
        max_ground_speed_mps: dataset.metadata.max_ground_speed_mps,
        max_ground_speed_kmh: max_speed_kmh,
        start_time_utc,
        end_time_utc,
        home_point,
        bounding_box,
        battery_summary,
        events_count: dataset.events.len(),
    };

    if args.json {
        let json_str = serde_json::to_string_pretty(&output)?;
        println!("{json_str}");
    } else {
        print_human_summary(&output, path);
    }

    Ok(())
}

fn derive_battery_metrics(dataset: &FlightDataset) -> (Option<u8>, Option<u8>, Option<u32>) {
    let mut start_soc = None;
    let mut min_soc = None;
    let mut min_volts = None;

    for pt in &dataset.points {
        if pt.battery_pct > 0 && pt.battery_pct <= 100 {
            if start_soc.is_none() {
                start_soc = Some(pt.battery_pct);
            }
            min_soc = Some(min_soc.map_or(pt.battery_pct, |m: u8| m.min(pt.battery_pct)));
        }
        if pt.battery_voltage_mv > 0 {
            min_volts = Some(min_volts.map_or(pt.battery_voltage_mv, |m: u32| m.min(pt.battery_voltage_mv)));
        }
    }

    (start_soc, min_soc, min_volts)
}

fn print_human_summary(info: &FlightInfoOutput, path: &Path) {
    println!("================================================================================");
    println!("OPENFLIGHTREADER :: FLIGHT LOG SUMMARY");
    println!("================================================================================");
    println!("  Target File:       {}", path.display());
    println!("  File Size:         {} ({} bytes)", info.file_size_formatted, info.file_size_bytes);
    println!("  Format:            {}", info.format);
    if let Some(v) = info.version {
        println!("  Version:           {}", v);
    }
    if let Some(off) = info.details_offset {
        println!("  Details Offset:    0x{:X} ({})", off, off);
    }
    if let Some(scrambled) = info.scrambled {
        println!("  Scrambled:         {}", if scrambled { "Yes (XOR / AES)" } else { "No (Plaintext)" });
    }
    println!("--------------------------------------------------------------------------------");
    println!("  Aircraft Model:    {}", info.aircraft_name);
    println!("  Total Samples:     {}", info.total_points);
    println!("  Flight Duration:   {} ({:.2} s)", info.duration_formatted, info.duration_seconds);
    println!("  Flight Distance:   {:.2} m ({:.2} km)", info.total_distance_meters, info.total_distance_meters / 1000.0);
    println!("  Max Altitude MSL:  {:.2} m", info.max_altitude_msl);
    println!("  Max Altitude AGL:  {:.2} m", info.max_altitude_agl);
    println!("  Max Ground Speed:  {:.2} m/s ({:.2} km/h)", info.max_ground_speed_mps, info.max_ground_speed_kmh);
    println!("--------------------------------------------------------------------------------");
    if let Some(start) = &info.start_time_utc {
        println!("  Start Time (UTC):  {}", start);
    }
    if let Some(end) = &info.end_time_utc {
        println!("  End Time (UTC):    {}", end);
    }
    if let Some(hp) = &info.home_point {
        println!("  Home Point:        Lat {:.7}°, Lon {:.7}°, Alt {:.1} m MSL", hp.latitude, hp.longitude, hp.altitude_msl);
    }
    if let Some(bb) = &info.bounding_box {
        println!("  Bounding Box:      Lat [{:.6}°, {:.6}°], Lon [{:.6}°, {:.6}°]", bb.min_lat, bb.max_lat, bb.min_lon, bb.max_lon);
    }
    if let Some(bat) = &info.battery_summary {
        let start_str = bat.start_soc_pct.map_or("-".to_string(), |v| format!("{v}%"));
        let min_str = bat.min_soc_pct.map_or("-".to_string(), |v| format!("{v}%"));
        let volt_str = bat.min_voltage_mv.map_or("-".to_string(), |v| format!("{:.2} V", v as f64 / 1000.0));
        println!("  Battery Health:    Start SOC: {}, Min SOC: {}, Lowest Pack: {}", start_str, min_str, volt_str);
    }
    println!("  Flight Events:     {} recorded", info.events_count);
    println!("================================================================================");
}

fn format_file_size(bytes: u64) -> String {
    const KB: u64 = 1024;
    const MB: u64 = 1024 * KB;
    const GB: u64 = 1024 * MB;

    if bytes >= GB {
        format!("{:.2} GB", bytes as f64 / GB as f64)
    } else if bytes >= MB {
        format!("{:.2} MB", bytes as f64 / MB as f64)
    } else if bytes >= KB {
        format!("{:.2} KB", bytes as f64 / KB as f64)
    } else {
        format!("{bytes} B")
    }
}

fn format_duration(seconds: f64) -> String {
    let total_secs = seconds.round() as u64;
    let hours = total_secs / 3600;
    let minutes = (total_secs % 3600) / 60;
    let secs = total_secs % 60;

    if hours > 0 {
        format!("{:02}:{:02}:{:02}", hours, minutes, secs)
    } else {
        format!("{:02}:{:02}", minutes, secs)
    }
}

