//! Implementation of the `flightreader export` command.

use std::fs;
use std::io::{self, BufWriter, Write};
use std::path::{Path, PathBuf};

use flightreader_export::exporters::{
    CsvExporter, CsvOptions, ExportFormat, FlightExporter, GeoJsonExporter, GeoJsonOptions,
    GpxExporter, GpxOptions, JsonSummaryExporter, JsonSummaryOptions, KmlExporter, KmlOptions,
};
use flightreader_export::filter::{filter_dataset, TimeFilter};

use crate::args::{CliExportFormat, ExportArgs};

/// Executes the `flightreader export` command.
pub fn execute_export(args: ExportArgs) -> Result<(), Box<dyn std::error::Error>> {
    let input_path = &args.file;
    if !input_path.exists() {
        return Err(format!("Input file not found: {}", input_path.display()).into());
    }

    let bytes = fs::read(input_path)?;
    if bytes.is_empty() {
        return Err("Input flight log file is empty (0 bytes)".into());
    }

    // Parse and aggregate binary flight telemetry
    let dataset = flightreader_export::aggregate_buffer(&bytes, None)
        .map_err(|e| format!("Failed to parse flight log: {e}"))?;

    // Apply time window filtering and rate decimation if requested
    let has_filter = args.start.is_some() || args.end.is_some() || args.rate.is_some();
    let final_dataset = if has_filter {
        let time_filter = if args.start.is_some() || args.end.is_some() {
            Some(TimeFilter::parse(args.start.as_deref(), args.end.as_deref())?)
        } else {
            None
        };

        filter_dataset(&dataset, time_filter.as_ref(), args.rate)?
    } else {
        dataset
    };

    let target_format = ExportFormat::from(args.format);

    // Determine output sink: stdout if "-" or None, otherwise file path
    let is_stdout = match &args.output {
        None => true,
        Some(p) => p == Path::new("-"),
    };

    if is_stdout {
        let stdout = io::stdout();
        let mut handle = stdout.lock();
        write_export_to(&final_dataset, args.format, args.pretty, &mut handle)?;
        handle.flush()?;
    } else {
        let out_path = args.output.as_ref().unwrap();
        // Ensure parent directory exists
        if let Some(parent) = out_path.parent() {
            if !parent.as_os_str().is_empty() {
                fs::create_dir_all(parent)?;
            }
        }

        let file = fs::File::create(out_path)?;
        let mut writer = BufWriter::new(file);
        write_export_to(&final_dataset, args.format, args.pretty, &mut writer)?;
        writer.flush()?;

        let out_size = fs::metadata(out_path)?.len();
        eprintln!(
            "Successfully exported {} telemetry points to {} (format: {}, size: {} bytes)",
            final_dataset.points.len(),
            out_path.display(),
            target_format.file_extension(),
            out_size
        );
    }

    Ok(())
}

fn write_export_to<W: Write>(
    dataset: &flightreader_export::model::FlightDataset,
    format: CliExportFormat,
    pretty: bool,
    writer: &mut W,
) -> Result<(), flightreader_export::error::ExportError> {
    match format {
        CliExportFormat::Csv => {
            let exporter = CsvExporter::new(CsvOptions::default());
            exporter.export(dataset, writer)
        }
        CliExportFormat::Kml => {
            let exporter = KmlExporter::new(KmlOptions::default());
            exporter.export(dataset, writer)
        }
        CliExportFormat::Gpx => {
            let exporter = GpxExporter::new(GpxOptions::default());
            exporter.export(dataset, writer)
        }
        CliExportFormat::Geojson => {
            let exporter = GeoJsonExporter::new(GeoJsonOptions {
                pretty,
                ..Default::default()
            });
            exporter.export(dataset, writer)
        }
        CliExportFormat::Json => {
            let exporter = JsonSummaryExporter::new(JsonSummaryOptions { pretty });
            exporter.export(dataset, writer)
        }
    }
}

//! Implementation of the `flightreader serve` command.

use std::fs;
use std::time::Duration;

use flightreader_server::ServerConfig;

use crate::args::ServeArgs;

/// Executes the `flightreader serve` command.
pub async fn execute_serve(args: ServeArgs) -> Result<(), Box<dyn std::error::Error>> {
    let mut config = ServerConfig {
        host: args.host.clone(),
        port: args.port,
        open_browser: args.open,
        mbtiles_path: args.mbtiles,
        tile_dir: args.tile_dir,
        initial_dataset: None,
    };

    // Load initial flight log if specified on command line
    if let Some(path) = &args.file {
        if !path.exists() {
            return Err(format!("Specified flight log not found: {}", path.display()).into());
        }

        let bytes = fs::read(path)?;
        if bytes.is_empty() {
            return Err("Specified flight log file is empty".into());
        }

        let dataset = flightreader_export::aggregate_buffer(&bytes, None)
            .map_err(|e| format!("Failed to parse initial flight log {}: {e}", path.display()))?;

        println!(
            "Pre-loaded flight log: {} ({} points, duration: {:.1}s)",
            path.display(),
            dataset.points.len(),
            dataset.metadata.duration_seconds
        );

        config.initial_dataset = Some(dataset);
    }

    let server_url = format!("http://{}:{}", config.host, config.port);

    println!("================================================================================");
    println!("OPENFLIGHTREADER :: OFFLINE LOCAL WEB DASHBOARD");
    println!("================================================================================");
    println!("  Dashboard URL:     {}", server_url);
    println!("  Mode:              100% Offline Air-Gapped (Zero Cloud Calls)");
    println!("  Features:          Leaflet / 2D Canvas Fallback Map, 60 FPS Scrubber, Telemetry Charts");
    if let Some(mb) = &config.mbtiles_path {
        println!("  MBTiles Basemap:   {}", mb.display());
    }
    if let Some(td) = &config.tile_dir {
        println!("  Offline Tiles:     {}", td.display());
    }
    println!("  Press Ctrl+C to shut down gracefully");
    println!("================================================================================");

    // Optionally spawn browser launch in background after brief listener delay
    if args.open {
        let url_to_open = server_url.clone();
        tokio::spawn(async move {
            tokio::time::sleep(Duration::from_millis(300)).await;
            tracing::info!("Opening default web browser to {}", url_to_open);
            let _ = open::that(&url_to_open);
        });
    }

    flightreader_server::start_server(config)
        .await
        .map_err(|e| format!("Server execution error: {e}"))?;

    Ok(())
}

//! Command implementations for `flightreader`.

pub mod export;
pub mod info;
pub mod serve;

pub use export::execute_export;
pub use info::execute_info;
pub use serve::execute_serve;

//! OpenFlightReader CLI entry point.
//!
//! Provides high-performance command-line operations for DJI drone flight log analysis,
//! GIS telemetry export (CSV, KML, GPX, GeoJSON, JSON), and local offline visualization.

#![deny(unsafe_code)]

mod args;
mod commands;

use clap::Parser;
use tracing_subscriber::{layer::SubscriberExt, util::SubscriberInitExt, EnvFilter};

use args::{Cli, Commands};
use commands::{execute_export, execute_info, execute_serve};

#[tokio::main]
async fn main() {
    let cli = Cli::parse();

    // Configure logging verbosity
    let log_level = match cli.verbose {
        0 => "warn,flightreader=info",
        1 => "info",
        2 => "debug",
        _ => "trace",
    };

    let filter = EnvFilter::try_from_default_env()
        .unwrap_or_else(|_| EnvFilter::new(log_level));

    tracing_subscriber::registry()
        .with(filter)
        .with(tracing_subscriber::fmt::layer().with_target(false))
        .init();

    let result = match cli.command {
        Commands::Info(args) => execute_info(args),
        Commands::Export(args) => execute_export(args),
        Commands::Serve(args) => execute_serve(args).await,
    };

    if let Err(e) = result {
        eprintln!("Error: {e}");
        std::process::exit(1);
    }
}

//! Implementation of the `flightreader info` command.

use std::fs;
use std::path::Path;
use serde::Serialize;

use flightreader_core::dat::DAT_MAGIC;
use flightreader_core::txt::TxtHeader;
use flightreader_export::model::FlightDataset;

use crate::args::InfoArgs;

/// Structured JSON output model for flight information.
#[derive(Debug, Serialize)]
pub struct FlightInfoOutput {
    /// File name.
    pub file_name: String,
    /// Total file size in bytes.
    pub file_size_bytes: u64,
    /// Human-readable file size string.
    pub file_size_formatted: String,
    /// Format identifier (e.g. "DJI .txt (v12)" or "DJI .DAT Blackbox").
    pub format: String,
    /// Protocol major version (for .txt logs).
    pub version: Option<u8>,
    /// Byte offset where details metadata or record tables reside.
    pub details_offset: Option<i64>,
    /// Whether payloads are scrambled with cyclic XOR / AES encryption.
    pub scrambled: Option<bool>,
    /// Aircraft model / name.
    pub aircraft_name: String,
    /// Total count of synchronized telemetry points.
    pub total_points: usize,
    /// Total recording duration in seconds.
    pub duration_seconds: f64,
    /// Formatted duration string (HH:MM:SS or MM:SS).
    pub duration_formatted: String,
    /// Total horizontal flight distance in meters.
    pub total_distance_meters: f64,
    /// Maximum altitude MSL in meters.
    pub max_altitude_msl: f64,
    /// Maximum altitude AGL in meters.
    pub max_altitude_agl: f64,
    /// Maximum ground speed in meters per second.
    pub max_ground_speed_mps: f64,
    /// Maximum ground speed in km/h.
    pub max_ground_speed_kmh: f64,
    /// Start timestamp in ISO 8601 UTC.
    pub start_time_utc: Option<String>,
    /// End timestamp in ISO 8601 UTC.
    pub end_time_utc: Option<String>,
    /// Home point location.
    pub home_point: Option<HomePointInfo>,
    /// Geographic bounding box.
    pub bounding_box: Option<BoundingBoxInfo>,
    /// Battery health and consumption summary.
    pub battery_summary: Option<BatterySummaryInfo>,
    /// Total recorded flight landmark events (takeoff, landing, mode change, RTH).
    pub events_count: usize,
}

/// Home point coordinate information.
#[derive(Debug, Serialize)]
pub struct HomePointInfo {
    /// WGS84 Latitude.
    pub latitude: f64,
    /// WGS84 Longitude.
    pub longitude: f64,
    /// Altitude MSL in meters.
    pub altitude_msl: f64,
}

/// Geographic bounding box enclosing the trajectory.
#[derive(Debug, Serialize)]
pub struct BoundingBoxInfo {
    /// Minimum latitude.
    pub min_lat: f64,
    /// Maximum latitude.
    pub max_lat: f64,
    /// Minimum longitude.
    pub min_lon: f64,
    /// Maximum longitude.
    pub max_lon: f64,
}

/// Battery summary metrics.
#[derive(Debug, Serialize)]
pub struct BatterySummaryInfo {
    /// Initial State of Charge percentage.
    pub start_soc_pct: Option<u8>,
    /// Lowest recorded State of Charge percentage.
    pub min_soc_pct: Option<u8>,
    /// Lowest pack terminal voltage in millivolts.
    pub min_voltage_mv: Option<u32>,
}

/// Executes the `flightreader info` command.
pub fn execute_info(args: InfoArgs) -> Result<(), Box<dyn std::error::Error>> {
    let path = &args.file;
    if !path.exists() {
        return Err(format!("File not found: {}", path.display()).into());
    }

    let file_metadata = fs::metadata(path)?;
    let file_size_bytes = file_metadata.len();
    let bytes = fs::read(path)?;

    if bytes.is_empty() {
        return Err("Flight log file is empty (0 bytes)".into());
    }

    // Inspect header format
    let is_dat = bytes[0] == DAT_MAGIC;
    let (format_str, version_opt, details_offset_opt, scrambled_opt) = if is_dat {
        ("DJI .DAT Blackbox Recording".to_string(), None, None, None)
    } else if bytes.len() >= 100 {
        match TxtHeader::parse(&bytes[..101.min(bytes.len())]) {
            Ok(hdr) => (
                format!("DJI .txt (v{})", hdr.version),
                Some(hdr.version),
                Some(hdr.details_offset),
                Some(hdr.scrambled_flag != 0),
            ),
            Err(_) => ("DJI .txt (Unknown Version)".to_string(), None, None, None),
        }
    } else {
        ("Unknown Binary Telemetry Format".to_string(), None, None, None)
    };

    // Ingest telemetry dataset
    let dataset = flightreader_export::aggregate_buffer(&bytes, None)
        .map_err(|e| format!("Failed to parse flight log: {e}"))?;

    let file_name = path
        .file_name()
        .map(|s| s.to_string_lossy().to_string())
        .unwrap_or_else(|| "unknown".to_string());

    let file_size_formatted = format_file_size(file_size_bytes);
    let duration_formatted = format_duration(dataset.metadata.duration_seconds);

    let start_time_utc = dataset.metadata.start_time_utc.clone();
    let end_time_utc = dataset.metadata.end_time_utc.clone();

    let home_point = match (dataset.metadata.home_latitude, dataset.metadata.home_longitude) {
        (Some(lat), Some(lon)) => Some(HomePointInfo {
            latitude: lat,
            longitude: lon,
            altitude_msl: dataset.metadata.home_altitude_msl.unwrap_or(0.0),
        }),
        _ => None,
    };

    let bounding_box = if dataset.points.is_empty() {
        None
    } else {
        let mut min_lat = f64::INFINITY;
        let mut max_lat = f64::NEG_INFINITY;
        let mut min_lon = f64::INFINITY;
        let mut max_lon = f64::NEG_INFINITY;
        for pt in &dataset.points {
            if pt.latitude.abs() > 1e-6 || pt.longitude.abs() > 1e-6 {
                min_lat = min_lat.min(pt.latitude);
                max_lat = max_lat.max(pt.latitude);
                min_lon = min_lon.min(pt.longitude);
                max_lon = max_lon.max(pt.longitude);
            }
        }
        if min_lat.is_finite() {
            Some(BoundingBoxInfo { min_lat, max_lat, min_lon, max_lon })
        } else {
            None
        }
    };

    // Derive battery metrics if available
    let (start_soc, min_soc, min_voltage) = derive_battery_metrics(&dataset);
    let battery_summary = if start_soc.is_some() || min_soc.is_some() || min_voltage.is_some() {
        Some(BatterySummaryInfo {
            start_soc_pct: start_soc,
            min_soc_pct: min_soc,
            min_voltage_mv: min_voltage,
        })
    } else {
        None
    };

    let aircraft_name = dataset
        .metadata
        .aircraft_model
        .clone()
        .or_else(|| dataset.metadata.aircraft_name.clone())
        .unwrap_or_else(|| "DJI Aircraft".to_string());

    let max_speed_kmh = dataset.metadata.max_horizontal_speed_mps * 3.6;

    let output = FlightInfoOutput {
        file_name,
        file_size_bytes,
        file_size_formatted,
        format: format_str,
        version: version_opt,
        details_offset: details_offset_opt,
        scrambled: scrambled_opt,
        aircraft_name,
        total_points: dataset.points.len(),
        duration_seconds: dataset.metadata.duration_seconds,
        duration_formatted,
        total_distance_meters: dataset.metadata.total_distance_meters,
        max_altitude_msl: dataset.metadata.max_altitude_msl_m,
        max_altitude_agl: dataset.metadata.max_altitude_agl_m,
        max_ground_speed_mps: dataset.metadata.max_horizontal_speed_mps,
        max_ground_speed_kmh: max_speed_kmh,
        start_time_utc,
        end_time_utc,
        home_point,
        bounding_box,
        battery_summary,
        events_count: dataset.events.len(),
    };

    if args.json {
        let json_str = serde_json::to_string_pretty(&output)?;
        println!("{json_str}");
    } else {
        print_human_summary(&output, path);
    }

    Ok(())
}

fn derive_battery_metrics(dataset: &FlightDataset) -> (Option<u8>, Option<u8>, Option<u32>) {
    let mut start_soc = None;
    let mut min_soc = None;
    let mut min_volts = None;

    for pt in &dataset.points {
        if pt.battery_pct > 0 && pt.battery_pct <= 100 {
            if start_soc.is_none() {
                start_soc = Some(pt.battery_pct);
            }
            min_soc = Some(min_soc.map_or(pt.battery_pct, |m: u8| m.min(pt.battery_pct)));
        }
        if pt.battery_voltage_mv > 0 {
            min_volts = Some(min_volts.map_or(pt.battery_voltage_mv, |m: u32| m.min(pt.battery_voltage_mv)));
        }
    }

    (start_soc, min_soc, min_volts)
}

fn print_human_summary(info: &FlightInfoOutput, path: &Path) {
    println!("================================================================================");
    println!("OPENFLIGHTREADER :: FLIGHT LOG SUMMARY");
    println!("================================================================================");
    println!("  Target File:       {}", path.display());
    println!("  File Size:         {} ({} bytes)", info.file_size_formatted, info.file_size_bytes);
    println!("  Format:            {}", info.format);
    if let Some(v) = info.version {
        println!("  Version:           {}", v);
    }
    if let Some(off) = info.details_offset {
        println!("  Details Offset:    0x{:X} ({})", off, off);
    }
    if let Some(scrambled) = info.scrambled {
        println!("  Scrambled:         {}", if scrambled { "Yes (XOR / AES)" } else { "No (Plaintext)" });
    }
    println!("--------------------------------------------------------------------------------");
    println!("  Aircraft Model:    {}", info.aircraft_name);
    println!("  Total Samples:     {}", info.total_points);
    println!("  Flight Duration:   {} ({:.2} s)", info.duration_formatted, info.duration_seconds);
    println!("  Flight Distance:   {:.2} m ({:.2} km)", info.total_distance_meters, info.total_distance_meters / 1000.0);
    println!("  Max Altitude MSL:  {:.2} m", info.max_altitude_msl);
    println!("  Max Altitude AGL:  {:.2} m", info.max_altitude_agl);
    println!("  Max Ground Speed:  {:.2} m/s ({:.2} km/h)", info.max_ground_speed_mps, info.max_ground_speed_kmh);
    println!("--------------------------------------------------------------------------------");
    if let Some(start) = &info.start_time_utc {
        println!("  Start Time (UTC):  {}", start);
    }
    if let Some(end) = &info.end_time_utc {
        println!("  End Time (UTC):    {}", end);
    }
    if let Some(hp) = &info.home_point {
        println!("  Home Point:        Lat {:.7}°, Lon {:.7}°, Alt {:.1} m MSL", hp.latitude, hp.longitude, hp.altitude_msl);
    }
    if let Some(bb) = &info.bounding_box {
        println!("  Bounding Box:      Lat [{:.6}°, {:.6}°], Lon [{:.6}°, {:.6}°]", bb.min_lat, bb.max_lat, bb.min_lon, bb.max_lon);
    }
    if let Some(bat) = &info.battery_summary {
        let start_str = bat.start_soc_pct.map_or("-".to_string(), |v| format!("{v}%"));
        let min_str = bat.min_soc_pct.map_or("-".to_string(), |v| format!("{v}%"));
        let volt_str = bat.min_voltage_mv.map_or("-".to_string(), |v| format!("{:.2} V", v as f64 / 1000.0));
        println!("  Battery Health:    Start SOC: {}, Min SOC: {}, Lowest Pack: {}", start_str, min_str, volt_str);
    }
    println!("  Flight Events:     {} recorded", info.events_count);
    println!("================================================================================");
}

fn format_file_size(bytes: u64) -> String {
    const KB: u64 = 1024;
    const MB: u64 = 1024 * KB;
    const GB: u64 = 1024 * MB;

    if bytes >= GB {
        format!("{:.2} GB", bytes as f64 / GB as f64)
    } else if bytes >= MB {
        format!("{:.2} MB", bytes as f64 / MB as f64)
    } else if bytes >= KB {
        format!("{:.2} KB", bytes as f64 / KB as f64)
    } else {
        format!("{bytes} B")
    }
}

fn format_duration(seconds: f64) -> String {
    let total_secs = seconds.round() as u64;
    let hours = total_secs / 3600;
    let minutes = (total_secs % 3600) / 60;
    let secs = total_secs % 60;

    if hours > 0 {
        format!("{:02}:{:02}:{:02}", hours, minutes, secs)
    } else {
        format!("{:02}:{:02}", minutes, secs)
    }
}

