        let fly_time_ds = (elapsed_s * 10.0).round() as u16;
        osd[42..44].copy_from_slice(&fly_time_ds.to_le_bytes());

        // Record envelope: [type: u8, len: u16 LE, payload, delimiter: 0xFF]
        buf.push(1); // Type 1 (OSD)
        buf.push(53); // Len low
        buf.push(0); // Len high
        buf.extend_from_slice(&osd);
        buf.push(0xFF); // Trailer
    }

    buf
}

/// Constructs a synthetic valid DJI `.DAT` blackbox log with an IMU frame.
fn make_synthetic_dat_log() -> Vec<u8> {
    // Single 11-byte valid DAT frame
    vec![
        0x55, 0x0B, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00, 0x84, 0x51,
    ]
}

