//! Comprehensive integration tests for the `flightreader` CLI binary.

use std::fs;
use std::process::Command;
use tempfile::NamedTempFile;

/// Resolves path to the compiled `flightreader` binary.
fn flightreader_bin() -> Command {
    let bin_path = env!("CARGO_BIN_EXE_flightreader");
    Command::new(bin_path)
}

/// Constructs a synthetic valid 100-byte DJI `.txt` log (v6 plaintext) with embedded OSD records.
fn make_synthetic_txt_log() -> Vec<u8> {
    let mut buf = Vec::new();

    let total_records = 20;
    let record_size = 1 + 1 + 53 + 1; // 56 bytes: [type: 1B, len: 1B, payload: 53B, trailer: 1B]
    let details_offset: i64 = (100 + total_records * record_size) as i64;
    let header_length: i16 = 100;
    let version: u8 = 6;
    let department: u8 = 0; // DJIFly
    let scrambled_flag: u8 = 0; // Plaintext

    let mut hdr = vec![0u8; 100];
    hdr[0..8].copy_from_slice(&details_offset.to_le_bytes());
    hdr[8..10].copy_from_slice(&header_length.to_le_bytes());
    hdr[10] = version;
    hdr[11] = department;
    hdr[12] = scrambled_flag;
    buf.extend_from_slice(&hdr);

    // Add 20 OSD records (Type 1)
    for i in 0..total_records {
        let elapsed_s = i as f64 * 0.1;
        let lat = 37.774929 + (i as f64 * 0.00001);
        let lon = -122.419416 + (i as f64 * 0.000015);
        let height_m = 10.0 + i as f64 * 0.5;
        let speed_mps: f64 = 2.5;

        let mut osd = [0u8; 53];
        osd[0..8].copy_from_slice(&lon.to_radians().to_le_bytes());
        osd[8..16].copy_from_slice(&lat.to_radians().to_le_bytes());
        let height_scaled = (height_m * 10.0).round() as i16;
        osd[16..18].copy_from_slice(&height_scaled.to_le_bytes());
        let speed_scaled = (speed_mps * 10.0f64).round() as i16;
        osd[18..20].copy_from_slice(&speed_scaled.to_le_bytes());
        osd[30] |= 0x08; // Motor on
        let status = 0x80u32 | 1; // GPS mode
        osd[32..36].copy_from_slice(&status.to_le_bytes());
        let fly_time_ds = (elapsed_s * 10.0).round() as u16;
        osd[42..44].copy_from_slice(&fly_time_ds.to_le_bytes());

        // Record envelope: [type: u8, len: u8, payload, delimiter: 0xFF]
        buf.push(1); // Type 1 (OSD)
        buf.push(53); // Len (1 byte for v1-v6)
        buf.extend_from_slice(&osd);
        buf.push(0xFF); // Trailer
    }

    buf
}

/// Constructs a synthetic valid DJI `.DAT` blackbox log with an IMU frame.
fn make_synthetic_dat_log() -> Vec<u8> {
    // Single 11-byte valid DAT frame
    vec![
        0x55, 0x0B, 0x00, 0x01, 0x00, 0xE8, 0x03, 0x00, 0x00, 0x84, 0x51,
    ]
}

#[test]
fn test_cli_help_flag() {
    let output = flightreader_bin()
        .arg("--help")
        .output()
        .expect("Failed to execute flightreader binary");

    assert!(output.status.success());
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("OpenFlightReader"));
    assert!(stdout.contains("info"));
    assert!(stdout.contains("export"));
    assert!(stdout.contains("serve"));
}

#[test]
fn test_cli_version_flag() {
    let output = flightreader_bin()
        .arg("--version")
        .output()
        .expect("Failed to execute flightreader binary");

    assert!(output.status.success());
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("0.1.0"));
}

#[test]
fn test_cli_info_txt_human_readable() {
    let temp = NamedTempFile::new().unwrap();
    fs::write(temp.path(), make_synthetic_txt_log()).unwrap();

    let output = flightreader_bin()
        .arg("info")
        .arg(temp.path())
        .output()
        .expect("Failed to execute info command");

    assert!(output.status.success());
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("OPENFLIGHTREADER :: FLIGHT LOG SUMMARY"));
    assert!(stdout.contains("DJI .txt (v6)"));
    assert!(stdout.contains("Total Samples:"));
    assert!(stdout.contains("Flight Duration:"));
}

#[test]
fn test_cli_info_txt_json() {
    let temp = NamedTempFile::new().unwrap();
    fs::write(temp.path(), make_synthetic_txt_log()).unwrap();

    let output = flightreader_bin()
        .arg("info")
        .arg(temp.path())
        .arg("--json")
        .output()
        .expect("Failed to execute info command with --json");

    assert!(output.status.success());
    let stdout = String::from_utf8_lossy(&output.stdout);
    let json_val: serde_json::Value =
        serde_json::from_str(&stdout).expect("Stdout must be valid JSON");

    assert_eq!(json_val["format"], "DJI .txt (v6)");
    assert_eq!(json_val["version"], 6);
    assert_eq!(json_val["total_points"], 20);
    assert!(json_val["duration_seconds"].as_f64().unwrap() >= 0.0);
}

#[test]
fn test_cli_info_dat() {
    let temp = NamedTempFile::new().unwrap();
    fs::write(temp.path(), make_synthetic_dat_log()).unwrap();

    let output = flightreader_bin()
        .arg("info")
        .arg(temp.path())
        .output()
        .expect("Failed to execute info command on DAT file");

    assert!(output.status.success());
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("DJI .DAT Blackbox Recording"));
}

#[test]
fn test_cli_info_missing_file_error() {
    let output = flightreader_bin()
        .arg("info")
        .arg("/non/existent/path/flight_log_404.txt")
        .output()
        .expect("Failed to execute info command");

    assert!(!output.status.success());
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(stderr.contains("File not found") || stderr.contains("No such file"));
}

#[test]
fn test_cli_info_empty_file_error() {
    let temp = NamedTempFile::new().unwrap();

    let output = flightreader_bin()
        .arg("info")
        .arg(temp.path())
        .output()
        .expect("Failed to execute info command");

    assert!(!output.status.success());
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(stderr.contains("empty"));
}

#[test]
fn test_cli_export_csv_file() {
    let input_file = NamedTempFile::new().unwrap();
    fs::write(input_file.path(), make_synthetic_txt_log()).unwrap();

    let output_file = NamedTempFile::new().unwrap();

    let output = flightreader_bin()
        .arg("export")
        .arg(input_file.path())
        .arg("-f")
        .arg("csv")
        .arg("-o")
        .arg(output_file.path())
        .output()
        .expect("Failed to execute export command");

    assert!(output.status.success());
    let csv_content = fs::read_to_string(output_file.path()).unwrap();
    assert!(csv_content.starts_with("Time(millisecond)"));
    assert!(csv_content.contains("OSD.latitude"));
    assert!(csv_content.contains("OSD.longitude"));
    assert_eq!(csv_content.lines().count(), 21); // 1 header + 20 rows
}

#[test]
fn test_cli_export_kml_file() {
    let input_file = NamedTempFile::new().unwrap();
    fs::write(input_file.path(), make_synthetic_txt_log()).unwrap();

    let output_file = NamedTempFile::new().unwrap();

    let output = flightreader_bin()
        .arg("export")
        .arg(input_file.path())
        .arg("-f")
        .arg("kml")
        .arg("-o")
        .arg(output_file.path())
        .output()
        .expect("Failed to execute export command");

    assert!(output.status.success());
    let kml_content = fs::read_to_string(output_file.path()).unwrap();
    assert!(kml_content.contains("<?xml version=\"1.0\" encoding=\"UTF-8\"?>"));
    assert!(kml_content.contains("<kml xmlns=\"http://www.opengis.net/kml/2.2\">"));
    assert!(kml_content.contains("<LineString>"));
    assert!(kml_content.contains("<altitudeMode>absolute</altitudeMode>"));
}

#[test]
fn test_cli_export_gpx_file() {
    let input_file = NamedTempFile::new().unwrap();
    fs::write(input_file.path(), make_synthetic_txt_log()).unwrap();

    let output_file = NamedTempFile::new().unwrap();

    let output = flightreader_bin()
