    assert!(gpx_content.contains("<gpx version=\"1.1\""));
    assert!(gpx_content.contains("<trk>"));
    assert!(gpx_content.contains("<trkpt"));
}

#[test]
fn test_cli_export_geojson_file() {
    let input_file = NamedTempFile::new().unwrap();
    fs::write(input_file.path(), make_synthetic_txt_log()).unwrap();

    let output_file = NamedTempFile::new().unwrap();

