    assert!(output.status.success());
    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.starts_with("Time(millisecond)"));
}

#[test]
fn test_cli_export_filter_time_window() {
    let input_file = NamedTempFile::new().unwrap();
    fs::write(input_file.path(), make_synthetic_txt_log()).unwrap();

    let output_file = NamedTempFile::new().unwrap();

    let output = flightreader_bin()
        .arg("export")
        .arg(input_file.path())
        .arg("-f")
        .arg("csv")
        .arg("--start")
        .arg("0.5")
        .arg("--end")
        .arg("1.2")
        .arg("-o")
        .arg(output_file.path())
        .output()
        .expect("Failed to execute export command with time filter");

    assert!(output.status.success());
    let csv_content = fs::read_to_string(output_file.path()).unwrap();
    let lines: Vec<&str> = csv_content.lines().collect();
    assert!(lines.len() > 1, "Must contain filtered rows");
