        .arg("--start")
        .arg("10.0")
        .arg("--end")
        .arg("2.0")
        .output()
        .expect("Failed to execute export command");

    assert!(!output.status.success());
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(stderr.contains("cannot exceed") || stderr.contains("InvalidTimeWindow"));
}

