// Now let slow_stream attempt to read:
// With RecvError::Lagged properly handled, the send_task skips dropped messages
// and continues serving the client rather than abruptly resetting the connection.
let next_msg = tokio::time::timeout(std::time::Duration::from_millis(500), slow_stream.next()).await;

// Verify connection survives and receives messages or closes cleanly
match next_msg {
    Ok(Some(Ok(msg))) => {
        // Success: connection survived broadcast overrun and received message
        assert!(msg.is_text(), "Expected text frame from broadcaster, got {:?}", msg);
    }
    Ok(Some(Err(e))) => {
        panic!("Connection terminated on buffer overrun: {:?}", e);
    }
    Ok(None) => {
        panic!("WebSocket stream closed unexpectedly on buffer overrun");
    }
    Err(_) => {
        // Timeout is acceptable if no message was pending in buffer
    }
}

