/**
 * OpenFlightReader — Canvas Attitude Director Indicator (ADI)
 * Dark Aerospace / Cockpit Edition
 */
(function (global) {
    'use strict';

    class AdiRenderer {
        constructor(canvasId) {
            this.canvas = document.getElementById(canvasId);
            this.ctx = this.canvas.getContext('2d');
            this.width = this.canvas.width;
            this.height = this.canvas.height;
            this.cx = this.width / 2;
            this.cy = this.height / 2;
            this.radius = Math.min(this.cx, this.cy) - 10;

            this.pitch = 0;
            this.roll = 0;
            this.yaw = 0;

            this.pitchElem = document.getElementById('adi-pitch-val');
            this.rollElem = document.getElementById('adi-roll-val');
            this.yawElem = document.getElementById('adi-yaw-val');
            this.headingBadge = document.getElementById('adi-heading');

            this.render();
        }

        update(pitchDeg, rollDeg, yawDeg, headingDeg) {
            this.pitch = Math.max(-90, Math.min(90, pitchDeg || 0));
            this.roll = Math.max(-180, Math.min(180, rollDeg || 0));
            this.yaw = yawDeg || 0;

            if (this.pitchElem) this.pitchElem.textContent = `${this.pitch >= 0 ? '+' : ''}${this.pitch.toFixed(1)}°`;
            if (this.rollElem) this.rollElem.textContent = `${this.roll.toFixed(1)}°`;
            if (this.yawElem) this.yawElem.textContent = `${this.yaw.toFixed(1)}°`;
            if (this.headingBadge) this.headingBadge.textContent = `HDG ${Math.round(((headingDeg || 0) + 360) % 360).toString().padStart(3, '0')}°`;

            this.render();
        }

        render() {
            const ctx = this.ctx;
            ctx.clearRect(0, 0, this.width, this.height);

            // 1. Draw Horizon within Circular Clipping Mask
            ctx.save();
            ctx.beginPath();
            ctx.arc(this.cx, this.cy, this.radius, 0, Math.PI * 2);
            ctx.clip();

            // Transform for Roll and Pitch
            ctx.translate(this.cx, this.cy);
            ctx.rotate(this.roll * Math.PI / 180.0);
            const pitchShift = -(this.pitch / 90.0) * this.radius;
            ctx.translate(0, pitchShift);

            // Deep Stratospheric Sky Gradient (Top)
            const skyGrad = ctx.createLinearGradient(0, -this.radius * 2, 0, 0);
            skyGrad.addColorStop(0, '#082f49');
            skyGrad.addColorStop(1, '#0e7490');
            ctx.fillStyle = skyGrad;
            ctx.fillRect(-this.radius * 2, -this.radius * 3, this.radius * 4, this.radius * 3);

            // Deep Tactical Terrain Gradient (Bottom)
            const earthGrad = ctx.createLinearGradient(0, 0, 0, this.radius * 2);
            earthGrad.addColorStop(0, '#382314');
            earthGrad.addColorStop(1, '#1c1008');
            ctx.fillStyle = earthGrad;
            ctx.fillRect(-this.radius * 2, 0, this.radius * 4, this.radius * 3);

            // Crisp White Horizon Line with subtle neon glow
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(-this.radius * 2, 0);
            ctx.lineTo(this.radius * 2, 0);
            ctx.stroke();

            // Pitch Ladder Marks
            this.drawPitchLadder(ctx);

            ctx.restore();

            // 2. Fixed Outer Bezel and Reticle (Non-rotating)
            this.drawBezel(ctx);
            this.drawAircraftSymbol(ctx);
            this.drawBankScale(ctx);
        }

        drawPitchLadder(ctx) {
            ctx.save();
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.9)';
            ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
            ctx.font = '9px monospace';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.lineWidth = 1.5;

            const intervals = [-60, -45, -30, -20, -10, 10, 20, 30, 45, 60];
            for (const deg of intervals) {
                const y = -(deg / 90.0) * this.radius;
                const halfWidth = (Math.abs(deg) % 20 === 0) ? 24 : 14;

                ctx.beginPath();
                if (deg < 0) {
                    // Dashed for nose-down attitude
                    ctx.setLineDash([4, 4]);
                } else {
                    ctx.setLineDash([]);
                }

                ctx.moveTo(-halfWidth, y);
                ctx.lineTo(halfWidth, y);
                ctx.stroke();

                if (Math.abs(deg) % 20 === 0) {
                    ctx.fillText(Math.abs(deg).toString(), -halfWidth - 9, y);
                    ctx.fillText(Math.abs(deg).toString(), halfWidth + 9, y);
                }
            }
            ctx.restore();
        }

        drawAircraftSymbol(ctx) {
            ctx.save();
            ctx.translate(this.cx, this.cy);

            ctx.fillStyle = '#38bdf8';
            ctx.strokeStyle = '#06090e';
            ctx.lineWidth = 2;

            // Center Pip
            ctx.beginPath();
            ctx.arc(0, 0, 3.5, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();

            // Left Wing
            ctx.beginPath();
            ctx.rect(-34, -2, 22, 4);
            ctx.fill();
            ctx.stroke();

            // Right Wing
            ctx.beginPath();
            ctx.rect(12, -2, 22, 4);
            ctx.fill();
            ctx.stroke();

            ctx.restore();
        }

        drawBankScale(ctx) {
            ctx.save();
            ctx.translate(this.cx, this.cy);

            ctx.strokeStyle = 'rgba(255, 255, 255, 0.55)';
            ctx.lineWidth = 1.5;

            // Bank angle ticks: 0, +-10, +-20, +-30, +-45, +-60
            const bankTicks = [-60, -45, -30, -20, -10, 0, 10, 20, 30, 45, 60];
            for (const b of bankTicks) {
                const rad = (b - 90) * Math.PI / 180.0;
                const r0 = this.radius;
                const r1 = this.radius - (b === 0 ? 8 : (Math.abs(b) % 30 === 0 ? 6 : 4));

                ctx.beginPath();
                ctx.moveTo(r0 * Math.cos(rad), r0 * Math.sin(rad));
                ctx.lineTo(r1 * Math.cos(rad), r1 * Math.sin(rad));
                ctx.stroke();
            }

            // Bank pointer triangle at top (telemetry cyan)
            ctx.fillStyle = '#38bdf8';
            ctx.beginPath();
            ctx.moveTo(0, -this.radius + 2);
            ctx.lineTo(-4, -this.radius + 10);
            ctx.lineTo(4, -this.radius + 10);
            ctx.closePath();
            ctx.fill();

            ctx.restore();
        }

        drawBezel(ctx) {
            ctx.save();
            // Outer Bezel Ring (slate border)
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 6;
            ctx.beginPath();
            ctx.arc(this.cx, this.cy, this.radius + 3, 0, Math.PI * 2);
            ctx.stroke();

            // Inner Aerospace Cyan Hairline
            ctx.strokeStyle = 'rgba(56, 189, 248, 0.35)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.arc(this.cx, this.cy, this.radius, 0, Math.PI * 2);
            ctx.stroke();

            ctx.restore();
        }
    }

    global.AdiRenderer = AdiRenderer;
})(window);

