/**
 * OpenFlightReader — Mode 2 Remote Controller Stick Visualizer
 * Dark Aerospace / Cockpit Edition
 */
(function (global) {
    'use strict';

    class SticksRenderer {
        constructor(canvasId) {
            this.canvas = document.getElementById(canvasId);
            this.ctx = this.canvas.getContext('2d');
            this.width = this.canvas.width;
            this.height = this.canvas.height;

            this.gimbalRadius = 38;
            this.travelRadius = 28;
            this.stickRadius = 8;

            this.leftCx = this.width * 0.28;
            this.rightCx = this.width * 0.72;
            this.cy = this.height / 2;

            this.leftReadout = document.getElementById('sticks-left-val');
            this.rightReadout = document.getElementById('sticks-right-val');

            this.update(0, 0, 0, 0);
        }

        normalize(val) {
            if (val == null || isNaN(val)) return 0.0;
            // Handle raw DJI 364..1684 counts if not pre-normalized
            if (val > 2.0 || val < -2.0) {
                if (val === 0) return 0.0;
                return Math.max(-1.0, Math.min(1.0, (val - 1024) / 660.0));
            }
            return Math.max(-1.0, Math.min(1.0, val));
        }

        update(throttle, rudder, elevator, aileron) {
            const t = this.normalize(throttle);
            const r = this.normalize(rudder);
            const e = this.normalize(elevator);
            const a = this.normalize(aileron);

            if (this.leftReadout) {
                this.leftReadout.textContent = `T: ${Math.round(t * 100)}% | R: ${Math.round(r * 100)}%`;
            }
            if (this.rightReadout) {
                this.rightReadout.textContent = `E: ${Math.round(e * 100)}% | A: ${Math.round(a * 100)}%`;
            }

            this.render(t, r, e, a);
        }

        render(t, r, e, a) {
            const ctx = this.ctx;
            ctx.clearRect(0, 0, this.width, this.height);

            // Left Gimbal (Throttle / Rudder)
            this.drawGimbal(ctx, this.leftCx, this.cy, 'LEFT (THR/RUD)');
            this.drawStick(ctx, this.leftCx + r * this.travelRadius, this.cy - t * this.travelRadius, r, t);

            // Right Gimbal (Elevator / Aileron)
            this.drawGimbal(ctx, this.rightCx, this.cy, 'RIGHT (ELE/AIL)');
            this.drawStick(ctx, this.rightCx + a * this.travelRadius, this.cy - e * this.travelRadius, a, e);
        }

        drawGimbal(ctx, cx, cy, label) {
            ctx.save();

            // Gimbal Well Radial Gradient (Obsidian to Void)
            const grad = ctx.createRadialGradient(cx, cy, 2, cx, cy, this.gimbalRadius);
            grad.addColorStop(0, '#111827');
            grad.addColorStop(1, '#06090e');
            ctx.fillStyle = grad;
            ctx.strokeStyle = '#1e293b';
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.arc(cx, cy, this.gimbalRadius, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();

            // Outer subtle cyan hairline
            ctx.strokeStyle = 'rgba(56, 189, 248, 0.2)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.arc(cx, cy, this.gimbalRadius + 2, 0, Math.PI * 2);
            ctx.stroke();

            // Crosshair Guidelines
            ctx.strokeStyle = 'rgba(56, 189, 248, 0.18)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx - this.gimbalRadius + 4, cy);
            ctx.lineTo(cx + this.gimbalRadius - 4, cy);
            ctx.moveTo(cx, cy - this.gimbalRadius + 4);
            ctx.lineTo(cx, cy + this.gimbalRadius - 4);
            ctx.stroke();

            // Concentric 50% circle (dashed)
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
            ctx.setLineDash([2, 3]);
            ctx.beginPath();
            ctx.arc(cx, cy, this.gimbalRadius * 0.5, 0, Math.PI * 2);
            ctx.stroke();
            ctx.setLineDash([]);

            ctx.restore();
        }

        drawStick(ctx, x, y, normX, normY) {
            ctx.save();

            // Determine deflection color
            const mag = Math.max(Math.abs(normX), Math.abs(normY));
            let fillColor = '#38bdf8'; // Nominal Cyan
            let glowColor = 'rgba(56, 189, 248, 0.4)';
            if (mag >= 0.95) {
                fillColor = '#ef4444'; // Limit Alert Crimson
                glowColor = 'rgba(239, 68, 68, 0.6)';
            } else if (mag >= 0.12) {
                fillColor = '#f59e0b'; // Deflected Amber
                glowColor = 'rgba(245, 158, 11, 0.5)';
            }

            // Outer Stick Glow
            ctx.shadowColor = glowColor;
            ctx.shadowBlur = 8;
            ctx.fillStyle = fillColor;
            ctx.strokeStyle = '#06090e';
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.arc(x, y, this.stickRadius, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();

            // Inner Center Pip
            ctx.shadowBlur = 0;
            ctx.fillStyle = '#ffffff';
            ctx.beginPath();
            ctx.arc(x, y, 2, 0, Math.PI * 2);
            ctx.fill();

            ctx.restore();
        }
    }

    global.SticksRenderer = SticksRenderer;
})(window);

