/* ============================================================================
   OpenFlightReader — Dark Aerospace / Cockpit Design System
   100% Offline Air-Gapped High-Performance Flight Telemetry Dashboard
   ============================================================================ */

/* Reset & Global Box Model */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

:root {
    /* Layered Obsidian & Slate Surfaces */
    --bg-void: #06090e;
    --bg-base: #0b0f17;
    --surface-1: #111827;
    --surface-2: #162032;
    --surface-3: #1e293b;
    --surface-glass: rgba(17, 24, 39, 0.88);

    /* Translucent Cockpit Grid & Borders */
    --border-color: rgba(255, 255, 255, 0.08);
    --border-subtle: rgba(255, 255, 255, 0.05);
    --border-accent: rgba(56, 189, 248, 0.35);
    --border-active: #38bdf8;

    /* Aviation Telemetry Accents */
    --accent-blue: #38bdf8;
    --accent-green: #10b981;
    --accent-amber: #f59e0b;
    --accent-red: #ef4444;

    /* Typography Hierarchy */
    --text-primary: #f8fafc;
    --text-secondary: #94a3b8;
    --text-muted: #64748b;
    --text-faint: #475569;

    --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    --font-mono: ui-monospace, "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;

    /* Directional Elevation Shadows (Craft floor: depth with offset & blur) */
    --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.5), 0 1px 2px rgba(0, 0, 0, 0.6);
    --shadow-md: 0 4px 14px rgba(0, 0, 0, 0.55), 0 1px 3px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 12px 28px rgba(0, 0, 0, 0.7), 0 4px 8px rgba(0, 0, 0, 0.5);
    --shadow-hud: 0 8px 24px rgba(0, 0, 0, 0.65);
}

/* Base Document Setup */
html, body {
    width: 100%;
    height: 100%;
    overflow: hidden;
    background-color: var(--bg-void);
    color: var(--text-primary);
    font-family: var(--font-sans);
    font-size: 13px;
    line-height: 1.45;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

body {
    display: flex;
    flex-direction: column;
}

/* Custom Cockpit Scrollbars */
::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}
::-webkit-scrollbar-track {
    background: var(--bg-base);
}
::-webkit-scrollbar-thumb {
    background: var(--surface-3);
    border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
    background: var(--accent-blue);
}

/* Text Selection */
::selection {
    background: rgba(56, 189, 248, 0.3);
    color: #ffffff;
}

/* Tabular Numerals Enforcement (Rock-solid, jitter-free readouts) */
.chip-val,
.hud-val,
.readout-val,
.stat-val,
.time-row,
.cell-volts-text,
.card-badge,
.status-indicator,
.btn-speed {
    font-variant-numeric: tabular-nums;
    font-feature-settings: "tnum" 1, "zero" 1;
}

/* ============================================================================
   1. Top Aerospace Header Bar
   ============================================================================ */
.app-header {
    height: 52px;
    background: linear-gradient(180deg, var(--surface-1) 0%, var(--bg-base) 100%);
    border-bottom: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 16px;
    gap: 16px;
    flex-shrink: 0;
    z-index: 100;
    box-shadow: var(--shadow-sm);
}

.header-brand {
    display: flex;
    align-items: center;
    gap: 10px;
    user-select: none;
}

.brand-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    background: rgba(56, 189, 248, 0.12);
    border: 1px solid rgba(56, 189, 248, 0.35);
    border-radius: 6px;
    color: var(--accent-blue);
    font-size: 15px;
    box-shadow: var(--shadow-sm);
}

.brand-title {
    font-weight: 700;
    font-size: 15px;
    letter-spacing: 0.5px;
    color: var(--text-primary);
}

.badge-offline {
    font-size: 11px;
    font-weight: 700;
    background-color: rgba(16, 185, 129, 0.12);
    color: var(--accent-green);
    border: 1px solid rgba(16, 185, 129, 0.4);
    border-radius: 4px;
    padding: 2px 8px;
    letter-spacing: 0.8px;
}

.header-summary {
    display: flex;
    align-items: center;
    gap: 8px;
    overflow-x: auto;
    padding: 4px 0;
}

.summary-chip {
    background: var(--surface-2);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 4px 10px;
    display: flex;
    flex-direction: column;
    min-width: 88px;
    transition: border-color 0.15s ease, background-color 0.15s ease;
}

.summary-chip:hover {
    border-color: rgba(56, 189, 248, 0.3);
    background: var(--surface-3);
}

.chip-label {
    font-size: 11px;
    font-weight: 700;
    color: var(--text-muted);
    letter-spacing: 0.6px;
    text-transform: uppercase;
}

.chip-val {
    font-size: 13px;
    font-weight: 600;
    font-family: var(--font-mono);
    color: var(--text-primary);
    white-space: nowrap;
    margin-top: 1px;
}

.header-actions {
    display: flex;
    align-items: center;
    gap: 8px;
}

/* Interactive Buttons */
.btn {
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 6px 12px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    transition: all 0.15s ease;
    background-color: var(--surface-2);
    color: var(--text-primary);
    user-select: none;
    box-shadow: var(--shadow-sm);
}

.btn:hover {
    background-color: var(--surface-3);
    border-color: rgba(255, 255, 255, 0.2);
    transform: translateY(-1px);
}

.btn:active {
    transform: translateY(0);
}

.btn-primary {
    background: linear-gradient(180deg, #0284c7 0%, #0369a1 100%);
    border-color: #38bdf8;
    color: #ffffff;
    box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
    background: linear-gradient(180deg, #0369a1 0%, #075985 100%);
    border-color: #7dd3fc;
}

.btn-secondary {
    background-color: var(--surface-2);
    color: var(--text-primary);
}

/* WebSocket Status Indicator */
.status-indicator {
    font-size: 11px;
    font-weight: 600;
    padding: 4px 10px;
    border-radius: 12px;
    border: 1px solid var(--border-color);
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.status-indicator::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 50%;
    display: inline-block;
}

.status-online {
    background-color: rgba(16, 185, 129, 0.12);
    color: var(--accent-green);
    border-color: rgba(16, 185, 129, 0.4);
}
.status-online::before {
    background-color: var(--accent-green);
}

.status-offline {
    background-color: rgba(245, 158, 11, 0.12);
    color: var(--accent-amber);
    border-color: rgba(245, 158, 11, 0.4);
}
.status-offline::before {
    background-color: var(--accent-amber);
}

/* ============================================================================
   2. Main Workspace Layout
   ============================================================================ */
.workspace {
    flex: 1;
    display: flex;
    overflow: hidden;
    position: relative;
    background-color: var(--bg-void);
}

.viewer-container {
    flex: 1;
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
}

.map-container {
    flex: 1;
    position: relative;
    background-color: #06090e;
}

#map, .canvas-container {
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
}

#trajectory-canvas {
    width: 100%;
    height: 100%;
    display: block;
}

/* Leaflet Dark Tactical Mission Styling */
.leaflet-container {
    background: #06090e !important;
    font-family: var(--font-sans) !important;
}

.leaflet-tile {
    /* Converts OSM light tiles into a tactical dark navy night radar basemap */
    filter: invert(100%) hue-rotate(180deg) brightness(80%) contrast(125%) !important;
}

.leaflet-bar {
    border: 1px solid var(--border-color) !important;
    box-shadow: var(--shadow-md) !important;
    border-radius: 6px !important;
    overflow: hidden;
}

.leaflet-bar a {
    background-color: var(--surface-1) !important;
    border-bottom: 1px solid var(--border-color) !important;
    color: var(--text-primary) !important;
    transition: background-color 0.15s ease, color 0.15s ease;
}

.leaflet-bar a:hover {
    background-color: var(--surface-3) !important;
    color: var(--accent-blue) !important;
}

.drone-leaflet-icon {
    display: flex;
    align-items: center;
    justify-content: center;
}

#drone-svg-marker {
    transition: transform 0.05s linear;
}

/* ============================================================================
   3. Cockpit Heads-Up Display (HUD) Overlay
   ============================================================================ */
.hud-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 500;
    padding: 14px;
}

.hud-card {
    position: absolute;
    background: var(--surface-glass);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(56, 189, 248, 0.25);
    border-radius: 8px;
    padding: 10px 14px;
    font-family: var(--font-mono);
    font-size: 11px;
    box-shadow: var(--shadow-hud);
    pointer-events: auto;
}

.hud-top-left {
    top: 14px;
    left: 14px;
    min-width: 175px;
}

.hud-top-right {
    top: 14px;
    right: 14px;
    min-width: 165px;
}

.hud-row {
    display: flex;
    justify-content: space-between;
    gap: 14px;
    margin-bottom: 4px;
}
.hud-row:last-child {
    margin-bottom: 0;
}

.hud-label {
    color: var(--text-muted);
    font-weight: 600;
    font-size: 11px;
}

.hud-val {
    font-weight: 700;
    color: var(--text-primary);
    font-size: 11px;
}

.badge-mode {
    color: var(--accent-blue);
    background: rgba(56, 189, 248, 0.12);
    padding: 1px 6px;
    border-radius: 4px;
    border: 1px solid rgba(56, 189, 248, 0.3);
}

.hud-alert {
    position: absolute;
    top: 64px;
    left: 50%;
    transform: translateX(-50%);
    background: rgba(239, 68, 68, 0.95);
    color: #ffffff;
    font-weight: 700;
    font-size: 12px;
    padding: 8px 18px;
    border-radius: 6px;
    border: 1px solid #fca5a5;
    box-shadow: var(--shadow-lg);
    animation: alert-pulse 1.5s infinite;
    z-index: 600;
    pointer-events: auto;
    letter-spacing: 0.5px;
}

@keyframes alert-pulse {
    0%, 100% {
        opacity: 1;
    }
    50% {
        opacity: 0.8;
    }
}

/* ============================================================================
   4. Timeline Scrubber & Bottom Control Deck
   ============================================================================ */
.timeline-bar {
    height: 56px;
    background: linear-gradient(180deg, var(--surface-1) 0%, var(--bg-base) 100%);
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    padding: 0 16px;
    gap: 16px;
    flex-shrink: 0;
    z-index: 50;
    box-shadow: var(--shadow-sm);
}

.playback-controls {
    display: flex;
    align-items: center;
    gap: 4px;
}

.btn-ctrl {
    background-color: var(--surface-2);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    border-radius: 6px;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: 12px;
    transition: all 0.15s ease;
}

.btn-ctrl:hover {
    background-color: var(--surface-3);
    border-color: rgba(255, 255, 255, 0.2);
    transform: translateY(-1px);
}

.btn-ctrl:active {
    transform: translateY(0);
}

.btn-play {
    width: 36px;
    height: 36px;
    background: linear-gradient(180deg, #0284c7 0%, #0369a1 100%);
    border-color: #38bdf8;
    color: #ffffff;
    font-size: 14px;
    font-weight: 700;
    box-shadow: var(--shadow-sm);
}

.btn-play:hover {
    background: linear-gradient(180deg, #0369a1 0%, #075985 100%);
    border-color: #7dd3fc;
}

.speed-controls {
    display: flex;
    gap: 2px;
    background: var(--surface-2);
    padding: 2px;
    border-radius: 6px;
    border: 1px solid var(--border-color);
}

.btn-speed {
    background: transparent;
    border: none;
    color: var(--text-secondary);
    padding: 4px 8px;
    font-size: 11px;
    font-weight: 600;
    cursor: pointer;
    border-radius: 4px;
    transition: all 0.15s ease;
}

.btn-speed:hover {
    color: var(--text-primary);
}

.btn-speed.active {
    background-color: rgba(56, 189, 248, 0.16);
    color: var(--accent-blue);
    font-weight: 700;
}

.slider-wrapper {
    flex: 1;
    position: relative;
    display: flex;
    align-items: center;
}

.event-markers-track {
    position: absolute;
    width: 100%;
    height: 6px;
    top: 50%;
    transform: translateY(-50%);
    pointer-events: none;
}

.event-marker-dot {
    position: absolute;
    width: 4px;
    height: 14px;
    top: -4px;
    background-color: var(--accent-amber);
    border-radius: 2px;
    cursor: pointer;
    pointer-events: auto;
    box-shadow: var(--shadow-sm);
    transition: transform 0.1s;
}

.event-marker-dot:hover {
    transform: scale(1.4);
    background-color: #fbbf24;
}

#timeline-slider {
    width: 100%;
    height: 6px;
    -webkit-appearance: none;
    appearance: none;
    background: var(--surface-3);
    border-radius: 3px;
    outline: none;
    cursor: pointer;
    transition: background 0.15s ease;
}

#timeline-slider::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: var(--accent-blue);
    border: 2px solid #ffffff;
    cursor: pointer;
    box-shadow: var(--shadow-sm);
    transition: transform 0.12s ease;
}

#timeline-slider::-webkit-slider-thumb:hover {
    transform: scale(1.25);
}

#timeline-slider::-moz-range-thumb {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: var(--accent-blue);
    border: 2px solid #ffffff;
    cursor: pointer;
    box-shadow: var(--shadow-sm);
}

.time-readouts {
    display: flex;
    flex-direction: column;
    min-width: 175px;
    font-family: var(--font-mono);
    font-size: 11px;
    gap: 1px;
}

.time-row {
    display: flex;
    justify-content: space-between;
    gap: 8px;
    font-size: 11px;
}

.time-lbl {
    color: var(--text-muted);
    font-weight: 600;
}

/* ============================================================================
   5. Right Side Aeronautical Instruments Panel
   ============================================================================ */
.instruments-panel {
    width: 290px;
    background: linear-gradient(180deg, var(--surface-1) 0%, var(--bg-base) 100%);
    border-left: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    padding: 12px;
    gap: 12px;
    overflow-y: auto;
    flex-shrink: 0;
}

.instrument-card {
    background: var(--surface-2);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    padding: 10px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    box-shadow: var(--shadow-sm);
    transition: border-color 0.15s ease;
}

.instrument-card:hover {
    border-color: rgba(56, 189, 248, 0.25);
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.card-title {
    font-size: 11px;
    font-weight: 700;
    color: var(--text-secondary);
    letter-spacing: 0.6px;
    text-transform: uppercase;
}

.card-badge {
    font-size: 11px;
    font-family: var(--font-mono);
    color: var(--accent-blue);
    background-color: rgba(56, 189, 248, 0.1);
    border: 1px solid rgba(56, 189, 248, 0.25);
    padding: 2px 7px;
    border-radius: 4px;
    font-weight: 600;
}

.canvas-wrapper {
    display: flex;
    justify-content: center;
    align-items: center;
    background: var(--bg-void);
    border-radius: 6px;
    padding: 4px;
    border: 1px solid var(--border-subtle);
}

.instrument-readouts {
    display: flex;
    justify-content: space-around;
    background-color: var(--surface-1);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 6px 8px;
}

.readout-col {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.readout-label {
    font-size: 11px;
    font-weight: 700;
    color: var(--text-muted);
    letter-spacing: 0.5px;
}

.readout-val {
    font-size: 12px;
    font-family: var(--font-mono);
    font-weight: 700;
    color: var(--text-primary);
}

/* Smart Battery Heatmap Monitor */
.battery-pack-summary {
    display: flex;
    justify-content: space-between;
    background-color: var(--surface-1);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 6px 10px;
}

.pack-stat {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.stat-lbl {
    font-size: 11px;
    color: var(--text-muted);
    font-weight: 700;
    letter-spacing: 0.5px;
}

.stat-val {
    font-size: 12px;
    font-family: var(--font-mono);
    font-weight: 700;
}

.stat-nominal {
    color: var(--accent-green);
}
.stat-warning {
    color: var(--accent-amber);
}
.stat-danger {
    color: var(--accent-red);
}

.battery-bars-container {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    height: 94px;
    gap: 3px;
    padding: 8px 6px 4px 6px;
    background-color: var(--bg-void);
    border: 1px solid var(--border-subtle);
    border-radius: 6px;
}

.cell-bar-wrapper {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    height: 100%;
}

.cell-volts-text {
    font-size: 11px;
    font-family: var(--font-mono);
    margin-bottom: 2px;
    color: var(--text-secondary);
}

.cell-bar-track {
    flex: 1;
    width: 100%;
    background-color: var(--surface-3);
    border-radius: 2px;
    position: relative;
    display: flex;
    align-items: flex-end;
    overflow: hidden;
    border: 1px solid rgba(255, 255, 255, 0.04);
}

.cell-bar-fill {
    width: 100%;
    border-radius: 2px;
    transition: height 0.12s ease, background-color 0.12s ease;
}

.cell-idx-text {
    font-size: 11px;
    color: var(--text-muted);
    margin-top: 3px;
    font-weight: 600;
}

/* ============================================================================
   6. Bottom Telemetry Charts Panel
   ============================================================================ */
.charts-panel {
    height: 220px;
    background: linear-gradient(180deg, var(--surface-1) 0%, var(--bg-base) 100%);
    border-top: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
}

.charts-nav {
    height: 34px;
    background-color: var(--surface-2);
    border-bottom: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    padding: 0 14px;
    gap: 8px;
}

.chart-tab {
    background: none;
    border: none;
    color: var(--text-secondary);
    font-size: 11px;
    font-weight: 600;
    padding: 5px 12px;
    cursor: pointer;
    border-radius: 4px;
    transition: all 0.15s ease;
}

.chart-tab:hover {
    color: var(--text-primary);
    background-color: rgba(255, 255, 255, 0.04);
}

.chart-tab.active {
    background-color: rgba(56, 189, 248, 0.12);
    color: var(--accent-blue);
    font-weight: 700;
    box-shadow: inset 0 -2px 0 var(--accent-blue);
}

.charts-legend-info {
    margin-left: auto;
    font-size: 11px;
    color: var(--text-muted);
}

.chart-viewport {
    flex: 1;
    position: relative;
    padding: 8px;
    background: var(--bg-void);
}

.chart-box {
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
    display: none;
    padding: 6px;
}

.chart-box.active {
    display: block;
}

/* uPlot Dark Cockpit Customization */
.uplot {
    font-family: var(--font-sans);
}

.u-cursor-x, .u-cursor-y {
    border-color: rgba(56, 189, 248, 0.5) !important;
}

.u-legend {
    font-size: 11px !important;
    color: var(--text-secondary) !important;
}

.u-legend .u-series th,
.u-legend .u-series td {
    padding: 2px 6px !important;
}

.u-legend .u-value {
    font-family: var(--font-mono) !important;
    font-variant-numeric: tabular-nums !important;
    color: var(--text-primary) !important;
}

/* ============================================================================
   OpenFlightReader — Dark Aerospace / Cockpit Design System
   100% Offline Air-Gapped High-Performance Flight Telemetry Dashboard
   ============================================================================ */

/* Reset & Global Box Model */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

:root {
    /* Layered Obsidian & Slate Surfaces */
    --bg-void: #06090e;
    --bg-base: #0b0f17;
    --surface-1: #111827;
    --surface-2: #162032;
    --surface-3: #1e293b;
    --surface-glass: rgba(17, 24, 39, 0.92);

    /* Translucent Cockpit Grid & Borders */
    --border-color: rgba(255, 255, 255, 0.08);
    --border-subtle: rgba(255, 255, 255, 0.05);
    --border-accent: rgba(56, 189, 248, 0.35);
    --border-active: #38bdf8;

    /* Aviation Telemetry Accents */
    --accent-blue: #38bdf8;
    --accent-green: #10b981;
    --accent-amber: #f59e0b;
    --accent-red: #ef4444;
    --accent-red-dark: #991b1b;

    /* Typography Hierarchy — WCAG AA Contrast Compliant (≥4.5:1 on dark surfaces) */
    --text-primary: #ffffff;
    --text-secondary: #cbd5e1;
    --text-muted: #94a3b8;
    --text-faint: #64748b;

    --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    --font-mono: ui-monospace, "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;

    /* Directional Elevation Shadows (Craft floor: depth with offset & blur) */
    --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.5), 0 1px 2px rgba(0, 0, 0, 0.6);
    --shadow-md: 0 4px 14px rgba(0, 0, 0, 0.55), 0 1px 3px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 12px 28px rgba(0, 0, 0, 0.7), 0 4px 8px rgba(0, 0, 0, 0.5);
    --shadow-hud: 0 8px 24px rgba(0, 0, 0, 0.65);
}

/* Base Document Setup */
html, body {
    width: 100%;
    height: 100%;
    overflow: hidden;
    background-color: var(--bg-void);
    color: var(--text-primary);
    font-family: var(--font-sans);
    font-size: 14px;
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

body {
    display: flex;
    flex-direction: column;
}

/* Custom Cockpit Scrollbars */
::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}
::-webkit-scrollbar-track {
    background: var(--bg-base);
}
::-webkit-scrollbar-thumb {
    background: var(--surface-3);
    border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
    background: var(--accent-blue);
}

/* Text Selection */
::selection {
    background: rgba(56, 189, 248, 0.3);
    color: #ffffff;
}

/* Tabular Numerals Enforcement (Rock-solid, jitter-free readouts) */
.chip-val,
.hud-val,
.readout-val,
.stat-val,
.time-row,
.cell-volts-text,
.card-badge,
.status-indicator,
.btn-speed {
    font-variant-numeric: tabular-nums;
    font-feature-settings: "tnum" 1, "zero" 1;
}

/* ============================================================================
   1. Top Aerospace Header Bar
   ============================================================================ */
.app-header {
    height: 52px;
    background: linear-gradient(180deg, var(--surface-1) 0%, var(--bg-base) 100%);
    border-bottom: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 16px;
    gap: 16px;
    flex-shrink: 0;
    z-index: 100;
    box-shadow: var(--shadow-sm);
}

.header-brand {
    display: flex;
    align-items: center;
    gap: 10px;
    user-select: none;
}

.brand-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    height: 28px;
    background: rgba(56, 189, 248, 0.12);
    border: 1px solid rgba(56, 189, 248, 0.35);
    border-radius: 6px;
    color: var(--accent-blue);
    font-size: 15px;
    box-shadow: var(--shadow-sm);
}

.brand-title {
    font-weight: 700;
    font-size: 15px;
    letter-spacing: 0.5px;
    color: var(--text-primary);
}

.badge-offline {
    font-size: 11px;
    font-weight: 700;
    background-color: rgba(16, 185, 129, 0.12);
    color: var(--accent-green);
    border: 1px solid rgba(16, 185, 129, 0.4);
    border-radius: 4px;
    padding: 2px 8px;
    letter-spacing: 0.8px;
}

.header-summary {
    display: flex;
    align-items: center;
    gap: 8px;
    overflow-x: auto;
    padding: 4px 0;
}

.summary-chip {
    background: var(--surface-2);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 4px 10px;
    display: flex;
    flex-direction: column;
    min-width: 88px;
    transition: border-color 0.15s ease, background-color 0.15s ease;
}

.summary-chip:hover {
    border-color: rgba(56, 189, 248, 0.3);
    background: var(--surface-3);
}

.chip-label {
    font-size: 11px;
    font-weight: 700;
    color: var(--text-muted);
    letter-spacing: 0.6px;
    text-transform: uppercase;
}

.chip-val {
    font-size: 13px;
    font-weight: 600;
    font-family: var(--font-mono);
    color: var(--text-primary);
    white-space: nowrap;
    margin-top: 1px;
}

.header-actions {
    display: flex;
    align-items: center;
    gap: 8px;
}

/* Interactive Buttons */
.btn {
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 6px 12px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    transition: all 0.15s ease;
    background-color: var(--surface-2);
    color: var(--text-primary);
    user-select: none;
    box-shadow: var(--shadow-sm);
}

.btn:hover {
    background-color: var(--surface-3);
    border-color: rgba(255, 255, 255, 0.2);
    transform: translateY(-1px);
}

.btn:active {
    transform: translateY(0);
}

.btn-primary {
    background: linear-gradient(180deg, #0284c7 0%, #0369a1 100%);
    border-color: #38bdf8;
    color: #ffffff;
    box-shadow: var(--shadow-sm);
}

.btn-primary:hover {
    background: linear-gradient(180deg, #0369a1 0%, #075985 100%);
    border-color: #7dd3fc;
}

.btn-secondary {
    background-color: var(--surface-2);
    color: var(--text-primary);
}

/* WebSocket Status Indicator */
.status-indicator {
    font-size: 11px;
    font-weight: 600;
    padding: 4px 10px;
    border-radius: 12px;
    border: 1px solid var(--border-color);
    display: inline-flex;
    align-items: center;
    gap: 6px;
}

.status-indicator::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 50%;
    display: inline-block;
}

.status-online {
    background-color: rgba(16, 185, 129, 0.12);
    color: var(--accent-green);
    border-color: rgba(16, 185, 129, 0.4);
}
.status-online::before {
    background-color: var(--accent-green);
}

.status-offline {
    background-color: rgba(245, 158, 11, 0.12);
    color: var(--accent-amber);
    border-color: rgba(245, 158, 11, 0.4);
}
.status-offline::before {
    background-color: var(--accent-amber);
}

/* ============================================================================
   2. Main Workspace Layout
   ============================================================================ */
.workspace {
    flex: 1;
    display: flex;
    overflow: hidden;
    position: relative;
    background-color: var(--bg-void);
}

.viewer-container {
    flex: 1;
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
}

.map-container {
    flex: 1;
    position: relative;
    background-color: #06090e;
}

#map, .canvas-container {
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
}

#trajectory-canvas {
    width: 100%;
    height: 100%;
    display: block;
}

/* Leaflet Dark Tactical Mission Styling */
.leaflet-container {
    background: #06090e !important;
    font-family: var(--font-sans) !important;
}

.leaflet-tile {
    /* Converts OSM light tiles into a tactical dark navy night radar basemap */
    filter: invert(100%) hue-rotate(180deg) brightness(80%) contrast(125%) !important;
}

.leaflet-bar {
    border: 1px solid var(--border-color) !important;
    box-shadow: var(--shadow-md) !important;
    border-radius: 6px !important;
    overflow: hidden;
}

.leaflet-bar a {
    background-color: var(--surface-1) !important;
    border-bottom: 1px solid var(--border-color) !important;
    color: var(--text-primary) !important;
    transition: background-color 0.15s ease, color 0.15s ease;
}

.leaflet-bar a:hover {
    background-color: var(--surface-3) !important;
    color: var(--accent-blue) !important;
}

.drone-leaflet-icon {
    display: flex;
    align-items: center;
    justify-content: center;
}

#drone-svg-marker {
    transition: transform 0.05s linear;
}

/* ============================================================================
   3. Cockpit Heads-Up Display (HUD) Overlay
   ============================================================================ */
.hud-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 500;
    padding: 14px;
}

.hud-card {
    position: absolute;
    background: var(--surface-glass);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(56, 189, 248, 0.25);
    border-radius: 8px;
    padding: 10px 14px;
    font-family: var(--font-mono);
    font-size: 12px;
    box-shadow: var(--shadow-hud);
    pointer-events: auto;
}

.hud-top-left {
    top: 14px;
    left: 14px;
    min-width: 180px;
}

.hud-top-right {
    top: 14px;
    right: 14px;
    min-width: 170px;
}

.hud-row {
    display: flex;
    justify-content: space-between;
    gap: 14px;
    margin-bottom: 4px;
}
.hud-row:last-child {
    margin-bottom: 0;
}

.hud-label {
    color: var(--text-muted);
    font-weight: 600;
    font-size: 11px;
}

.hud-val {
    font-weight: 700;
    color: var(--text-primary);
    font-size: 12px;
}

.badge-mode {
    color: var(--accent-blue);
    background: rgba(56, 189, 248, 0.12);
    padding: 1px 6px;
    border-radius: 4px;
    border: 1px solid rgba(56, 189, 248, 0.3);
}

.hud-alert {
    position: absolute;
    top: 64px;
    left: 50%;
    transform: translateX(-50%);
    background: var(--accent-red-dark);
    color: #ffffff;
    font-weight: 700;
    font-size: 12px;
    padding: 8px 18px;
    border-radius: 6px;
    border: 1px solid #f87171;
    box-shadow: var(--shadow-lg);
    animation: alert-pulse 1.5s infinite;
    z-index: 600;
    pointer-events: auto;
    letter-spacing: 0.5px;
}

@keyframes alert-pulse {
    0%, 100% {
        opacity: 1;
    }
    50% {
        opacity: 0.8;
    }
}

/* ============================================================================
   4. Timeline Scrubber & Bottom Control Deck
   ============================================================================ */
.timeline-bar {
    height: 60px;
    background: linear-gradient(180deg, var(--surface-1) 0%, var(--bg-base) 100%);
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    padding: 8px 16px;
    gap: 16px;
    flex-shrink: 0;
    z-index: 50;
    box-shadow: var(--shadow-sm);
}

.playback-controls {
    display: flex;
    align-items: center;
    gap: 4px;
}

.btn-ctrl {
    background-color: var(--surface-2);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    border-radius: 6px;
    width: 30px;
    height: 30px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    font-size: 12px;
    transition: all 0.15s ease;
}

.btn-ctrl:hover {
    background-color: var(--surface-3);
    border-color: rgba(255, 255, 255, 0.2);
    transform: translateY(-1px);
}

.btn-ctrl:active {
    transform: translateY(0);
}

.btn-play {
    width: 36px;
    height: 36px;
    background: linear-gradient(180deg, #0284c7 0%, #0369a1 100%);
    border-color: #38bdf8;
    color: #ffffff;
    font-size: 14px;
    font-weight: 700;
    box-shadow: var(--shadow-sm);
}

.btn-play:hover {
    background: linear-gradient(180deg, #0369a1 0%, #075985 100%);
    border-color: #7dd3fc;
}

.speed-controls {
    display: flex;
    gap: 2px;
    background: var(--surface-2);
    padding: 2px;
    border-radius: 6px;
    border: 1px solid var(--border-color);
}

.btn-speed {
    background: transparent;
    border: none;
    color: var(--text-secondary);
    padding: 4px 8px;
    font-size: 11px;
    font-weight: 600;
    cursor: pointer;
    border-radius: 4px;
    transition: all 0.15s ease;
}

.btn-speed:hover {
    color: var(--text-primary);
}

.btn-speed.active {
    background-color: rgba(56, 189, 248, 0.16);
    color: var(--accent-blue);
    font-weight: 700;
}

.slider-wrapper {
    flex: 1;
    position: relative;
    display: flex;
    align-items: center;
}

.event-markers-track {
    position: absolute;
    width: 100%;
    height: 6px;
    top: 50%;
    transform: translateY(-50%);
    pointer-events: none;
}

.event-marker-dot {
    position: absolute;
    width: 4px;
    height: 14px;
    top: -4px;
    background-color: var(--accent-amber);
    border-radius: 2px;
    cursor: pointer;
    pointer-events: auto;
    box-shadow: var(--shadow-sm);
    transition: transform 0.1s;
}

.event-marker-dot:hover {
    transform: scale(1.4);
    background-color: #fbbf24;
}

#timeline-slider {
    width: 100%;
    height: 6px;
    -webkit-appearance: none;
    appearance: none;
    background: var(--surface-3);
    border-radius: 3px;
    outline: none;
    cursor: pointer;
    transition: background 0.15s ease;
}

#timeline-slider::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: var(--accent-blue);
    border: 2px solid #ffffff;
    cursor: pointer;
    box-shadow: var(--shadow-sm);
    transition: transform 0.12s ease;
}

#timeline-slider::-webkit-slider-thumb:hover {
    transform: scale(1.25);
}

#timeline-slider::-moz-range-thumb {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: var(--accent-blue);
    border: 2px solid #ffffff;
    cursor: pointer;
    box-shadow: var(--shadow-sm);
}

.time-readouts {
    display: flex;
    flex-direction: column;
    min-width: 180px;
    font-family: var(--font-mono);
    font-size: 11px;
    gap: 1px;
}

.time-row {
    display: flex;
    justify-content: space-between;
    gap: 8px;
    font-size: 11px;
}

.time-lbl {
    color: var(--text-muted);
    font-weight: 600;
}

/* ============================================================================
   5. Right Side Aeronautical Instruments Panel
   ============================================================================ */
.instruments-panel {
    width: 290px;
    background: linear-gradient(180deg, var(--surface-1) 0%, var(--bg-base) 100%);
    border-left: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    padding: 12px;
    gap: 12px;
    overflow-y: auto;
    flex-shrink: 0;
}

.instrument-card {
    background: var(--surface-2);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    padding: 10px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    box-shadow: var(--shadow-sm);
    transition: border-color 0.15s ease;
}

.instrument-card:hover {
    border-color: rgba(56, 189, 248, 0.25);
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.card-title {
    font-size: 11px;
    font-weight: 700;
    color: var(--text-secondary);
    letter-spacing: 0.6px;
    text-transform: uppercase;
}

.card-badge {
    font-size: 11px;
    font-family: var(--font-mono);
    color: var(--accent-blue);
    background-color: rgba(56, 189, 248, 0.1);
    border: 1px solid rgba(56, 189, 248, 0.25);
    padding: 2px 7px;
    border-radius: 4px;
    font-weight: 600;
}

.canvas-wrapper {
    display: flex;
    justify-content: center;
    align-items: center;
    background: var(--bg-void);
    border-radius: 6px;
    padding: 4px;
    border: 1px solid var(--border-subtle);
}

.instrument-readouts {
    display: flex;
    justify-content: space-around;
    background-color: var(--surface-1);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 6px 8px;
}

.readout-col {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.readout-label {
    font-size: 11px;
    font-weight: 700;
    color: var(--text-muted);
    letter-spacing: 0.5px;
}

.readout-val {
    font-size: 12px;
    font-family: var(--font-mono);
    font-weight: 700;
    color: var(--text-primary);
}

/* Smart Battery Heatmap Monitor */
.battery-pack-summary {
    display: flex;
    justify-content: space-between;
    background-color: var(--surface-1);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 6px 10px;
}

.pack-stat {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.stat-lbl {
    font-size: 11px;
    color: var(--text-muted);
    font-weight: 700;
    letter-spacing: 0.5px;
}

.stat-val {
    font-size: 12px;
    font-family: var(--font-mono);
    font-weight: 700;
}

.stat-nominal {
    color: var(--accent-green);
}
.stat-warning {
    color: var(--accent-amber);
}
.stat-danger {
    color: var(--accent-red);
}

.battery-bars-container {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    height: 94px;
    gap: 3px;
    padding: 8px 6px 4px 6px;
    background-color: var(--bg-void);
    border: 1px solid var(--border-subtle);
    border-radius: 6px;
}

.cell-bar-wrapper {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    height: 100%;
}

.cell-volts-text {
    font-size: 11px;
    font-family: var(--font-mono);
    margin-bottom: 2px;
    color: var(--text-secondary);
}

.cell-bar-track {
    flex: 1;
    width: 100%;
    background-color: var(--surface-3);
    border-radius: 2px;
    position: relative;
    display: flex;
    align-items: flex-end;
    overflow: hidden;
    border: 1px solid rgba(255, 255, 255, 0.04);
}

.cell-bar-fill {
    width: 100%;
    border-radius: 2px;
    transition: height 0.12s ease, background-color 0.12s ease;
}

.cell-idx-text {
    font-size: 11px;
    color: var(--text-muted);
    margin-top: 3px;
    font-weight: 600;
}

/* ============================================================================
   6. Bottom Telemetry Charts Panel
   ============================================================================ */
.charts-panel {
    height: 220px;
    background: linear-gradient(180deg, var(--surface-1) 0%, var(--bg-base) 100%);
    border-top: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
}

.charts-nav {
    height: 34px;
    background-color: var(--surface-2);
    border-bottom: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    padding: 0 14px;
    gap: 8px;
}

.chart-tab {
    background: none;
    border: none;
    color: var(--text-secondary);
    font-size: 12px;
    font-weight: 600;
    padding: 5px 12px;
    cursor: pointer;
    border-radius: 4px;
    transition: all 0.15s ease;
}

.chart-tab:hover {
    color: var(--text-primary);
    background-color: rgba(255, 255, 255, 0.04);
}

.chart-tab.active {
    background-color: rgba(56, 189, 248, 0.12);
    color: var(--accent-blue);
    font-weight: 700;
    box-shadow: inset 0 -2px 0 var(--accent-blue);
}

.charts-legend-info {
    margin-left: auto;
    font-size: 11px;
    color: var(--text-muted);
}

.chart-viewport {
    flex: 1;
    position: relative;
    padding: 8px;
    background: var(--bg-void);
}

.chart-box {
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
    display: none;
    padding: 6px;
}

.chart-box.active {
    display: block;
}

/* uPlot Dark Cockpit Customization */
.uplot {
    font-family: var(--font-sans);
}

.u-cursor-x, .u-cursor-y {
    border-color: rgba(56, 189, 248, 0.5) !important;
}

.u-legend {
    font-size: 11px !important;
    color: var(--text-secondary) !important;
}

.u-legend .u-series th,
.u-legend .u-series td {
    padding: 2px 6px !important;
}

.u-legend .u-value {
    font-family: var(--font-mono) !important;
    font-variant-numeric: tabular-nums !important;
    color: var(--text-primary) !important;
}

