args.CodeContent:
/* ============================================================================
   OpenFlightReader — Dark Aerospace / Cockpit Design System
   100% Offline Air-Gapped High-Performance Flight Telemetry Dashboard
   ============================================================================ */

/* Reset & Global Box Model */
*, *::before, *::after {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
}

:root {
    /* Layered Obsidian & Slate Avionics Surfaces */
    --bg-void: #05080d;
    --bg-base: #0a0e17;
    --surface-1: #101622;
    --surface-2: #162030;
    --surface-3: #1e2a3e;
    --surface-glass: rgba(16, 22, 34, 0.94);

    /* Translucent Cockpit Grid & Bezel Accents */
    --border-color: rgba(255, 255, 255, 0.08);
    --border-subtle: rgba(255, 255, 255, 0.05);
    --border-accent: rgba(56, 189, 248, 0.35);
    --border-active: #38bdf8;

    /* Aviation Telemetry Accents */
    --accent-blue: #38bdf8;
    --accent-cyan-dark: #0284c7;
    --accent-green: #10b981;
    --accent-amber: #f59e0b;
    --accent-red: #ef4444;
    --accent-red-dark: #991b1b;

    /* Typography Hierarchy — Strictly WCAG AA Contrast Compliant (≥4.5:1) */
    --text-primary: #ffffff;
    --text-secondary: #cbd5e1;
    --text-muted: #94a3b8;
    --text-faint: #64748b;

    --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
    --font-mono: ui-monospace, "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;

    /* Directional Elevation Shadows (Offset + blur, zero flat halo) */
    --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.5), 0 1px 2px rgba(0, 0, 0, 0.6);
    --shadow-md: 0 4px 14px rgba(0, 0, 0, 0.6), 0 2px 4px rgba(0, 0, 0, 0.4);
    --shadow-lg: 0 12px 30px rgba(0, 0, 0, 0.75), 0 4px 10px rgba(0, 0, 0, 0.5);
    --shadow-hud: 0 8px 24px rgba(0, 0, 0, 0.7);
}

/* Base Document Setup */
html, body {
    width: 100%;
    height: 100%;
    overflow: hidden;
    background-color: var(--bg-void);
    color: var(--text-primary);
    font-family: var(--font-sans);
    font-size: 14px;
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

body {
    display: flex;
    flex-direction: column;
}

/* Custom Cockpit Scrollbars */
::-webkit-scrollbar {
    width: 6px;
    height: 6px;
}
::-webkit-scrollbar-track {
    background: var(--bg-base);
}
::-webkit-scrollbar-thumb {
    background: var(--surface-3);
    border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
    background: var(--accent-blue);
}

/* Text Selection */
::selection {
    background: rgba(56, 189, 248, 0.35);
    color: #ffffff;
}

/* Tabular Numerals Enforcement (Rock-solid, jitter-free readouts) */
.chip-val,
.hud-val,
.readout-val,
.stat-val,
.time-row,
.cell-volts-text,
.card-badge,
.status-indicator,
.btn-speed,
.heading-digital,
.tape-readout-window {
    font-variant-numeric: tabular-nums;
    font-feature-settings: "tnum" 1, "zero" 1;
}

/* ============================================================================
   1. Top Aerospace Avionics System Bar
   ============================================================================ */
.app-header {
    height: 54px;
    background: linear-gradient(180deg, var(--surface-1) 0%, var(--bg-base) 100%);
    border-bottom: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 16px;
    gap: 14px;
    flex-shrink: 0;
    z-index: 100;
    box-shadow: var(--shadow-sm);
}

.header-brand {
    display: flex;
    align-items: center;
    gap: 10px;
    user-select: none;
}

.brand-icon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    background: linear-gradient(135deg, rgba(56, 189, 248, 0.2) 0%, rgba(2, 132, 199, 0.1) 100%);
    border: 1px solid rgba(56, 189, 248, 0.4);
    border-radius: 6px;
    color: var(--accent-blue);
    box-shadow: var(--shadow-sm);
}

.brand-meta {
    display: flex;
    flex-direction: column;
}

.brand-title {
    font-weight: 800;
    font-size: 14px;
    letter-spacing: 0.8px;
    color: #ffffff;
    text-transform: uppercase;
}

.badge-offline {
    font-size: 11px;
    font-weight: 700;
    color: var(--accent-green);
    letter-spacing: 0.8px;
    line-height: 1;
    margin-top: 2px;
}

.header-summary {
    display: flex;
    align-items: center;
    gap: 8px;
    overflow-x: auto;
    padding: 2px 0;
}

.summary-chip {
    background: var(--surface-2);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 4px 10px;
    display: flex;
    flex-direction: column;
    min-width: 86px;
    transition: border-color 0.15s ease, background-color 0.15s ease;
}

.summary-chip:hover {
    border-color: rgba(56, 189, 248, 0.35);
    background: var(--surface-3);
}

.chip-label {
    font-size: 11px;
    font-weight: 700;
    color: var(--text-muted);
    letter-spacing: 0.6px;
    text-transform: uppercase;
}

.chip-val {
    font-size: 13px;
    font-weight: 600;
    font-family: var(--font-mono);
    color: var(--text-primary);
    white-space: nowrap;
    margin-top: 1px;
}

.header-actions {
    display: flex;
    align-items: center;
    gap: 8px;
}

/* Interactive Cockpit Buttons */
.btn {
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 6px 12px;
    font-size: 12px;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    transition: all 0.15s ease;
    background-color: var(--surface-2);
    color: var(--text-primary);
    user-select: none;
    box-shadow: var(--shadow-sm);
}

.btn:hover {
    background-color: var(--surface-3);
    border-color: rgba(255, 255, 255, 0.25);
    transform: translateY(-1px);
}

.btn:active {
    transform: translateY(0);
}

.btn-primary {
    background: linear-gradient(180deg, #0284c7 0%, #0369a1 100%);
    border-color: #38bdf8;
    color: #ffffff;
}

.btn-primary:hover {
    background: linear-gradient(180deg, #0369a1 0%, #075985 100%);
    border-color: #7dd3fc;
}

.btn-secondary {
    background-color: var(--surface-2);
    color: var(--text-primary);
}

.btn-demo {
    background: linear-gradient(180deg, rgba(245, 158, 11, 0.2) 0%, rgba(217, 119, 6, 0.15) 100%);
    border: 1px solid rgba(245, 158, 11, 0.5);
    color: #fbbf24;
}

.btn-demo:hover {
    background: linear-gradient(180deg, rgba(245, 158, 11, 0.3) 0%, rgba(217, 119, 6, 0.25) 100%);
    border-color: #f59e0b;
    color: #ffffff;
}

/* Status Indicator Pill */
.status-indicator {
    font-size: 11px;
    font-weight: 700;
    padding: 4px 10px;
    border-radius: 12px;
    border: 1px solid var(--border-color);
    display: inline-flex;
    align-items: center;
    gap: 6px;
    letter-spacing: 0.5px;
}

.status-indicator::before {
    content: '';
    width: 6px;
    height: 6px;
    border-radius: 50%;
    display: inline-block;
}

.status-online {
    background-color: rgba(16, 185, 129, 0.12);
    color: var(--accent-green);
    border-color: rgba(16, 185, 129, 0.4);
}
.status-online::before {
    background-color: var(--accent-green);
}

.status-offline {
    background-color: rgba(56, 189, 248, 0.12);
    color: var(--accent-blue);
    border-color: rgba(56, 189, 248, 0.4);
}
.status-offline::before {
    background-color: var(--accent-blue);
}

/* ============================================================================
   2. Main Workspace Layout & Tactical Viewport
   ============================================================================ */
.workspace {
    flex: 1;
    display: flex;
    overflow: hidden;
    position: relative;
    background-color: var(--bg-void);
}

.viewer-container {
    flex: 1;
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
}

.map-container {
    flex: 1;
    position: relative;
    background-color: #05080d;
}

#map, .canvas-container {
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
}

#trajectory-canvas {
    width: 100%;
    height: 100%;
    display: block;
}

/* Leaflet Tactical Mission Styling with Cybernetic Radar Pattern */
.leaflet-container {
    background: radial-gradient(circle at center, #0a111e 0%, #05080d 75%) !important;
    font-family: var(--font-sans) !important;
}

.leaflet-tile {
    filter: invert(100%) hue-rotate(180deg) brightness(75%) contrast(130%) !important;
}

.leaflet-bar {
    border: 1px solid var(--border-color) !important;
    box-shadow: var(--shadow-md) !important;
    border-radius: 6px !important;
    overflow: hidden;
}

.leaflet-bar a {
    background-color: var(--surface-1) !important;
    border-bottom: 1px solid var(--border-color) !important;
    color: var(--text-primary) !important;
    transition: background-color 0.15s ease, color 0.15s ease;
}

.leaflet-bar a:hover {
    background-color: var(--surface-3) !important;
    color: var(--accent-blue) !important;
}

.drone-leaflet-icon {
    display: flex;
    align-items: center;
    justify-content: center;
}

#drone-svg-marker {
    transition: transform 0.05s linear;
}

/* ============================================================================
   3. Standby Telemetry Ingest Card
   ============================================================================ */
.standby-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 400;
    pointer-events: none;
    transition: opacity 0.3s ease;
}

.standby-card {
    pointer-events: auto;
    background: var(--surface-glass);
    border: 1px solid rgba(56, 189, 248, 0.3);
    border-radius: 12px;
    padding: 32px 40px;
    max-width: 520px;
    text-align: center;
    box-shadow: var(--shadow-lg);
    backdrop-filter: blur(16px);
    -webkit-backdrop-filter: blur(16px);
}

.standby-reticle {
    width: 72px;
    height: 72px;
    margin: 0 auto 16px auto;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
}

.reticle-ring {
    position: absolute;
    border-radius: 50%;
    border: 1px solid rgba(56, 189, 248, 0.4);
}

.ring-outer {
    width: 100%;
    height: 100%;
    border: 1.5px dashed rgba(56, 189, 248, 0.45);
    animation: spin-cw 20s linear infinite;
}

.ring-inner {
    width: 60%;
    height: 60%;
    border: 1.5px solid rgba(56, 189, 248, 0.6);
}

.reticle-crosshair {
    position: absolute;
    background: rgba(56, 189, 248, 0.5);
}

.ch-h {
    width: 100%;
    height: 1px;
}

.ch-v {
    height: 100%;
    width: 1px;
}

.reticle-core {
    width: 8px;
    height: 8px;
    background: var(--accent-blue);
    border-radius: 50%;
    box-shadow: 0 0 8px rgba(56, 189, 248, 0.8);
}

@keyframes spin-cw {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

.standby-title {
    font-size: 16px;
    font-weight: 800;
    letter-spacing: 1px;
    color: #ffffff;
    margin-bottom: 8px;
}

.standby-desc {
    font-size: 13px;
    color: var(--text-secondary);
    line-height: 1.5;
    margin-bottom: 24px;
}

.standby-actions {
    display: flex;
    justify-content: center;
    gap: 12px;
    margin-bottom: 20px;
}

.btn-demo-large {
    background: linear-gradient(180deg, rgba(245, 158, 11, 0.25) 0%, rgba(217, 119, 6, 0.2) 100%);
    border: 1px solid #f59e0b;
    color: #fef3c7;
    padding: 10px 18px;
    font-size: 13px;
    font-weight: 700;
}

.btn-demo-large:hover {
    background: linear-gradient(180deg, rgba(245, 158, 11, 0.35) 0%, rgba(217, 119, 6, 0.3) 100%);
    color: #ffffff;
}

.btn-primary-large {
    background: linear-gradient(180deg, #0284c7 0%, #0369a1 100%);
    border: 1px solid #38bdf8;
    color: #ffffff;
    padding: 10px 18px;
    font-size: 13px;
    font-weight: 700;
}

.standby-footer {
    font-size: 11px;
    color: var(--text-faint);
    letter-spacing: 0.5px;
}

/* ============================================================================
   4. Glass Cockpit Primary Flight Display (PFD) HUD Overlay
   ============================================================================ */
.hud-overlay {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    z-index: 500;
    padding: 12px;
}

/* Top Heading Compass Ribbon */
.hud-heading-strip {
    position: absolute;
    top: 12px;
    left: 50%;
    transform: translateX(-50%);
    display: flex;
    flex-direction: column;
    align-items: center;
    pointer-events: auto;
}

.heading-lubber-line {
    color: var(--accent-blue);
    font-size: 12px;
    line-height: 1;
}

.heading-digital {
    background: var(--surface-glass);
    border: 1px solid rgba(56, 189, 248, 0.4);
    border-radius: 4px;
    padding: 3px 12px;
    font-family: var(--font-mono);
    font-size: 13px;
    font-weight: 700;
    color: #ffffff;
    box-shadow: var(--shadow-sm);
    letter-spacing: 0.8px;
}

/* Left Airspeed Tape */
.hud-speed-tape {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: var(--surface-glass);
    border: 1px solid rgba(56, 189, 248, 0.35);
    border-radius: 6px;
    padding: 8px 10px;
    font-family: var(--font-mono);
    box-shadow: var(--shadow-hud);
    pointer-events: auto;
    text-align: center;
    min-width: 84px;
}

.tape-header {
    font-size: 11px;
    font-weight: 700;
    color: var(--text-muted);
    letter-spacing: 0.8px;
    margin-bottom: 2px;
}

.tape-readout-window {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.tape-readout-window .hud-val {
    font-size: 16px;
    font-weight: 800;
    color: var(--accent-blue);
}

.tape-unit {
    font-size: 11px;
    color: var(--text-muted);
    font-weight: 600;
}

/* Right Altitude Tape */
.hud-alt-tape {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: var(--surface-glass);
    border: 1px solid rgba(56, 189, 248, 0.35);
    border-radius: 6px;
    padding: 8px 10px;
    font-family: var(--font-mono);
    box-shadow: var(--shadow-hud);
    pointer-events: auto;
    text-align: center;
    min-width: 90px;
}

.tape-sub-window {
    border-top: 1px solid var(--border-subtle);
    margin-top: 6px;
    padding-top: 4px;
    font-size: 11px;
    color: var(--text-secondary);
}

.tape-sub-label {
    font-size: 11px;
    color: var(--text-muted);
    margin-left: 2px;
}

.tape-vsi-window {
    border-top: 1px solid var(--border-subtle);
    margin-top: 4px;
    padding-top: 4px;
    display: flex;
    justify-content: space-between;
    font-size: 11px;
}

.vsi-label {
    color: var(--text-muted);
    font-weight: 700;
}

/* Corner HUD Brackets */
.hud-card {
    position: absolute;
    background: var(--surface-glass);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border: 1px solid rgba(56, 189, 248, 0.25);
    border-radius: 8px;
    padding: 10px 14px;
    font-family: var(--font-mono);
    font-size: 12px;
    box-shadow: var(--shadow-hud);
    pointer-events: auto;
}

.hud-top-left {
    top: 12px;
    left: 12px;
    min-width: 190px;
}

.hud-top-right {
    top: 12px;
    right: 12px;
    min-width: 175px;
}

.card-bracket-accent {
    position: absolute;
    width: 6px;
    height: 6px;
    border: 1.5px solid var(--accent-blue);
}

.card-bracket-accent.top-left { top: -1px; left: -1px; border-right: none; border-bottom: none; }
.card-bracket-accent.bottom-right { bottom: -1px; right: -1px; border-left: none; border-top: none; }
.card-bracket-accent.top-right { top: -1px; right: -1px; border-left: none; border-bottom: none; }
.card-bracket-accent.bottom-left { bottom: -1px; left: -1px; border-right: none; border-top: none; }

.hud-row {
    display: flex;
    justify-content: space-between;
    gap: 12px;
    margin-bottom: 4px;
}
.hud-row:last-child {
    margin-bottom: 0;
}

.hud-label {
    color: var(--text-muted);
    font-weight: 700;
    font-size: 11px;
    letter-spacing: 0.5px;
}

.hud-val {
    font-weight: 700;
    color: var(--text-primary);
    font-size: 12px;
}

.badge-mode {
    color: var(--accent-blue);
    background: rgba(56, 189, 248, 0.14);
    padding: 1px 6px;
    border-radius: 4px;
    border: 1px solid rgba(56, 189, 248, 0.35);
}

.hud-alert {
    position: absolute;
    top: 64px;
    left: 50%;
    transform: translateX(-50%);
    background: var(--accent-red-dark);
    color: #ffffff;
    font-weight: 700;
    font-size: 12px;
    padding: 8px 18px;
    border-radius: 6px;
    border: 1px solid #f87171;
    box-shadow: var(--shadow-lg);
    animation: alert-pulse 1.5s infinite;
    z-index: 600;
    pointer-events: auto;
    letter-spacing: 0.5px;
    display: flex;
    align-items: center;
    gap: 8px;
}

.alert-icon {
    font-size: 14px;
}

@keyframes alert-pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.8; }
}

/* ============================================================================
   5. Avionics Flight Data Recorder (FDR) Deck & Timeline
   ============================================================================ */
.timeline-bar {
    height: 60px;
    background: linear-gradient(180deg, var(--surface-1) 0%, var(--bg-base) 100%);
    border-top: 1px solid var(--border-color);
    border-bottom: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    padding: 8px 16px;
    gap: 14px;
    flex-shrink: 0;
    z-index: 50;
    box-shadow: var(--shadow-sm);
}

.playback-controls {
    display: flex;
    align-items: center;
    gap: 4px;
}

.btn-ctrl {
    background-color: var(--surface-2);
    border: 1px solid var(--border-color);
    color: var(--text-primary);
    border-radius: 6px;
    width: 32px;
    height: 32px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: all 0.15s ease;
}

.btn-ctrl:hover {
    background-color: var(--surface-3);
    border-color: rgba(255, 255, 255, 0.25);
    transform: translateY(-1px);
}

.btn-ctrl:active {
    transform: translateY(0);
}

.btn-play {
    width: 38px;
    height: 38px;
    background: linear-gradient(180deg, #0284c7 0%, #0369a1 100%);
    border-color: #38bdf8;
    color: #ffffff;
    box-shadow: var(--shadow-sm);
}

.btn-play:hover {
    background: linear-gradient(180deg, #0369a1 0%, #075985 100%);
    border-color: #7dd3fc;
}

.speed-controls {
    display: flex;
    gap: 2px;
    background: var(--surface-2);
    padding: 2px;
    border-radius: 6px;
    border: 1px solid var(--border-color);
}

.btn-speed {
    background: transparent;
    border: none;
    color: var(--text-secondary);
    padding: 4px 8px;
    font-size: 11px;
    font-weight: 600;
    cursor: pointer;
    border-radius: 4px;
    transition: all 0.15s ease;
}

.btn-speed:hover {
    color: var(--text-primary);
}

.btn-speed.active {
    background-color: rgba(56, 189, 248, 0.18);
    color: var(--accent-blue);
    font-weight: 700;
}

.slider-wrapper {
    flex: 1;
    position: relative;
    display: flex;
    align-items: center;
}

.event-markers-track {
    position: absolute;
    width: 100%;
    height: 6px;
    top: 50%;
    transform: translateY(-50%);
    pointer-events: none;
}

.event-marker-dot {
    position: absolute;
    width: 4px;
    height: 14px;
    top: -4px;
    background-color: var(--accent-amber);
    border-radius: 2px;
    cursor: pointer;
    pointer-events: auto;
    box-shadow: var(--shadow-sm);
    transition: transform 0.1s;
}

.event-marker-dot:hover {
    transform: scale(1.4);
    background-color: #fbbf24;
}

#timeline-slider {
    width: 100%;
    height: 6px;
    -webkit-appearance: none;
    appearance: none;
    background: var(--surface-3);
    border-radius: 3px;
    outline: none;
    cursor: pointer;
    transition: background 0.15s ease;
}

#timeline-slider::-webkit-slider-thumb {
    -webkit-appearance: none;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: var(--accent-blue);
    border: 2px solid #ffffff;
    cursor: pointer;
    box-shadow: var(--shadow-sm);
    transition: transform 0.12s ease;
}

#timeline-slider::-webkit-slider-thumb:hover {
    transform: scale(1.25);
}

#timeline-slider::-moz-range-thumb {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: var(--accent-blue);
    border: 2px solid #ffffff;
    cursor: pointer;
    box-shadow: var(--shadow-sm);
}

.time-readouts {
    display: flex;
    flex-direction: column;
    min-width: 190px;
    font-family: var(--font-mono);
    font-size: 11px;
    gap: 1px;
}

.time-row {
    display: flex;
    justify-content: space-between;
    gap: 8px;
    font-size: 11px;
}

.time-lbl {
    color: var(--text-muted);
    font-weight: 700;
    letter-spacing: 0.5px;
}

/* ============================================================================
   6. Right Side Aeronautical Multifunction Display (MFD)
   ============================================================================ */
.instruments-panel {
    width: 296px;
    background: linear-gradient(180deg, var(--surface-1) 0%, var(--bg-base) 100%);
    border-left: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    padding: 12px;
    gap: 12px;
    overflow-y: auto;
    flex-shrink: 0;
}

.instrument-card {
    background: var(--surface-2);
    border: 1px solid var(--border-color);
    border-radius: 8px;
    padding: 10px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    box-shadow: var(--shadow-sm);
    transition: border-color 0.15s ease;
    position: relative;
}

.instrument-card:hover {
    border-color: rgba(56, 189, 248, 0.3);
}

.card-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.title-with-led {
    display: flex;
    align-items: center;
    gap: 6px;
}

.led-indicator {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    display: inline-block;
}

.led-green {
    background: var(--accent-green);
    box-shadow: 0 1px 3px rgba(16, 185, 129, 0.6);
}

.led-cyan {
    background: var(--accent-blue);
    box-shadow: 0 1px 3px rgba(56, 189, 248, 0.6);
}

.card-title {
    font-size: 11px;
    font-weight: 800;
    color: var(--text-secondary);
    letter-spacing: 0.8px;
    text-transform: uppercase;
}

.card-badge {
    font-size: 11px;
    font-family: var(--font-mono);
    color: var(--accent-blue);
    background-color: rgba(56, 189, 248, 0.12);
    border: 1px solid rgba(56, 189, 248, 0.3);
    padding: 2px 7px;
    border-radius: 4px;
    font-weight: 700;
}

.canvas-wrapper {
    display: flex;
    justify-content: center;
    align-items: center;
    background: var(--bg-void);
    border-radius: 6px;
    padding: 4px;
    border: 1px solid var(--border-subtle);
    box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.7);
}

.instrument-readouts {
    display: flex;
    justify-content: space-around;
    background-color: var(--surface-1);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 6px 8px;
}

.readout-col {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.readout-label {
    font-size: 11px;
    font-weight: 700;
    color: var(--text-muted);
    letter-spacing: 0.5px;
}

.readout-val {
    font-size: 12px;
    font-family: var(--font-mono);
    font-weight: 700;
    color: var(--text-primary);
}

/* Smart Battery Heatmap Monitor */
.battery-pack-summary {
    display: flex;
    justify-content: space-between;
    background-color: var(--surface-1);
    border: 1px solid var(--border-color);
    border-radius: 6px;
    padding: 6px 10px;
}

.pack-stat {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.stat-lbl {
    font-size: 11px;
    color: var(--text-muted);
    font-weight: 700;
    letter-spacing: 0.5px;
}

.stat-val {
    font-size: 12px;
    font-family: var(--font-mono);
    font-weight: 700;
}

.stat-nominal { color: var(--accent-green); }
.stat-warning { color: var(--accent-amber); }
.stat-danger  { color: var(--accent-red); }

.battery-bars-container {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    height: 98px;
    gap: 3px;
    padding: 8px 6px 4px 6px;
    background-color: var(--bg-void);
    border: 1px solid var(--border-subtle);
    border-radius: 6px;
    box-shadow: inset 0 2px 6px rgba(0, 0, 0, 0.6);
}

.cell-bar-wrapper {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    height: 100%;
}

.cell-volts-text {
    font-size: 11px;
    font-family: var(--font-mono);
    margin-bottom: 2px;
    color: var(--text-secondary);
}

.cell-bar-track {
    flex: 1;
    width: 100%;
    background-color: var(--surface-3);
    border-radius: 2px;
    position: relative;
    display: flex;
    align-items: flex-end;
    overflow: hidden;
    border: 1px solid rgba(255, 255, 255, 0.04);
}

.cell-bar-fill {
    width: 100%;
    border-radius: 2px;
    transition: height 0.12s ease, background-color 0.12s ease;
}

.cell-idx-text {
    font-size: 11px;
    color: var(--text-muted);
    margin-top: 3px;
    font-weight: 700;
}

/* ============================================================================
   7. Bottom Telemetry Charts Panel
   ============================================================================ */
.charts-panel {
    height: 220px;
    background: linear-gradient(180deg, var(--surface-1) 0%, var(--bg-base) 100%);
    border-top: 1px solid var(--border-color);
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
}

.charts-nav {
    height: 34px;
    background-color: var(--surface-2);
    border-bottom: 1px solid var(--border-color);
    display: flex;
    align-items: center;
    padding: 0 14px;
    gap: 8px;
}

.chart-tab {
    background: none;
    border: none;
    color: var(--text-secondary);
    font-size: 12px;
    font-weight: 600;
    padding: 5px 12px;
    cursor: pointer;
    border-radius: 4px;
    transition: all 0.15s ease;
}

.chart-tab:hover {
    color: var(--text-primary);
    background-color: rgba(255, 255, 255, 0.04);
}

.chart-tab.active {
    background-color: rgba(56, 189, 248, 0.14);
    color: var(--accent-blue);
    font-weight: 700;
    box-shadow: inset 0 -2px 0 var(--accent-blue);
}

.charts-legend-info {
    margin-left: auto;
    font-size: 11px;
    color: var(--text-muted);
}

.chart-viewport {
    flex: 1;
    position: relative;
    padding: 8px;
    background: var(--bg-void);
}

.chart-box {
    width: 100%;
    height: 100%;
    position: absolute;
    top: 0;
    left: 0;
    display: none;
    padding: 6px;
}

.chart-box.active {
    display: block;
}

/* uPlot Dark Cockpit Customization */
.uplot {
    font-family: var(--font-sans);
}

.u-cursor-x, .u-cursor-y {
    border-color: rgba(56, 189, 248, 0.5) !important;
}

.u-legend {
    font-size: 11px !important;
    color: var(--text-secondary) !important;
}

.u-legend .u-series th,
.u-legend .u-series td {
    padding: 2px 6px !important;
}

.u-legend .u-value {
    font-family: var(--font-mono) !important;
    font-variant-numeric: tabular-nums !important;
    color: var(--text-primary) !important;
}

