/**
 * OpenFlightReader — Mode 2 Remote Controller Stick Visualizer
 * CNC Milled Gimbal Glass Cockpit Edition
 */
(function (global) {
    'use strict';

    class SticksRenderer {
        constructor(canvasId) {
            this.canvas = document.getElementById(canvasId);
            this.ctx = this.canvas.getContext('2d');
            this.width = this.canvas.width;
            this.height = this.canvas.height;

            this.gimbalRadius = 42;
            this.travelRadius = 30;
            this.stickRadius = 8;

            this.leftCx = this.width * 0.28;
            this.rightCx = this.width * 0.72;
            this.cy = this.height / 2;

            this.leftReadout = document.getElementById('sticks-left-val');
            this.rightReadout = document.getElementById('sticks-right-val');

            this.update(0, 0, 0, 0);
        }

        normalize(val) {
            if (val == null || isNaN(val)) return 0.0;
            // Handle raw DJI 364..1684 counts if not pre-normalized
            if (val > 2.0 || val < -2.0) {
                if (val === 0) return 0.0;
                return Math.max(-1.0, Math.min(1.0, (val - 1024) / 660.0));
            }
            return Math.max(-1.0, Math.min(1.0, val));
        }

        update(throttle, rudder, elevator, aileron) {
            const t = this.normalize(throttle);
            const r = this.normalize(rudder);
            const e = this.normalize(elevator);
            const a = this.normalize(aileron);

            if (this.leftReadout) {
                this.leftReadout.textContent = `T: ${Math.round(t * 100)}% | R: ${Math.round(r * 100)}%`;
            }
            if (this.rightReadout) {
                this.rightReadout.textContent = `E: ${Math.round(e * 100)}% | A: ${Math.round(a * 100)}%`;
            }

            this.render(t, r, e, a);
        }

        render(t, r, e, a) {
            const ctx = this.ctx;
            ctx.clearRect(0, 0, this.width, this.height);

            // Left Gimbal (Throttle / Rudder)
            this.drawGimbal(ctx, this.leftCx, this.cy);
            this.drawStick(ctx, this.leftCx, this.cy, this.leftCx + r * this.travelRadius, this.cy - t * this.travelRadius, r, t);

            // Right Gimbal (Elevator / Aileron)
            this.drawGimbal(ctx, this.rightCx, this.cy);
            this.drawStick(ctx, this.rightCx, this.cy, this.rightCx + a * this.travelRadius, this.cy - e * this.travelRadius, a, e);
        }

        drawGimbal(ctx, cx, cy) {
            ctx.save();

            // Gimbal Well Radial Gradient (Deep obsidian into void)
            const grad = ctx.createRadialGradient(cx, cy, 2, cx, cy, this.gimbalRadius);
            grad.addColorStop(0, '#101622');
            grad.addColorStop(1, '#05080d');
            ctx.fillStyle = grad;
            ctx.strokeStyle = '#1e2a3e';
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.arc(cx, cy, this.gimbalRadius, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();

            // Outer subtle cyan hairline
            ctx.strokeStyle = 'rgba(56, 189, 248, 0.25)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.arc(cx, cy, this.gimbalRadius + 2, 0, Math.PI * 2);
            ctx.stroke();

            // Concentric Limit Rings (25%, 50%, 75%)
            const rings = [0.33, 0.66, 1.0];
            ctx.strokeStyle = 'rgba(255, 255, 255, 0.08)';
            ctx.lineWidth = 1;
            for (const factor of rings) {
                ctx.beginPath();
                ctx.arc(cx, cy, this.travelRadius * factor, 0, Math.PI * 2);
                ctx.stroke();
            }

            // Crosshair Guidelines
            ctx.strokeStyle = 'rgba(56, 189, 248, 0.2)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(cx - this.gimbalRadius + 3, cy);
            ctx.lineTo(cx + this.gimbalRadius - 3, cy);
            ctx.moveTo(cx, cy - this.gimbalRadius + 3);
            ctx.lineTo(cx, cy + this.gimbalRadius - 3);
            ctx.stroke();

            ctx.restore();
        }

        drawStick(ctx, cx, cy, sx, sy, normX, normY) {
            ctx.save();

            // Dynamic deflection vector line from center to stick
            const dist = Math.hypot(sx - cx, sy - cy);
            if (dist > 2) {
                ctx.strokeStyle = 'rgba(56, 189, 248, 0.4)';
                ctx.lineWidth = 1.5;
                ctx.beginPath();
                ctx.moveTo(cx, cy);
                ctx.lineTo(sx, sy);
                ctx.stroke();
            }

            // Determine deflection color
            const mag = Math.max(Math.abs(normX), Math.abs(normY));
            let fillColor = '#38bdf8'; // Nominal Cyan
            if (mag >= 0.95) {
                fillColor = '#ef4444'; // Limit Alert Crimson
            } else if (mag >= 0.15) {
                fillColor = '#f59e0b'; // Deflected Amber
            }

            // Stick Head Outer Ring (Milled bezel)
            ctx.fillStyle = '#0a0e17';
            ctx.strokeStyle = fillColor;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.arc(sx, sy, this.stickRadius, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();

            // Stick Core Pip
            ctx.fillStyle = fillColor;
            ctx.beginPath();
            ctx.arc(sx, sy, 3.5, 0, Math.PI * 2);
            ctx.fill();

            ctx.restore();
        }
    }

    global.SticksRenderer = SticksRenderer;
})(window);

/**
 * OpenFlightReader — 12-Cell Smart Battery Voltage Heatmap & Health Monitor
 * Dark Aerospace / Cockpit Edition
 */
(function (global) {
    'use strict';

    class BatteryRenderer {
        constructor(containerId) {
            this.container = document.getElementById(containerId);
            this.voltsElem = document.getElementById('bat-pack-volts');
            this.ampsElem = document.getElementById('bat-pack-amps');
            this.deltaElem = document.getElementById('bat-pack-delta');
            this.tempBadge = document.getElementById('battery-temp-badge');
            this.renderedCellCount = 0;
        }

        update(cellVoltagesMv, socPct, packVoltageMv, tempC, currentA) {
            // Filter valid cells (voltage > 1.0V)
            const validCells = (cellVoltagesMv || []).filter(mv => mv > 1000);
            const cellCount = validCells.length;

            if (this.voltsElem) this.voltsElem.textContent = ((packVoltageMv || 0) / 1000.0).toFixed(2) + ' V';
            if (this.ampsElem) this.ampsElem.textContent = (currentA || 0).toFixed(1) + ' A';
            if (this.tempBadge) this.tempBadge.textContent = `${(tempC || 0).toFixed(1)}°C`;

            // Calculate Delta V (spread across cells in mV)
            let deltaMv = 0;
            if (cellCount > 1) {
                const maxV = Math.max(...validCells);
                const minV = Math.min(...validCells);
                deltaMv = Math.round(maxV - minV);
            }

            if (this.deltaElem) {
                this.deltaElem.textContent = `${deltaMv} mV`;
                this.deltaElem.className = 'stat-val ' + (deltaMv <= 30 ? 'stat-nominal' : (deltaMv <= 80 ? 'stat-warning' : 'stat-danger'));
            }

            // Rebuild DOM bars if cell count changed
            if (this.container && cellCount !== this.renderedCellCount) {
                this.buildBars(cellCount);
                this.renderedCellCount = cellCount;
            }

            // Update individual cell bars
            for (let i = 0; i < cellCount; i++) {
                const mv = validCells[i];
                const volts = (mv / 1000.0);
                const fillRatio = Math.max(0.08, Math.min(1.0, (mv - 3200) / (4350 - 3200)));
                const color = this.getCellColor(volts);

                const fillBar = document.getElementById(`cell-fill-${i}`);
                const textElem = document.getElementById(`cell-txt-${i}`);

                if (fillBar) {
                    fillBar.style.height = `${Math.round(fillRatio * 100)}%`;
                    fillBar.style.backgroundColor = color;
                }
                if (textElem) {
                    textElem.textContent = volts.toFixed(2);
                }
            }
        }

        getCellColor(volts) {
            if (volts >= 4.10) return '#34d399'; // High charge emerald
            if (volts >= 3.80) return '#10b981'; // Nominal green
            if (volts >= 3.65) return '#f59e0b'; // Caution amber
            if (volts >= 3.45) return '#f97316'; // Low orange
            return '#ef4444';                     // Critical crimson
        }

        buildBars(count) {
            if (!this.container) return;
            this.container.innerHTML = '';
            for (let i = 0; i < count; i++) {
                const wrapper = document.createElement('div');
                wrapper.className = 'cell-bar-wrapper';

                const txt = document.createElement('span');
                txt.className = 'cell-volts-text';
                txt.id = `cell-txt-${i}`;
                txt.textContent = '0.00';

                const track = document.createElement('div');
                track.className = 'cell-bar-track';

                const fill = document.createElement('div');
                fill.className = 'cell-bar-fill';
                fill.id = `cell-fill-${i}`;
                fill.style.height = '50%';
                fill.style.backgroundColor = '#10b981';

                track.appendChild(fill);

                const idx = document.createElement('span');
                idx.className = 'cell-idx-text';
                idx.textContent = `C${i + 1}`;

                wrapper.appendChild(txt);
                wrapper.appendChild(track);
                wrapper.appendChild(idx);

                this.container.appendChild(wrapper);
            }
        }
    }

    global.BatteryRenderer = BatteryRenderer;
})(window);

/**
 * OpenFlightReader — Autonomous 2D Canvas Trajectory & Radar Renderer
 * 100% Offline Air-Gapped Flight Path Visualization
 * Glass Cockpit & Tactical Radar Edition
 */
(function (global) {
    'use strict';

    const R_EARTH = 6378137.0; // WGS84 equatorial radius in meters

    class CanvasRenderer {
        constructor(canvasId) {
            this.canvas = document.getElementById(canvasId);
            this.ctx = this.canvas.getContext('2d');
            this.points = null;
            this.metadata = null;
            this.metricPoints = []; // [{ x: meters, y: meters, alt: meters }]
            this.originLat = 0;
            this.originLon = 0;

            // Viewport & Camera State
            this.panX = 0; // meters
            this.panY = 0; // meters
            this.scale = 1.0; // pixels per meter
            this.isDragging = false;
            this.dragStartX = 0;
            this.dragStartY = 0;

            this.initEvents();
            this.resize();
        }

        initEvents() {
            window.addEventListener('resize', () => this.resize());

            this.canvas.addEventListener('mousedown', (e) => {
                this.isDragging = true;
                this.dragStartX = e.clientX;
                this.dragStartY = e.clientY;
            });

            window.addEventListener('mousemove', (e) => {
                if (!this.isDragging) return;
                const dx = e.clientX - this.dragStartX;
                const dy = e.clientY - this.dragStartY;
                this.dragStartX = e.clientX;
                this.dragStartY = e.clientY;

                this.panX -= dx / this.scale;
                this.panY += dy / this.scale;
                this.render();
            });

            window.addEventListener('mouseup', () => {
                this.isDragging = false;
            });

            this.canvas.addEventListener('wheel', (e) => {
                e.preventDefault();
                const zoomFactor = e.deltaY < 0 ? 1.15 : 0.85;
                this.scale *= zoomFactor;
                this.render();
            });
        }

        resize() {
            if (!this.canvas.parentElement) return;
            const rect = this.canvas.parentElement.getBoundingClientRect();
            const dpr = window.devicePixelRatio || 1;
            this.canvas.width = rect.width * dpr;
            this.canvas.height = rect.height * dpr;
            this.ctx.setTransform(1, 0, 0, 1, 0, 0);
            this.ctx.scale(dpr, dpr);
            this.width = rect.width;
            this.height = rect.height;
            this.render();
        }

        loadDataset(points, metadata) {
            this.points = points;
            this.metadata = metadata;
            this.metricPoints = [];

            const latArr = points ? (points.latitudes || points.lat) : null;
            const lonArr = points ? (points.longitudes || points.lon) : null;
            const altArr = points ? (points.altitudes_agl || points.alt_agl) : null;

            if (!latArr || latArr.length === 0) return;

            // Use Home Point or first point as coordinate origin
            this.originLat = (metadata && metadata.home_latitude) ? metadata.home_latitude : latArr[0];
            this.originLon = (metadata && metadata.home_longitude) ? metadata.home_longitude : lonArr[0];
            const cosLat = Math.cos(this.originLat * Math.PI / 180.0);

            let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;

            for (let i = 0; i < latArr.length; i++) {
                const lat = latArr[i];
                const lon = lonArr[i];
                if (lat === 0 && lon === 0) {
                    this.metricPoints.push(null);
                    continue;
                }
                const x = (lon - this.originLon) * (Math.PI / 180.0) * R_EARTH * cosLat;
                const y = (lat - this.originLat) * (Math.PI / 180.0) * R_EARTH;
                const alt = altArr ? altArr[i] : 0;

                this.metricPoints.push({ x, y, alt });

                minX = Math.min(minX, x);
                maxX = Math.max(maxX, x);
                minY = Math.min(minY, y);
                maxY = Math.max(maxY, y);
            }

            // Auto-fit bounds
            const spanX = Math.max(20, maxX - minX);
            const spanY = Math.max(20, maxY - minY);
            this.panX = (minX + maxX) / 2;
            this.panY = (minY + maxY) / 2;
            const availableW = Math.max(100, this.width - 120);
            const availableH = Math.max(100, this.height - 120);
            this.scale = Math.min(availableW / spanX, availableH / spanY);
            this.render();
        }

        renderFrame(currentIndex) {
            this.currentIndex = currentIndex;
            this.render();
        }

        centerOnIndex(index) {
            if (!this.metricPoints[index]) return;
            this.panX = this.metricPoints[index].x;
            this.panY = this.metricPoints[index].y;
            this.render();
        }

        render() {
            const ctx = this.ctx;
            if (!ctx || !this.width || !this.height) return;
            ctx.clearRect(0, 0, this.width, this.height);

            // 1. Tactical Radar Grid & Concentric Rings
            this.drawRadarGrid(ctx);

            if (!this.metricPoints || this.metricPoints.length === 0) {
                this.drawStandbyDisplay(ctx);
                return;
            }

            // 2. Trajectory Polyline
            this.drawTrajectory(ctx);

            // 3. Home Point Marker
            this.drawHomePoint(ctx);

            // 4. Current Aircraft Symbol & Heading Vector
            if (this.currentIndex !== undefined && this.metricPoints[this.currentIndex]) {
                const cur = this.metricPoints[this.currentIndex];
                const headingArr = this.points.headings_deg || this.points.heading || this.points.yaws_deg || this.points.yaw;
                const heading = headingArr ? headingArr[this.currentIndex] : 0;
                this.drawAircraft(ctx, cur.x, cur.y, heading || 0);
            }

            // 5. Compass Rose & Metric Scale Bar
            this.drawScaleBar(ctx);
            this.drawCompass(ctx);
        }

        drawRadarGrid(ctx) {
            ctx.save();
            ctx.fillStyle = '#05080d';
            ctx.fillRect(0, 0, this.width, this.height);

            const cx = this.width / 2 - this.panX * this.scale;
            const cy = this.height / 2 + this.panY * this.scale;

            // Concentric Range Rings centered at (panX, panY)
            const ringDistances = [25, 50, 100, 200, 400, 800, 1600];
            ctx.strokeStyle = 'rgba(56, 189, 248, 0.12)';
            ctx.lineWidth = 1;

            ctx.font = '10px monospace';
            ctx.fillStyle = 'rgba(56, 189, 248, 0.4)';
            ctx.textAlign = 'left';

            for (const dist of ringDistances) {
                const rPix = dist * this.scale;
                if (rPix < 20 || rPix > Math.max(this.width, this.height) * 1.5) continue;

                ctx.beginPath();
                ctx.arc(cx, cy, rPix, 0, Math.PI * 2);
                ctx.stroke();

                ctx.fillText(`${dist}m`, cx + rPix + 4, cy - 4);
            }

            // Tactical Grid lines
            const targetPixelSpacing = 80;
            const rawMeters = targetPixelSpacing / (this.scale || 1.0);
            const magnitude = Math.pow(10, Math.floor(Math.log10(Math.max(1e-3, rawMeters))));
            let gridStepMeters = magnitude;
            if (rawMeters / magnitude > 5) gridStepMeters = 5 * magnitude;
            else if (rawMeters / magnitude > 2) gridStepMeters = 2 * magnitude;

            const gridStepPixels = gridStepMeters * this.scale;
            const startX = (this.width / 2 - this.panX * this.scale) % gridStepPixels;
            const startY = (this.height / 2 + this.panY * this.scale) % gridStepPixels;

            ctx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
            ctx.beginPath();
            for (let x = startX; x < this.width; x += gridStepPixels) {
                ctx.moveTo(x, 0); ctx.lineTo(x, this.height);
            }
            for (let y = startY; y < this.height; y += gridStepPixels) {
                ctx.moveTo(0, y); ctx.lineTo(this.width, y);
            }
            ctx.stroke();

            // Center Major Crosshairs
            ctx.strokeStyle = 'rgba(56, 189, 248, 0.25)';
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.moveTo(cx, 0); ctx.lineTo(cx, this.height);
            ctx.moveTo(0, cy); ctx.lineTo(this.width, cy);
            ctx.stroke();

            ctx.restore();
        }

        drawTrajectory(ctx) {
            ctx.save();
            ctx.lineWidth = 2.5;
            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';

            const pts = this.metricPoints;
            const curIdx = this.currentIndex || 0;

            for (let i = 1; i < pts.length; i++) {
                const p0 = pts[i - 1];
                const p1 = pts[i];
                if (!p0 || !p1) continue;

                const u0 = this.width / 2 + (p0.x - this.panX) * this.scale;
                const v0 = this.height / 2 - (p0.y - this.panY) * this.scale;
                const u1 = this.width / 2 + (p1.x - this.panX) * this.scale;
                const v1 = this.height / 2 - (p1.y - this.panY) * this.scale;

                // Aviation color gradient based on altitude
                const alt = p1.alt;
                if (alt < 15) ctx.strokeStyle = '#10b981';       // Low nominal green
                else if (alt < 60) ctx.strokeStyle = '#38bdf8';  // Standard cruise cyan
                else if (alt < 120) ctx.strokeStyle = '#f59e0b'; // High altitude amber
                else ctx.strokeStyle = '#ef4444';                // Ceiling red

                // Future path is dimmed
                ctx.globalAlpha = i <= curIdx ? 0.95 : 0.22;

                ctx.beginPath();
                ctx.moveTo(u0, v0);
                ctx.lineTo(u1, v1);
                ctx.stroke();
            }

            ctx.restore();
        }

        drawHomePoint(ctx) {
            const u = this.width / 2 + (0 - this.panX) * this.scale;
            const v = this.height / 2 - (0 - this.panY) * this.scale;

            ctx.save();
            ctx.fillStyle = '#f59e0b';
            ctx.strokeStyle = '#05080d';
            ctx.lineWidth = 2;

            ctx.beginPath();
            ctx.arc(u, v, 10, 0, Math.PI * 2);
            ctx.fill();
            ctx.stroke();

            ctx.fillStyle = '#05080d';
            ctx.font = 'bold 11px monospace';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillText('H', u, v);
            ctx.restore();
        }

        drawAircraft(ctx, x, y, headingDeg) {
            const u = this.width / 2 + (x - this.panX) * this.scale;
            const v = this.height / 2 - (y - this.panY) * this.scale;

            ctx.save();
            ctx.translate(u, v);

            // Heading Vector Projection Line
            const rad = headingDeg * Math.PI / 180.0;
            ctx.strokeStyle = 'rgba(56, 189, 248, 0.6)';
            ctx.lineWidth = 1.5;
            ctx.setLineDash([3, 3]);
            ctx.beginPath();
            ctx.moveTo(0, 0);
            ctx.lineTo(Math.sin(rad) * 40, -Math.cos(rad) * 40);
            ctx.stroke();
            ctx.setLineDash([]);

            ctx.rotate(rad);

            // Aircraft Tactical Chevron
            ctx.beginPath();
            ctx.moveTo(0, -16);
            ctx.lineTo(10, 11);
            ctx.lineTo(0, 5);
            ctx.lineTo(-10, 11);
            ctx.closePath();

            ctx.fillStyle = '#38bdf8';
            ctx.strokeStyle = '#ffffff';
            ctx.lineWidth = 2;
            ctx.fill();
            ctx.stroke();

            ctx.restore();
        }

        drawScaleBar(ctx) {
            ctx.save();
            const barPixelWidth = 100;
            const barMeters = barPixelWidth / (this.scale || 1.0);
            const label = barMeters >= 1000 ? `${(barMeters / 1000).toFixed(1)} km` : `${Math.round(barMeters)} m`;

            const x = 24;
            const y = this.height - 24;

            ctx.strokeStyle = '#94a3b8';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(x, y - 4);
            ctx.lineTo(x, y);
            ctx.lineTo(x + barPixelWidth, y);
            ctx.lineTo(x + barPixelWidth, y - 4);
            ctx.stroke();

            ctx.fillStyle = '#94a3b8';
            ctx.font = '11px monospace';
            ctx.textAlign = 'center';
            ctx.fillText(label, x + barPixelWidth / 2, y - 6);
            ctx.restore();
        }

        drawCompass(ctx) {
            ctx.save();
            const cx = this.width - 36;
            const cy = 36;

            ctx.translate(cx, cy);

            ctx.fillStyle = '#ef4444';
            ctx.beginPath();
            ctx.moveTo(0, -16);
            ctx.lineTo(5, 0);
            ctx.lineTo(-5, 0);
            ctx.closePath();
            ctx.fill();

            ctx.fillStyle = '#94a3b8';
            ctx.beginPath();
            ctx.moveTo(0, 16);
            ctx.lineTo(5, 0);
            ctx.lineTo(-5, 0);
            ctx.closePath();
            ctx.fill();

            ctx.font = 'bold 10px sans-serif';
            ctx.textAlign = 'center';
            ctx.fillStyle = '#ffffff';
            ctx.fillText('N', 0, -18);
            ctx.restore();
        }

        drawStandbyDisplay(ctx) {
            // Handled seamlessly by #standby-overlay DOM element
        }
    }

    global.CanvasRenderer = CanvasRenderer;
})(window);

