/**
 * OpenFlightReader — Main Application Controller & Cockpit Telemetry Bus
 * 100% Offline Air-Gapped Flight Telemetry Analysis Engine
 * Glass Cockpit & MFD Edition
 */
(function () {
    'use strict';

    // Application State
    const state = {
        metadata: null,
        points: null,
        pointCount: 0,
        currentIndex: 0,
        isPlaying: false,
        playbackSpeed: 1.0,
        renderMode: 'leaflet', // 'leaflet' | 'canvas'
        ws: null,
        wsConnected: false,
        lastFrameTime: 0,
        activeChart: 'alt-speed'
    };

    // Sub-module & Chart Instances
    let canvasRenderer = null;
    let adiRenderer = null;
    let sticksRenderer = null;
    let batteryRenderer = null;
    let leafletMap = null;
    let droneMarker = null;
    let homeMarker = null;
    let trajectoryPolyline = null;

    const charts = {
        'alt-speed': null,
        'attitude': null,
        'battery': null,
        'rc': null
    };

    // DOM Elements Map
    const elements = {
        slider: document.getElementById('timeline-slider'),
        btnPlayPause: document.getElementById('btn-play-pause'),
        btnJumpStart: document.getElementById('btn-jump-start'),
        btnJumpEnd: document.getElementById('btn-jump-end'),
        btnStepBack: document.getElementById('btn-step-back'),
        btnStepForward: document.getElementById('btn-step-forward'),
        btnToggleRenderer: document.getElementById('btn-toggle-renderer'),
        btnRecenter: document.getElementById('btn-recenter'),
        btnDemoFlight: document.getElementById('btn-demo-flight'),
        btnLoadDemo: document.getElementById('btn-load-demo'),
        fileInput: document.getElementById('file-input'),
        fileInputStandby: document.getElementById('file-input-standby'),
        wsStatus: document.getElementById('ws-status'),
        mapContainer: document.getElementById('map'),
        canvasContainer: document.getElementById('canvas-container'),
        standbyOverlay: document.getElementById('standby-overlay'),
        // Readout Labels
        timeFly: document.getElementById('time-fly'),
        timeTotal: document.getElementById('time-total'),
        timeUtc: document.getElementById('time-utc'),
        frameCounter: document.getElementById('frame-counter'),
        // HUD
        hudLat: document.getElementById('hud-lat'),
        hudLon: document.getElementById('hud-lon'),
        hudAltAgl: document.getElementById('hud-alt-agl'),
        hudAltMsl: document.getElementById('hud-alt-msl'),
        hudHSpd: document.getElementById('hud-h-spd'),
        hudVSpd: document.getElementById('hud-v-spd'),
        hudFlightMode: document.getElementById('hud-flight-mode'),
        hudMotors: document.getElementById('hud-motors'),
        hudSats: document.getElementById('hud-sats'),
        hudFailsafe: document.getElementById('hud-failsafe'),
        hudAlert: document.getElementById('hud-alert'),
        hudAlertText: document.getElementById('hud-alert-text'),
        hudHeadingDigital: document.getElementById('hud-heading-digital'),
        // Summary Chips
        sumAircraft: document.getElementById('summary-aircraft'),
        sumDuration: document.getElementById('summary-duration'),
        sumDistance: document.getElementById('summary-distance'),
        sumAltitude: document.getElementById('summary-altitude'),
        sumSpeed: document.getElementById('summary-speed'),
        sumBattery: document.getElementById('summary-battery'),
        sumRecords: document.getElementById('summary-records')
    };

    // Initialize Application
    document.addEventListener('DOMContentLoaded', () => {
        initSubmodules();
        bindEvents();
        initWebSocket();
        fetchFlightData();
    });

    function initSubmodules() {
        if (window.AdiRenderer) adiRenderer = new window.AdiRenderer('adi-canvas');
        if (window.SticksRenderer) sticksRenderer = new window.SticksRenderer('sticks-canvas');
        if (window.BatteryRenderer) batteryRenderer = new window.BatteryRenderer('battery-bars-container');
        if (window.CanvasRenderer) canvasRenderer = new window.CanvasRenderer('trajectory-canvas');
        initLeafletMap();
    }

    function initLeafletMap() {
        try {
            if (!window.L) {
                setRenderMode('canvas');
                return;
            }
            leafletMap = window.L.map('map', {
                zoomControl: true,
                attributionControl: false
            }).setView([0, 0], 2);

            // Attempt to load local tiles if available
            window.L.tileLayer('/tiles/{z}/{x}/{y}.png', {
                maxZoom: 19
            }).addTo(leafletMap);

            // Aircraft Icon (Aviation Cyan Chevron)
            const aircraftIcon = window.L.divIcon({
                className: 'drone-leaflet-icon',
                html: '<div id="drone-svg-marker" style="transform: rotate(0deg);"><svg width="30" height="30" viewBox="0 0 24 24"><path fill="#38bdf8" stroke="#05080d" stroke-width="2" d="M12 2L4 20L12 17L20 20L12 2Z"/></svg></div>',
                iconSize: [30, 30],
                iconAnchor: [15, 15]
            });
            droneMarker = window.L.marker([0, 0], { icon: aircraftIcon, zIndexOffset: 1000 }).addTo(leafletMap);

            // Home Icon (Warning Amber Dot)
            const homeIcon = window.L.divIcon({
                className: 'home-leaflet-icon',
                html: '<svg width="24" height="24" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="#f59e0b" stroke="#05080d" stroke-width="2"/><text x="12" y="16" font-size="11" font-weight="bold" text-anchor="middle" fill="#05080d">H</text></svg>',
                iconSize: [24, 24],
                iconAnchor: [12, 12]
            });
            homeMarker = window.L.marker([0, 0], { icon: homeIcon, zIndexOffset: 500 }).addTo(leafletMap);

            trajectoryPolyline = window.L.polyline([], {
                color: '#38bdf8',
                weight: 3.5,
                opacity: 0.95
            }).addTo(leafletMap);
        } catch (e) {
            console.warn('Leaflet initialization failed; defaulting to autonomous Canvas', e);
            setRenderMode('canvas');
        }
    }

    function bindEvents() {
        // Slider Scrubbing
        if (elements.slider) {
            elements.slider.addEventListener('input', (e) => {
                const idx = parseInt(e.target.value, 10);
                seekToIndex(idx, 'user');
            });
        }

        // Transport Controls
        if (elements.btnPlayPause) elements.btnPlayPause.addEventListener('click', togglePlayPause);
        if (elements.btnJumpStart) elements.btnJumpStart.addEventListener('click', () => seekToIndex(0, 'user'));
        if (elements.btnJumpEnd) elements.btnJumpEnd.addEventListener('click', () => seekToIndex(state.pointCount - 1, 'user'));
        if (elements.btnStepBack) elements.btnStepBack.addEventListener('click', () => seekToIndex(Math.max(0, state.currentIndex - 10), 'user'));
        if (elements.btnStepForward) elements.btnStepForward.addEventListener('click', () => seekToIndex(Math.min(state.pointCount - 1, state.currentIndex + 10), 'user'));

        // Speed Buttons
        document.querySelectorAll('.btn-speed').forEach(btn => {
            btn.addEventListener('click', () => {
                document.querySelectorAll('.btn-speed').forEach(b => b.classList.remove('active'));
                btn.classList.add('active');
                state.playbackSpeed = parseFloat(btn.dataset.speed);
                if (state.wsConnected) {
                    sendWsMessage({ type: 'playback', playing: state.isPlaying, speed: state.playbackSpeed, current_index: state.currentIndex });
                }
            });
        });

        // Renderer Toggle (Leaflet vs Canvas)
        if (elements.btnToggleRenderer) {
            elements.btnToggleRenderer.addEventListener('click', () => {
                setRenderMode(state.renderMode === 'leaflet' ? 'canvas' : 'leaflet');
            });
        }

        // Re-center
        if (elements.btnRecenter) elements.btnRecenter.addEventListener('click', recenterAircraft);

        // Demo Flight Ingestion Buttons
        if (elements.btnDemoFlight) {
            elements.btnDemoFlight.addEventListener('click', () => loadDemoFlight());
        }
        if (elements.btnLoadDemo) {
            elements.btnLoadDemo.addEventListener('click', () => loadDemoFlight());
        }

        // Chart Viewport Tabs
        document.querySelectorAll('.chart-tab').forEach(tab => {
            tab.addEventListener('click', () => {
                document.querySelectorAll('.chart-tab').forEach(t => t.classList.remove('active'));
                document.querySelectorAll('.chart-box').forEach(b => b.classList.remove('active'));
                tab.classList.add('active');
                state.activeChart = tab.dataset.chart;
                const targetId = `chart-container-${tab.dataset.chart}`;
                const targetBox = document.getElementById(targetId);
                if (targetBox) {
                    targetBox.classList.add('active');
                    if (charts[state.activeChart]) {
                        charts[state.activeChart].resize(targetBox.clientWidth, targetBox.clientHeight);
                    }
                }
            });
        });

        // File Upload Listeners
        if (elements.fileInput) elements.fileInput.addEventListener('change', handleFileUpload);
        if (elements.fileInputStandby) elements.fileInputStandby.addEventListener('change', handleFileUpload);

        window.addEventListener('dragover', (e) => e.preventDefault());
        window.addEventListener('drop', (e) => {
            e.preventDefault();
            if (e.dataTransfer && e.dataTransfer.files.length > 0) {
                uploadLogFile(e.dataTransfer.files[0]);
            }
        });

        // Keyboard Shortcuts
        window.addEventListener('keydown', (e) => {
            if (e.target && e.target.tagName === 'INPUT') return;
            switch (e.code) {
                case 'Space':
                    e.preventDefault();
                    togglePlayPause();
                    break;
                case 'ArrowLeft':
                    e.preventDefault();
                    seekToIndex(Math.max(0, state.currentIndex - (e.shiftKey ? 50 : 10)), 'user');
                    break;
                case 'ArrowRight':
                    e.preventDefault();
                    seekToIndex(Math.min(state.pointCount - 1, state.currentIndex + (e.shiftKey ? 50 : 10)), 'user');
                    break;
                case 'Home':
                    e.preventDefault();
                    seekToIndex(0, 'user');
                    break;
                case 'End':
                    e.preventDefault();
                    seekToIndex(state.pointCount - 1, 'user');
                    break;
            }
        });
    }

    function setRenderMode(mode) {
        state.renderMode = mode;
        const rendererLabel = document.getElementById('renderer-label');
        if (mode === 'canvas') {
            if (elements.mapContainer) elements.mapContainer.style.display = 'none';
            if (elements.canvasContainer) elements.canvasContainer.style.display = 'block';
            if (rendererLabel) rendererLabel.textContent = 'Map Mode';
            if (canvasRenderer) {
                canvasRenderer.resize();
                canvasRenderer.renderFrame(state.currentIndex);
            }
        } else {
            if (elements.canvasContainer) elements.canvasContainer.style.display = 'none';
            if (elements.mapContainer) elements.mapContainer.style.display = 'block';
            if (rendererLabel) rendererLabel.textContent = 'Canvas Mode';
            if (leafletMap) leafletMap.invalidateSize();
        }
    }

    async function fetchFlightData() {
        try {
            const [infoRes, pointsRes] = await Promise.all([
                fetch('/api/v1/flight/info'),
                fetch('/api/v1/flight/points')
            ]);

            if (!infoRes.ok || !pointsRes.ok) return;

            const info = await infoRes.json();
            const points = await pointsRes.json();

            if (info.loaded && points && (points.count > 0 || (points.latitudes && points.latitudes.length > 0))) {
                loadFlightData(info.metadata || info, points);
            }
        } catch (e) {
            console.error('Failed to load initial flight telemetry', e);
        }
    }

    function loadFlightData(metadata, points) {
        state.metadata = metadata || {};
        state.points = points;
        state.pointCount = points.count || (points.indices ? points.indices.length : (points.latitudes ? points.latitudes.length : 0));

        // Manage Standby Overlay Visibility
        if (elements.standbyOverlay) {
            elements.standbyOverlay.style.display = (state.pointCount > 0) ? 'none' : 'flex';
        }

        // Populate Summary System Bar
        if (elements.sumAircraft) elements.sumAircraft.textContent = state.metadata.aircraft_model || 'UAV Flight';
        if (elements.sumDuration) elements.sumDuration.textContent = formatDuration(state.metadata.flight_duration_seconds || state.metadata.duration_seconds || 0);
        if (elements.sumDistance) elements.sumDistance.textContent = ((state.metadata.total_distance_meters || 0) / 1000).toFixed(2) + ' km';
        if (elements.sumAltitude) elements.sumAltitude.textContent = (state.metadata.max_altitude_agl_m || 0).toFixed(1) + ' m';
        if (elements.sumSpeed) elements.sumSpeed.textContent = (state.metadata.max_horizontal_speed_mps || 0).toFixed(1) + ' m/s';
        if (elements.sumRecords) elements.sumRecords.textContent = `${state.pointCount.toLocaleString()} @ 10Hz`;

        if (elements.slider) {
            elements.slider.max = Math.max(0, state.pointCount - 1);
            elements.slider.value = 0;
        }

        // Update Map / Canvas Bounds
        if (state.pointCount > 0) {
            const latArr = points.latitudes || points.lat || [];
            const lonArr = points.longitudes || points.lon || [];
            const coords = [];
            for (let i = 0; i < state.pointCount; i++) {
                if (latArr[i] !== 0 || lonArr[i] !== 0) {
                    coords.push([latArr[i], lonArr[i]]);
                }
            }

            if (coords.length > 0 && leafletMap && trajectoryPolyline) {
                trajectoryPolyline.setLatLngs(coords);
                leafletMap.fitBounds(trajectoryPolyline.getBounds(), { padding: [50, 50] });
            }

            if (state.metadata.home_latitude && state.metadata.home_longitude && homeMarker) {
                homeMarker.setLatLng([state.metadata.home_latitude, state.metadata.home_longitude]);
            }

            // Load into Canvas Renderer
            if (canvasRenderer) {
                canvasRenderer.loadDataset(points, state.metadata);
            }

            // Initialize uPlot Charts
            initCharts(points);
        }

        seekToIndex(0, 'init');
    }

    function seekToIndex(index, source) {
        if (!state.points || state.pointCount === 0) return;
        index = Math.max(0, Math.min(state.pointCount - 1, index));
        state.currentIndex = index;

        if (elements.slider) elements.slider.value = index;

        // Telemetry point references
        const p = state.points;
        const lat = (p.latitudes || p.lat || [])[index] || 0;
        const lon = (p.longitudes || p.lon || [])[index] || 0;
        const altAgl = (p.altitudes_agl || p.alt_agl || [])[index] || 0;
        const altMsl = (p.altitudes_msl || p.alt_msl || [])[index] || 0;
        const spdH = (p.ground_speeds_mps || p.speed_h || p.ground_speed_mps || [])[index] || 0;
        const spdV = (p.climb_rates_mps || p.speed_v || p.climb_rate_mps || [])[index] || 0;
        const pitch = (p.pitches_deg || p.pitch || [])[index] || 0;
        const roll = (p.rolls_deg || p.roll || [])[index] || 0;
        const yaw = (p.yaws_deg || p.yaw || [])[index] || 0;
        const headingArr = p.headings_deg || p.heading || p.yaws_deg || p.yaw || [];
        const heading = headingArr[index] !== undefined ? headingArr[index] : yaw;
        const elapsed = (p.elapsed_s || [])[index] || (index * 0.1);
        const flyTime = (p.fly_time_s || [])[index] || (index * 0.1);
        const utcMs = (p.timestamp_utc_ms || p.timestamps_ms || [])[index] || 0;
        const mode = (p.flight_modes || p.flight_mode || [])[index] || 'P-GPS';
        const motors = (p.is_motor_on || [])[index] || false;
        const sats = (p.gps_satellites || [])[index] || 0;
        const failsafe = (p.is_failsafe_active || [])[index] || false;

        // Update Time Labels
        if (elements.timeFly) elements.timeFly.textContent = formatDuration(flyTime);
        if (elements.timeTotal) elements.timeTotal.textContent = formatDuration(elapsed);
        if (elements.timeUtc) elements.timeUtc.textContent = utcMs ? new Date(utcMs).toISOString().replace('T', ' ').replace('Z', ' UTC') : '—';
        if (elements.frameCounter) elements.frameCounter.textContent = `${index + 1} / ${state.pointCount}`;

        // Update PFD HUD
        if (elements.hudLat) elements.hudLat.textContent = lat.toFixed(6) + '°';
        if (elements.hudLon) elements.hudLon.textContent = lon.toFixed(6) + '°';
        if (elements.hudAltAgl) elements.hudAltAgl.textContent = altAgl.toFixed(1);
        if (elements.hudAltMsl) elements.hudAltMsl.textContent = altMsl.toFixed(1) + ' m';
        if (elements.hudHSpd) elements.hudHSpd.textContent = spdH.toFixed(1);
        if (elements.hudVSpd) elements.hudVSpd.textContent = spdV.toFixed(1) + ' m/s';
        if (elements.hudFlightMode) elements.hudFlightMode.textContent = mode || 'P-GPS';
        if (elements.hudMotors) elements.hudMotors.textContent = motors ? 'ARMED' : 'OFF';
        if (elements.hudSats) elements.hudSats.textContent = `${sats} SATS`;
        if (elements.hudFailsafe) elements.hudFailsafe.textContent = failsafe ? 'FAILSAFE' : 'NORMAL';

        // Update Map Marker
        if (state.renderMode === 'leaflet' && droneMarker && (lat !== 0 || lon !== 0)) {
            droneMarker.setLatLng([lat, lon]);
            const markerDiv = document.getElementById('drone-svg-marker');
            if (markerDiv) markerDiv.style.transform = `rotate(${heading}deg)`;
        }

        // Update Flight Instruments
        if (adiRenderer) adiRenderer.update(pitch, roll, yaw, heading);
        if (sticksRenderer) {
            const thr = (p.rc_throttles || p.rc_throttle || [])[index] || 0;
            const rud = (p.rc_rudders || p.rc_rudder || [])[index] || 0;
            const ele = (p.rc_elevators || p.rc_elevator || [])[index] || 0;
            const ail = (p.rc_ailerons || p.rc_aileron || [])[index] || 0;
            sticksRenderer.update(thr, rud, ele, ail);
        }
        if (batteryRenderer) {
            const cellVoltages = (p.cell_voltages_mv || [])[index] || [];
            const soc = (p.battery_pcts || p.battery_pct || [])[index] || 0;
            const packV = (p.battery_voltages_mv || p.battery_voltage_mv || [])[index] || 0;
            const tempC = (p.battery_temps_c || p.battery_temp_c || [])[index] || 0;
            const currA = (p.battery_current_a || [])[index] || 0;
            batteryRenderer.update(cellVoltages, soc, packV, tempC, currA);
            if (elements.sumBattery) elements.sumBattery.textContent = `${Math.round(soc)}%`;
        }

        if (state.renderMode === 'canvas' && canvasRenderer) {
            canvasRenderer.renderFrame(index);
        }

        // Update Active uPlot Chart Scrubber Cursor
        if (charts[state.activeChart]) {
            charts[state.activeChart].setCursor(index);
        }

        // Send WebSocket seek event if initiated by user
        if (source === 'user' && state.wsConnected) {
            sendWsMessage({ type: 'seek', index: index });
        }
    }

    function togglePlayPause() {
        if (!state.points || state.pointCount === 0) return;
        state.isPlaying = !state.isPlaying;
        if (elements.btnPlayPause) {
            elements.btnPlayPause.classList.toggle('btn-playing', state.isPlaying);
            elements.btnPlayPause.innerHTML = state.isPlaying
                ? '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>'
                : '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg>';
        }

        if (state.isPlaying) {
            state.lastFrameTime = performance.now();
            requestAnimationFrame(playbackLoop);
        }

        if (state.wsConnected) {
            sendWsMessage({ type: 'playback', playing: state.isPlaying, speed: state.playbackSpeed, current_index: state.currentIndex });
        }
    }

    function playbackLoop(timestamp) {
        if (!state.isPlaying) return;

        const deltaMs = timestamp - state.lastFrameTime;
        state.lastFrameTime = timestamp;

        // At 10 Hz, 1 point = 100 ms
        const pointsToAdvance = (deltaMs * state.playbackSpeed) / 100.0;
        const nextIndex = Math.min(state.pointCount - 1, state.currentIndex + Math.max(1, Math.round(pointsToAdvance)));

        if (nextIndex >= state.pointCount - 1) {
            seekToIndex(state.pointCount - 1, 'playback');
            togglePlayPause();
            return;
        }

        seekToIndex(nextIndex, 'playback');
        requestAnimationFrame(playbackLoop);
    }

    function recenterAircraft() {
        if (!state.points || state.pointCount === 0) return;
        const latArr = state.points.latitudes || state.points.lat || [];
        const lonArr = state.points.longitudes || state.points.lon || [];
        const lat = latArr[state.currentIndex];
        const lon = lonArr[state.currentIndex];
        if (state.renderMode === 'leaflet' && leafletMap && (lat !== 0 || lon !== 0)) {
            leafletMap.panTo([lat, lon]);
        } else if (state.renderMode === 'canvas' && canvasRenderer) {
            canvasRenderer.centerOnIndex(state.currentIndex);
        }
    }

    // uPlot Telemetry Chart Generation
    function initCharts(p) {
        if (!window.uPlot) return;

        const n = state.pointCount;
        const xs = p.elapsed_s || Array.from({ length: n }, (_, i) => i * 0.1);

        // 1. Altitude & Speed Profile Chart
        const altData = [
            xs,
            p.altitudes_agl || p.alt_agl || [],
            p.ground_speeds_mps || p.speed_h || []
        ];
        createOrUpdateChart('alt-speed', 'chart-container-alt-speed', {
            series: [
                {},
                { label: 'Alt AGL (m)', stroke: '#38bdf8' },
                { label: 'Speed (m/s)', stroke: '#10b981' }
            ]
        }, altData);

        // 2. Attitude Dynamics Chart
        const attData = [
            xs,
            p.pitches_deg || p.pitch || [],
            p.rolls_deg || p.roll || []
        ];
        createOrUpdateChart('attitude', 'chart-container-attitude', {
            series: [
                {},
                { label: 'Pitch (°)', stroke: '#f59e0b' },
                { label: 'Roll (°)', stroke: '#38bdf8' }
            ]
        }, attData);

        // 3. Battery Voltage & Current Chart
        const batData = [
            xs,
            (p.battery_voltages_mv || []).map(mv => mv / 1000.0),
            p.battery_current_a || []
        ];
        createOrUpdateChart('battery', 'chart-container-battery', {
            series: [
                {},
                { label: 'Pack Volts (V)', stroke: '#10b981' },
                { label: 'Current (A)', stroke: '#ef4444' }
            ]
        }, batData);

        // 4. RC Channels Chart
        const rcData = [
            xs,
            (p.rc_throttles || []).map(v => v * 100),
            (p.rc_elevators || []).map(v => v * 100),
            (p.rc_ailerons || []).map(v => v * 100),
            (p.rc_rudders || []).map(v => v * 100)
        ];
        createOrUpdateChart('rc', 'chart-container-rc', {
            series: [
                {},
                { label: 'Throttle %', stroke: '#38bdf8' },
                { label: 'Elevator %', stroke: '#f59e0b' },
                { label: 'Aileron %', stroke: '#60a5fa' },
                { label: 'Rudder %', stroke: '#10b981' }
            ]
        }, rcData);
    }

    function createOrUpdateChart(key, containerId, opts, data) {
        const container = document.getElementById(containerId);
        if (!container) return;

        if (charts[key]) {
            charts[key].setData(data);
        } else {
            container.innerHTML = '';
            opts.width = container.clientWidth || 800;
            opts.height = container.clientHeight || 170;
            charts[key] = new window.uPlot(opts, data, container);
        }
    }

    // High-Fidelity Synthetic Mission Generator (Instant local demo mode)
    function loadDemoFlight() {
        const pointCount = 1200; // 2 minutes at 10Hz
        const baseLat = 37.774900;
        const baseLon = -122.419400;
        const startUtc = Date.now() - 120000;

        const p = {
            count: pointCount,
            indices: [],
            elapsed_s: [],
            fly_time_s: [],
            timestamp_utc_ms: [],
            latitudes: [],
            longitudes: [],
            altitudes_agl: [],
            altitudes_msl: [],
            ground_speeds_mps: [],
            climb_rates_mps: [],
            pitches_deg: [],
            rolls_deg: [],
            yaws_deg: [],
            headings_deg: [],
            flight_modes: [],
            is_motor_on: [],
            gps_satellites: [],
            is_failsafe_active: [],
            battery_pcts: [],
            battery_voltages_mv: [],
            battery_temps_c: [],
            battery_current_a: [],
            cell_voltages_mv: [],
            rc_throttles: [],
            rc_rudders: [],
            rc_elevators: [],
            rc_ailerons: []
        };

        // Generate realistic DJI Mavic 3 waypoint lawnmower survey flight
        let currentAlt = 0;
        let currentLat = baseLat;
        let currentLon = baseLon;
        let currentHdg = 0;

        for (let i = 0; i < pointCount; i++) {
            const t = i * 0.1; // seconds
            p.indices.push(i);
            p.elapsed_s.push(t);
            p.fly_time_s.push(Math.max(0, t - 3.0));
            p.timestamp_utc_ms.push(startUtc + i * 100);

            // Flight Phases: 0-10s Takeoff Climb, 10-95s Waypoint Survey, 95-120s RTH & Touchdown
            let mode = 'P-GPS';
            let motorOn = t >= 2.0 && t <= 116.0;
            let spdH = 0;
            let spdV = 0;
            let pitch = 0;
            let roll = 0;
            let thr = 0;
            let rud = 0;
            let ele = 0;
            let ail = 0;

            if (t < 10.0) {
                // Vertical Ascent
                mode = 'TAKEOFF';
                currentAlt = (t / 10.0) * 45.0;
                spdV = 4.5;
                thr = 0.65;
            } else if (t < 95.0) {
                // Waypoint Survey Cruise at 45m
                mode = 'AUTO-WAYPOINT';
                currentAlt = 45.0 + Math.sin(t * 0.2) * 1.5;
                spdH = 8.5;
                const leg = Math.floor((t - 10.0) / 20.0);
                const legT = (t - 10.0) % 20.0;

                if (legT < 16.0) {
                    // Straight run
                    currentHdg = (leg % 2 === 0) ? 90 : 270;
                    roll = 0;
                    pitch = -6.5;
                    ele = 0.55;
                } else {
                    // Banking Turn
                    const turnProgress = (legT - 16.0) / 4.0;
                    roll = (leg % 2 === 0) ? 18.0 : -18.0;
                    currentHdg = (leg % 2 === 0) ? (90 + turnProgress * 180) : (270 + turnProgress * 180);
                    ail = (leg % 2 === 0) ? 0.45 : -0.45;
                    rud = (leg % 2 === 0) ? 0.35 : -0.35;
                }

                const rad = currentHdg * Math.PI / 180.0;
                currentLat += Math.cos(rad) * 0.000008;
                currentLon += Math.sin(rad) * 0.000010;
            } else if (t < 116.0) {
                // Return to Home & Landing
                mode = 'RTH-LAND';
                const descentProgress = (t - 95.0) / 21.0;
                currentAlt = Math.max(0, 45.0 * (1.0 - descentProgress));
                spdV = -2.2;
                thr = -0.4;
                currentLat += (baseLat - currentLat) * 0.05;
                currentLon += (baseLon - currentLon) * 0.05;
            } else {
                mode = 'LANDED';
                currentAlt = 0;
                motorOn = false;
            }

            p.latitudes.push(currentLat);
            p.longitudes.push(currentLon);
            p.altitudes_agl.push(currentAlt);
            p.altitudes_msl.push(currentAlt + 18.5);
            p.ground_speeds_mps.push(spdH);
            p.climb_rates_mps.push(spdV);
            p.pitches_deg.push(pitch);
            p.rolls_deg.push(roll);
            p.yaws_deg.push(currentHdg);
            p.headings_deg.push(currentHdg);
            p.flight_modes.push(mode);
            p.is_motor_on.push(motorOn);
            p.gps_satellites.push(19);
            p.is_failsafe_active.push(false);

            // Battery Discharge Curve (4S Battery Pack)
            const soc = Math.max(68, 98 - (t / 120.0) * 30);
            const currentA = motorOn ? (spdV > 2 ? 22.4 : (spdH > 5 ? 12.8 : 6.5)) : 0.8;
            const packMv = Math.round(16800 - (120 - soc) * 45 - (currentA * 15));
            const c1 = Math.round(packMv / 4 + (Math.sin(t) * 8));
            const c2 = Math.round(packMv / 4 - 5);
            const c3 = Math.round(packMv / 4 + 7);
            const c4 = Math.round(packMv / 4 - 2);

            p.battery_pcts.push(soc);
            p.battery_voltages_mv.push(packMv);
            p.battery_current_a.push(currentA);
            p.battery_temps_c.push(24.5 + (t / 120.0) * 8.2);
            p.cell_voltages_mv.push([c1, c2, c3, c4]);

            // RC Sticks
            p.rc_throttles.push(thr);
            p.rc_rudders.push(rud);
            p.rc_elevators.push(ele);
            p.rc_ailerons.push(ail);
        }

        const metadata = {
            aircraft_model: 'DJI Mavic 3 Enterprise',
            duration_seconds: 120.0,
            flight_duration_seconds: 114.0,
            total_distance_meters: 846.5,
            max_altitude_agl_m: 46.5,
            max_altitude_msl_m: 65.0,
            max_horizontal_speed_mps: 8.7,
            max_vertical_speed_mps: 4.5,
            home_latitude: baseLat,
            home_longitude: baseLon,
            total_records: pointCount
        };

        loadFlightData(metadata, p);
    }

    // WebSocket Synchronization
    function initWebSocket() {
        const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
        const wsUrl = `${protocol}//${window.location.host}/api/v1/ws`;

        try {
            state.ws = new WebSocket(wsUrl);

            state.ws.onopen = () => {
                state.wsConnected = true;
                if (elements.wsStatus) {
                    elements.wsStatus.textContent = 'SYNCED';
                    elements.wsStatus.className = 'status-indicator status-online';
                }
            };

            state.ws.onmessage = (event) => {
                try {
                    const msg = JSON.parse(event.data);
                    if ((msg.type === 'sync' || msg.type === 'frame') && msg.index !== undefined && msg.index !== state.currentIndex) {
                        seekToIndex(msg.index, 'remote');
                    } else if (msg.type === 'dataset_loaded') {
                        fetchFlightData();
                    } else if (msg.type === 'playback') {
                        if (msg.playing !== undefined && msg.playing !== state.isPlaying) {
                            state.isPlaying = msg.playing;
                            if (elements.btnPlayPause) {
                                elements.btnPlayPause.innerHTML = state.isPlaying
                                    ? '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>'
                                    : '<svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3"/></svg>';
                            }
                            if (state.isPlaying) {
                                state.lastFrameTime = performance.now();
                                requestAnimationFrame(playbackLoop);
                            }
                        }
                        if (msg.current_index !== undefined) {
                            seekToIndex(msg.current_index, 'remote');
                        }
                    }
                } catch (e) {}
            };

            state.ws.onclose = () => {
                state.wsConnected = false;
                if (elements.wsStatus) {
                    elements.wsStatus.textContent = 'STANDBY';
                    elements.wsStatus.className = 'status-indicator status-offline';
                }
                setTimeout(initWebSocket, 3000); // Reconnect loop
            };

            state.ws.onerror = () => {
                if (state.ws) state.ws.close();
            };
        } catch (e) {
            if (elements.wsStatus) {
                elements.wsStatus.textContent = 'STANDBY';
                elements.wsStatus.className = 'status-indicator status-offline';
            }
        }
    }

    function sendWsMessage(msg) {
        if (state.ws && state.ws.readyState === WebSocket.OPEN) {
            state.ws.send(JSON.stringify(msg));
        }
    }

    // File Upload Handling
    function handleFileUpload(e) {
        if (e.target.files && e.target.files.length > 0) {
            uploadLogFile(e.target.files[0]);
        }
    }

    async function uploadLogFile(file) {
        const formData = new FormData();
        formData.append('file', file);

        try {
            if (elements.hudAlertText) elements.hudAlertText.textContent = `Uploading and parsing ${file.name}...`;
            if (elements.hudAlert) elements.hudAlert.style.display = 'flex';

            const res = await fetch('/api/v1/upload', {
                method: 'POST',
                body: formData
            });

            if (res.ok) {
                if (elements.hudAlertText) elements.hudAlertText.textContent = `Successfully decoded ${file.name}`;
